INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 1, '出塞', 'yuefu-yf-28', '黄河远上白云间，一片孤城万仞山。
羌笛何须怨杨柳，春风不度玉门关。', '黄河远远地伸向白云之间，一座孤城坐落在万丈高山之中。羌笛何必吹起哀怨的《折杨柳》，春风吹不到玉门关外啊。', 'public-domain'),
  ('tangshi300', 2, '江南曲', 'tangshi-ts-91', '嫁得瞿塘贾，朝朝误妾期。
早知潮有信，嫁与弄潮儿。', '嫁给了一个瞿塘的商人，天天耽误我约定的归期。早知道潮水都有信用，不如嫁给那弄潮的少年。', 'public-domain'),
  ('tangshi300', 3, '从军行七首·其四', 'tangshi-ts-304', '青海长云暗雪山，孤城遥望玉门关。
黄沙百战穿金甲，不破楼兰终不还。', '青海湖上长云弥漫，遮暗了雪山，孤零零的城池远远望着玉门关。黄沙百战磨穿了身上的铠甲，不打败楼兰就绝不回还。', 'public-domain'),
  ('tangshi300', 4, '蜀道难', 'tangshi-ts-74', '噫吁嚱，危乎高哉！
蜀道之难，难于上青天！
蚕丛及鱼凫，开国何茫然。
尔来四万八千岁，不与秦塞通人烟。
西当太白有鸟道，可以横绝峨眉巅。
地崩山摧壮士死，然后天梯石栈相钩连。
上有六龙回日之高标，下有冲波逆折之回川。
黄鹤之飞尚不得过，猿猱欲度愁攀援。
青泥何盘盘，百步九折萦岩峦。
扪参历井仰胁息，以手抚膺坐长叹。
问君西游何时还，畏途巉岩不可攀。
但见悲鸟号古木，雄飞雌从绕林间。
又闻子规啼夜月，愁空山。
蜀道之难，难于上青天，使人听此凋朱颜。
连峰去天不盈尺，枯松倒挂倚绝壁。
飞湍瀑流争喧豗，砯崖转石万壑雷。
其险也如此，嗟尔远道之人胡为乎来哉。
剑阁峥嵘而崔嵬，一夫当关，万夫莫开。
所守或匪亲，化为狼与豺。
朝避猛虎，夕避长蛇。
磨牙吮血，杀人如麻。
锦城虽云乐，不如早还家。
蜀道之难，难于上青天，侧身西望长咨嗟。', '唉呀呀，多么危险多么高峻！蜀道的艰难，比上青天还难！蚕丛和鱼凫开国的年代多么遥远茫昧。从那时以来四万八千年，不与秦地互通人烟。西面对着太白山只有鸟飞的路径，可以横越峨眉山顶。山崩地裂壮士死去，然后才有天梯石栈互相钩连。上面有六龙驾日都要回旋的高峰，下面有波涛冲击、回旋倒流的河川。黄鹤高飞尚且飞不过去，猿猱想过也愁于攀援。青泥岭多么曲折，百步之内九次折转萦绕着山峦。手摸参星、身历井宿，仰头屏息，抚胸而坐、长声叹息。问你西游何时回来，可怕的道路、险峻的山岩不可攀登。只见悲鸟在古木上号叫，雄飞雌随绕在林间。又听见子规在月夜里啼叫，愁满空山。蜀道的艰难，比上青天还难，使人听了这消息都容颜憔悴。连绵的山峰离天不到一尺，枯松倒挂着倚在绝壁上。飞流瀑布争相喧腾，撞击山崖、转动巨石，万壑轰鸣如雷。它如此险要，可叹你这远道之人为什么到这里来呢。剑阁峥嵘而高峻，一人把关，万人也攻不开。守关的若不是亲信，就会变成豺狼。早上要躲避猛虎，晚上要躲避长蛇。它们磨牙吸血，杀人如麻。锦城虽说快乐，不如早些回家。蜀道的艰难，比上青天还难，侧身向西望去，长声叹息。', 'academic'),
  ('tangshi300', 5, '长干曲四首', 'tangshi-ts-92', '君家何处住，妾住在横塘。
停船暂借问，或恐是同乡。
家临九江水，来去九江侧。
同是长干人，生小不相识。', '你家住在哪里？我家住在横塘。停下船来请问一声，恐怕咱们还是同乡。
我家临着九江的水，来往都在九江边上。同是长干里人，从小却不相识。', 'public-domain'),
  ('tangshi300', 6, '玉阶怨', 'tangshi-ts-93', '玉阶生白露，夜久侵罗袜。
却下水晶帘，玲珑望秋月。', '玉石台阶上生出白露，夜深了露水浸湿了罗袜。只好放下水晶帘，隔着玲珑的帘子望着秋月。', 'public-domain'),
  ('tangshi300', 7, '子夜吴歌·秋歌', 'tangshi-ts-64', '长安一片月，万户捣衣声。
秋风吹不尽，总是玉关情。
何日平胡虏，良人罢远征。', '长安城上一片月光，千家万户传来捣衣的声音。秋风吹也吹不尽，那都是思念玉门关外的情意。什么时候才能平定胡虏，让丈夫停止远征。', 'public-domain'),
  ('tangshi300', 8, '列女操', 'tangshi-ts-66', '梧桐相待老，鸳鸯会双死。
贞妇贵殉夫，舍生亦如此。
波澜誓不起，妾心井中水。', '梧桐相伴到老，鸳鸯双双同死。贞洁的妇人贵在能为丈夫殉节，舍生也是如此。发誓心不再起波澜，我的心就像井中的水。', 'public-domain'),
  ('tangshi300', 9, '长相思·其一', 'tangshi-ts-75', '长相思，在长安。
络纬秋啼金井阑，微霜凄凄簟色寒。
孤灯不明思欲绝，卷帷望月空长叹。
美人如花隔云端。
上有青冥之长天，下有渌水之波澜。
天长路远魂飞苦，梦魂不到关山难。
长相思，摧心肝。', '长相思啊，在长安。纺织娘在秋天啼叫在金井栏边，薄霜凄凄竹席生寒。孤灯不明思念欲绝，卷起帐幕望月空自长叹。美人生得像花却隔在云端。上面有青苍的长天，下面有清澈的水波。天长路远魂魄飞得辛苦，梦魂也飞不过关山重重。长相思，摧人心肝。', 'public-domain'),
  ('tangshi300', 10, '长相思·其二', 'tangshi-ts-76', '日色欲尽花含烟，月明如素愁不眠。
赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。
此曲有意无人传，愿随春风寄燕然。
忆君迢迢隔青天。
昔时横波目，今作流泪泉。
不信妾肠断，归来看取明镜前。', '日色将尽、花含着烟霭，月色如白练、愁得睡不着。赵地的瑟刚停在凤凰柱上，蜀地的琴想奏响鸳鸯弦。这支曲子里含着情意却无人传达，愿随着春风寄到燕然。思念你，迢迢隔着青天。从前流转如波的眼睛，如今成了流泪的泉。你若不信我肝肠寸断，回来看一看明镜前我的容颜。', 'public-domain'),
  ('tangshi300', 11, '行路难·其一', 'poems-cz9-07', '金樽清酒斗十千，玉盘珍羞直万钱。
停杯投箸不能食，拔剑四顾心茫然。
欲渡黄河冰塞川，将登太行雪满山。
闲来垂钓碧溪上，忽复乘舟梦日边。
行路难！行路难！多歧路，今安在？
长风破浪会有时，直挂云帆济沧海。', '金杯里的清酒一斗价值十千，玉盘里的珍贵菜肴价值万钱。我却停下酒杯、丢下筷子，吃不下去，拔出宝剑，环顾四周，心里一片茫然。想要渡过黄河，冰却堵塞了河道；将要登上太行山，大雪却堆满了山。闲来在碧溪上垂钓，忽然又梦见乘船经过太阳旁边。行路难啊，行路难！岔路这么多，如今我又身在何处？总有一天能乘长风破万里浪，直挂起高帆渡过苍茫大海。', 'academic'),
  ('tangshi300', 12, '长干行二首', 'tangshi-ts-92', '君家何处住，妾住在横塘。
停船暂借问，或恐是同乡。
家临九江水，来去九江侧。
同是长干人，生小不相识。', '你家住在哪里，我家住在横塘。停下船来相问，恐怕我们还是同乡。我家临着九江的水，来往都在九江边上。同是长干里人，从小却不相识。', 'public-domain'),
  ('tangshi300', 13, '长干行', 'tangshi-ts-65', '妾发初覆额，折花门前剧。
郎骑竹马来，绕床弄青梅。
同居长干里，两小无嫌猜。
十四为君妇，羞颜未尝开。
低头向暗壁，千唤不一回。
十五始展眉，愿同尘与灰。
常存抱柱信，岂上望夫台。
十六君远行，瞿塘滟滪堆。
五月不可触，猿声天上哀。
门前迟行迹，一一生绿苔。
苔深不能扫，落叶秋风早。
八月蝴蝶黄，双飞西园草。
感此伤妾心，坐愁红颜老。
早晚下三巴，预将书报家。
相迎不道远，直至长风沙。', '我的头发刚盖住额头，折了花在门前玩耍。你骑着竹马跑来，绕着床榻摆弄青梅。同住在长干里，两个小孩没有猜嫌。十四岁做了你的妻子，羞怯的脸色还没有展开。低着头对着暗墙，叫上千遍也不回一次头。十五岁才舒展眉头，愿与你同生共死。常怀着抱柱那样守信的信念，哪里会登上望夫台。十六岁你远行去了，要过瞿塘的滟滪堆。五月水涨不能碰，猿声从天上传来阵阵哀鸣。门前你离去时的脚印，一个个都长满青苔。青苔长得深了扫不掉，落叶飘下秋风来得早。八月蝴蝶飞来，双双飞在西园的草丛。见此情景我心中悲伤，坐着发愁红颜老去。什么时候你从三巴下来，事先写封信报个信回家。我去迎接不怕路远，一直走到长风沙。', 'public-domain'),
  ('tangshi300', 14, '独不见', 'tangshi-ts-83', '卢家少妇郁金堂，海燕双栖玳瑁梁。
九月寒砧催木叶，十年征戍忆辽阳。
白狼河北音书断，丹凤城南秋夜长。
谁为含愁独不见，更教明月照流黄。', '卢家少妇住在郁金香熏的堂屋里，海燕双双栖息在玳瑁装饰的梁上。九月里寒砧声催落树叶，十年的征战戍守令人思念辽阳。白狼河北书信断绝，丹凤城南的秋夜漫长。是谁让这含愁的人独自不见，又让明月照着她机上的流黄锦。', 'public-domain'),
  ('tangshi300', 15, '送李少府贬峡中王少府贬长沙', 'tangshi-ts-179', '嗟君此别意何如，驻马衔杯问谪居。
巫峡啼猿数行泪，衡阳归雁几封书。
青枫江上秋帆远，白帝城边古木疏。
圣代即今多雨露，暂时分手莫踌躇。', '唉，你们这一别心情如何，勒住马、举着杯询问贬谪的去处。巫峡的猿啼催人落下几行泪，衡阳的归雁可捎回几封书信。青枫江上秋帆远去，白帝城边古木稀疏。圣明的时代如今多有雨露之恩，暂时分手不必迟疑。', 'public-domain'),
  ('tangshi300', 16, '望岳', 'poems-cz7-19', '岱宗夫如何？齐鲁青未了。
造化钟神秀，阴阳割昏晓。
荡胸生曾云，决眦入归鸟。
会当凌绝顶，一览众山小。', '泰山到底怎么样呢？在齐鲁大地上，那青翠的山色望不到尽头。大自然把神奇和秀美都聚集在这里，山南和山北被分割成明亮和昏暗两面。望着层层云气升腾，心胸激荡；睁大眼睛看着归巢的鸟儿飞入山中。一定要登上泰山的顶峰，那时俯瞰群山，都会显得渺小。', 'academic'),
  ('tangshi300', 17, '兵车行', 'tangshi-ts-79', '车辚辚，马萧萧，行人弓箭各在腰。
爷娘妻子走相送，尘埃不见咸阳桥。
牵衣顿足拦道哭，哭声直上干云霄。
道旁过者问行人，行人但云点行频。
或从十五北防河，便至四十西营田。
去时里正与裹头，归来头白还戍边。
边庭流血成海水，武皇开边意未已。
君不闻汉家山东二百州，千村万落生荆杞。
纵有健妇把锄犁，禾生陇亩无东西。
况复秦兵耐苦战，被驱不异犬与鸡。
长者虽有问，役夫敢申恨。
且如今年冬，未休关西卒。
县官急索租，租税从何出。
信知生男恶，反是生女好。
生女犹得嫁比邻，生男埋没随百草。
君不见，青海头，古来白骨无人收。
新鬼烦冤旧鬼哭，天阴雨湿声啾啾。', '车辆辚辚作响，马匹萧萧嘶鸣，出征的人弓箭各自挂在腰间。爹娘妻子跑来相送，尘埃弥漫、看不见咸阳桥。牵着衣裳、跺着脚拦路痛哭，哭声直冲云霄。路旁经过的人询问出征的人，出征的人只说征兵频繁。有的十五岁就去北边防守黄河，到了四十岁还在西边屯田。去时里正给他裹头，回来头发白了还要戍边。边庭流血成海水，武帝开拓边地的心意还没有停止。你没听说汉家山东二百州，千村万落都长满了荆棘杞柳。纵然有健壮的妇人拿着锄犁，庄稼长在田里也分不清东西行列。何况秦地的兵耐得苦战，被驱赶得与狗鸡没有两样。长者虽然发问，役夫怎敢申诉怨恨。就像今年冬天，关西的兵卒还没有休整。县官急着催租，租税从哪里出。确实知道生男孩不好，反倒是生女孩好。生女孩还能嫁给近邻，生男孩就埋没在荒草之中。你没看见吗，青海边上，古来白骨无人收殓。新鬼含冤、旧鬼啼哭，天阴雨湿时哭声啾啾。', 'public-domain'),
  ('tangshi300', 18, '赠卫八处士', 'tangshi-ts-7', '人生不相见，动如参与商。
今夕复何夕，共此灯烛光。
少壮能几时，鬓发各已苍。
访旧半为鬼，惊呼热中肠。
焉知二十载，重上君子堂。
昔别君未婚，儿女忽成行。
怡然敬父执，问我来何方。
问答未及已，驱儿罗酒浆。
夜雨剪春韭，新炊间黄粱。
主称会面难，一举累十觞。
十觞亦不醉，感子故意长。
明日隔山岳，世事两茫茫。', '人生难得相见，动辄就像参星与商星一样此出彼没。今晚是什么好日子，竟能与你共对这灯烛之光。少年壮年能有几时，如今我们两鬓都已斑白。打探故旧，多半已成了鬼，令人惊呼叫喊，心中火热难平。哪里想到过了二十年，我又重新登上你的厅堂。当年分别时你还没结婚，如今儿女忽已成行。他们和悦地敬重父亲的挚友，问我从哪里来。问答还没完，你就催着儿女摆上酒菜。冒着夜雨去剪来春韭，刚煮好的饭里掺着黄粱。你说见面实在太难，一举杯就接连喝了十大杯。十杯也不觉得醉，是感念你情意深长。明天就要隔开重重山岳，世事茫茫，谁也难料。', 'public-domain'),
  ('tangshi300', 19, '丽人行', 'tangshi-ts-80', '三月三日天气新，长安水边多丽人。
态浓意远淑且真，肌理细腻骨肉匀。
绣罗衣裳照暮春，蹙金孔雀银麒麟。
头上何所有，翠微盍叶垂鬓唇。
背后何所见，珠压腰衱稳称身。
就中云幕椒房亲，赐名大国虢与秦。
紫驼之峰出翠釜，水精之盘行素鳞。
犀箸厌饫久未下，鸾刀缕切空纷纶。
黄门飞鞚不动尘，御厨络绎送八珍。
箫鼓哀吟感鬼神，宾从杂遝实要津。
后来鞍马何逡巡，当轩下马入锦茵。
杨花雪落覆白苹，青鸟飞去衔红巾。
炙手可热势绝伦，慎莫近前丞相嗔。', '三月三日天气清新，长安水边有许多美人。姿态秾丽、情意高远，娴淑而自然，肌肤细腻、骨肉匀称。绣罗衣裳映着暮春，用金线绣孔雀、银线绣麒麟。头上有什么，翠羽的叶饰垂到鬓边唇畔。背后见到什么，珍珠压着腰裙、十分合身。其中有云幕椒房的外戚，被赐封为虢国与秦国夫人。紫驼峰从翠釜中取出，水晶盘里盛着细切的鱼。犀角筷子吃腻了久久不下箸，鸾刀细切却空自纷忙。黄门飞马而来不扬尘土，御厨络绎不绝地送来八珍。箫鼓哀吟感动鬼神，宾客随从杂乱众多，都是权要之人。后来鞍马何等逡巡，到轩前下马走进锦茵。杨花如雪落下覆盖白苹，青鸟飞去衔来红巾。气焰炙手可热、势位无与伦比，千万不要靠近，免得丞相发怒。', 'public-domain'),
  ('tangshi300', 20, '哀江头', 'tangshi-ts-81', '少陵野老吞声哭，春日潜行曲江曲。
江头宫殿锁千门，细柳新蒲为谁绿。
忆昔霓旌下南苑，苑中万物生颜色。
昭阳殿里第一人，同辇随君侍君侧。
辇前才人带弓箭，白马嚼啮黄金勒。
翻身向天仰射云，一笑正坠双飞翼。
明眸皓齿今何在，血污游魂归不得。
清渭东流剑阁深，去住彼此无消息。
人生有情泪沾臆，江水江花岂终极。
黄昏胡骑尘满城，欲往城南望城北。', '我少陵野老吞声哭泣，春日里悄悄走在曲江的曲处。江头的宫殿千门紧锁，细柳新蒲为谁而绿。回忆从前霓旌来到南苑，苑中万物都生出颜色。昭阳殿里第一美人，与君王同辇、侍奉在君王身边。辇前的才人带着弓箭，白马咬着黄金勒。翻身向天仰射云中，一笑之间正好射落双飞的鸟。那明眸皓齿如今在哪里，血污了游魂、回不来了。清渭东流、剑阁深远，去的和留的彼此都没有消息。人生有情、泪水沾胸，江水江花岂有尽头。黄昏胡骑扬尘满城，我想去城南却望着城北。', 'public-domain'),
  ('tangshi300', 21, '哀王孙', 'tangshi-ts-82', '长安城头头白乌，夜飞延秋门上呼。
又向人家啄大屋，屋底达官走避胡。
金鞭断折九马死，骨肉不得同驰驱。
腰下宝玦青珊瑚，可怜王孙泣路隅。
问之不肯道姓名，但道困苦乞为奴。
已经百日窜荆棘，身上无有完肌肤。
高帝子孙尽隆准，龙种自与常人殊。
豺狼在邑龙在野，王孙善保千金躯。
不敢长语临交衢，且为王孙立斯须。
昨夜东风吹血腥，东来橐驼满旧都。
朔方健儿好身手，昔何勇锐今何愚。
窃闻天子已传位，圣德北服南单于。
花门剺面请雪耻，慎勿出口他人狙。
哀哉王孙慎勿疏，五陵佳气无时无。', '长安城头有白头乌鸦，夜里飞到延秋门上呼号。又向人家啄食大屋，屋下的达官逃走躲避胡人。金鞭折断、九马死去，骨肉不能一同奔驰。腰下挂着宝玦和青珊瑚，可怜王孙在路旁哭泣。问他却不肯说出姓名，只说困苦、乞求做奴。已经有一百天躲藏在荆棘里，身上没有一处完好的肌肤。高帝的子孙都是高鼻，龙种自然与常人不同。豺狼在城里、真龙在野外，王孙你要好好保重千金之躯。不敢在十字路口与你长谈，姑且为王孙稍立片刻。昨夜东风吹来血腥，东来的骆驼挤满旧都。朔方的健儿身手好，从前何等勇锐如今何等愚拙。私下听说天子已经传位，圣德向北使南单于归服。回纥人割面请求雪耻，千万不要说出口、免得他人窥伺。可叹啊王孙你要小心不要疏忽，五陵的佳气无时不在。', 'public-domain'),
  ('tangshi300', 22, '佳人', 'tangshi-ts-8', '绝代有佳人，幽居在空谷。
自云良家子，零落依草木。
关中昔丧乱，兄弟遭杀戮。
官高何足论，不得收骨肉。
世情恶衰歇，万事随转烛。
夫婿轻薄儿，新人美如玉。
合昏尚知时，鸳鸯不独宿。
但见新人笑，那闻旧人哭。
在山泉水清，出山泉水浊。
侍婢卖珠回，牵萝补茅屋。
摘花不插发，采柏动盈掬。
天寒翠袖薄，日暮倚修竹。', '有一位举世无双的美人，幽居在空寂的山谷里。她说自己本是好人家的女儿，如今流落零落，依傍着草木生活。当年关中遭遇战乱，兄弟都被杀害。官位再高又有什么用，连亲人的尸骨都无法收殓。世态人情厌恶衰落，万事都像转动的烛焰一样变化无常。丈夫是个轻薄的人，新娶的妻子美如白玉。合欢花尚且懂得按时开合，鸳鸯也不会独自过夜。可只见新人欢笑，哪听得见旧人哭泣。山中的泉水是清的，流出山来就浑浊了。侍女卖掉首饰回来，牵着藤萝修补茅屋。摘下花来却不插在发间，采柏树枝叶常常采满一把。天冷了翠袖单薄，黄昏时她倚着高高的竹子。', 'public-domain'),
  ('tangshi300', 23, '梦李白·其一', 'tangshi-ts-9', '死别已吞声，生别常恻恻。
江南瘴疠地，逐客无消息。
故人入我梦，明我长相忆。
恐非平生魂，路远不可测。
魂来枫林青，魂返关塞黑。
今君在罗网，何以有羽翼。
落月满屋梁，犹疑照颜色。
水深波浪阔，无使蛟龙得。', '死别已叫人泣不成声，生离则常常令人心中悲凄。江南是瘴疠横行的地方，被放逐的你一直没有消息。老朋友进入我的梦中，是知道我常常把你思念。恐怕这不是你生前的魂魄，路途遥远难以测度。魂魄来时枫林青翠，魂魄离去时关塞昏黑。如今你正陷在罗网之中，怎么还能长出翅膀飞来。西沉的月光洒满屋梁，我还疑心它照着你的容颜。江水深波浪阔，千万不要让蛟龙把你攫去。', 'public-domain'),
  ('tangshi300', 24, '梦李白·其二', 'tangshi-ts-10', '浮云终日行，游子久不至。
三夜频梦君，情亲见君意。
告归常局促，苦道来不易。
江湖多风波，舟楫恐失坠。
出门搔白首，若负平生志。
冠盖满京华，斯人独憔悴。
孰云网恢恢，将老身反累。
千秋万岁名，寂寞身后事。', '浮云整日飘行，远游的人却久久不来。连续三夜频频梦见你，可见你我情谊深厚、你也有此心意。告辞时你总是神情局促，苦苦诉说前来的不易。江湖上风波险恶，你担心船只会失事沉没。出门时你搔着满头白发，像是辜负了平生的壮志。京城里满是高冠华盖的显贵，唯独你这样的人才如此憔悴。谁说天网恢恢、善恶有报，你将近老年反而身遭牵累。千秋万岁的名声，不过是寂寞的身后之事罢了。', 'public-domain'),
  ('tangshi300', 25, '韦讽录事宅观曹将军画马图', 'tangshi-ts-47', '国初已来画鞍马，神妙独数江都王。
将军得名三十载，人间又见真乘黄。
曾貌先帝照夜白，龙池十日飞霹雳。
内府殷红玛瑙盘，婕妤传诏才人索。
盘赐将军拜舞归，轻纨细绮相追飞。
贵戚权门得笔迹，始觉屏障生光辉。
昔日太宗拳毛騧，近时郭家狮子花。
今之新图有二马，复令识者久叹嗟。
此皆骑战一敌万，缟素漠漠开风沙。
其余七匹亦殊绝，迥若寒空动烟雪。
霜蹄蹴踏长楸间，马官厮养森成列。
可怜九马争神骏，顾视清高气深稳。
借问苦心爱者谁，后有韦讽前支遁。
忆昔巡幸新丰宫，翠华拂天来向东。
腾骧磊落三万匹，皆与此图筋骨同。
自从献宝朝河宗，无复射蛟江水中。
君不见金粟堆前松柏里，龙媒去尽鸟呼风。', '开国以来画鞍马的名家，神妙首推江都王。曹将军成名三十年，人间又见到真正神骏的良马。他曾画先帝的照夜白，龙池上十日雷鸣电闪。内府里深红的玛瑙盘，婕妤传旨、才人来索取。盘子赐给将军，他拜舞而回，轻薄细软的绫罗追着送来。贵戚权门得到他的墨迹，才觉得屏风生了光辉。从前太宗的拳毛騧，近时郭家的狮子花。如今这幅新图上有两匹马，又让识马的人久久叹赏。这些都是奔驰征战、以一敌万的骏马，白绢上仿佛漠漠扬起风沙。其余七匹也非常出色，远远望去像寒空中飘动的烟雪。霜白的马蹄踏过长楸之间，马官和马夫密密麻麻排成行列。可爱的九匹马争显神骏，顾盼清高、气度深沉稳健。请问苦心爱马的是谁？后有韦讽，前有支遁。回忆当年圣上巡幸新丰宫，翠羽华盖拂天向东而来。腾跃奔放的三万匹马，筋骨都与这图上的马相同。自从献宝朝见河宗之后，再也不见在江水中射蛟。你没看见吗，金粟堆前的松柏里，骏马都已离去，只有鸟儿在风中呼叫。', 'public-domain'),
  ('tangshi300', 26, '丹青引赠曹将军霸', 'tangshi-ts-48', '将军魏武之子孙，于今为庶为清门。
英雄割据虽已矣，文采风流今尚存。
学书初学卫夫人，但恨无过王右军。
丹青不知老将至，富贵于我如浮云。
开元之中常引见，承恩数上南薰殿。
凌烟功臣少颜色，将军下笔开生面。
良相头上进贤冠，猛将腰间大羽箭。
褒公鄂公毛发动，英姿飒爽来酣战。
先帝御马玉花骢，画工如山貌不同。
是日牵来赤墀下，迥立阊阖生长风。
诏谓将军拂绢素，意匠惨淡经营中。
斯须九重真龙出，一洗万古凡马空。
玉花却在御榻上，榻上庭前屹相向。
至尊含笑催赐金，圉人太仆皆惆怅。
弟子韩幹早入室，亦能画马穷殊相。
幹惟画肉不画骨，忍使骅骝气凋丧。
将军善画盖有神，必逢佳士亦写真。
即今漂泊干戈际，屡貌寻常行路人。
途穷反遭俗眼白，世上未有如公贫。
但看古来盛名下，终日坎壈缠其身。', '曹将军是魏武帝曹操的后代，如今却成了平民百姓、清贫之家。英雄割据的时代虽然已经过去，曹家的文采风流如今还留存着。你学书法最初学卫夫人，只恨没能超过王右军。你专心绘画，不知老年将至，把富贵看得如浮云一般。开元年间你常被引见，承蒙恩宠多次登上南薰殿。凌烟阁的功臣画像已色彩暗淡，将军下笔便另开生面。良相头上戴上进贤冠，猛将腰间佩着大羽箭。褒国公、鄂国公画像上须发都能飘动，英姿飒爽像要前来酣战。先帝的御马玉花骢，画工多如山却画得各不相同。那天牵到殿前红阶下，昂然独立，宫门间顿生长风。下诏叫将军展开白绢，构思时惨淡经营。片刻间九重天上下凡来了真龙，把万古以来的凡马一扫而空。玉花骢仿佛就在御榻之上，榻上与庭前的马屹然相对。皇上含笑催促赐金，马夫、太仆都感到惆怅。你的弟子韩幹早已登堂入室，也能画马穷尽各种形态。但韩幹只画肉不画骨，竟让骏马的神气凋丧。将军善于画马，大概是有神助，遇到佳士也一定为之写真。如今你在战乱中漂泊，常常画些寻常的路人。途穷反而遭世俗的白眼，世上没有像你这样困顿的人。只看古来有盛名的人，往往终生坎坷缠身。', 'public-domain'),
  ('tangshi300', 27, '寄韩谏议注', 'tangshi-ts-49', '今我不乐思岳阳，身欲奋飞病在床。
美人娟娟隔秋水，濯足洞庭望八荒。
鸿飞冥冥日月白，青枫叶赤天雨霜。
玉京群帝集北斗，或骑麒麟翳凤凰。
芙蓉旌旗烟雾落，影动倒景摇潇湘。
星宫之君醉琼浆，羽人稀少不在旁。
似闻昨者赤松子，恐是汉代韩张良。
昔随刘氏定长安，帷幄未改神惨伤。
国家成败吾岂敢，色难腥腐餐枫香。
周南留滞古所惜，南极老人应寿昌。
美人胡为隔秋水，焉得置之贡玉堂。', '如今我闷闷不乐，思念起岳阳，身想奋飞却病倒在床。我所思念的人风姿美好，隔着秋水，在洞庭湖里洗足，遥望八方。鸿雁飞入高远的天空，日月洁白，青枫叶红，天上降霜。玉京的群帝聚集在北斗，有的骑着麒麟，有的驾着凤凰。芙蓉装饰的旌旗在烟雾中飘落，倒影摇动潇湘。星宫的神君醉饮琼浆，羽人稀少不在身旁。似乎听说从前的赤松子，恐怕就是汉代的韩张良。当年你跟随刘氏平定长安，运筹帷幄忠心未改却神情惨伤。国家的成败我哪敢妄议，只是看不惯腥腐之气，宁可餐食枫香。滞留周南是古人所惋惜的，南极老人星应当长寿昌盛。我思念的人啊为何隔着秋水，怎样才能把你安置到朝廷之上。', 'public-domain'),
  ('tangshi300', 28, '古柏行', 'tangshi-ts-50', '孔明庙前有老柏，柯如青铜根如石。
霜皮溜雨四十围，黛色参天二千尺。
君臣已与时际会，树木犹为人爱惜。
云来气接巫峡长，月出寒通雪山白。
忆昨路绕锦亭东，先主武侯同閟宫。
崔嵬枝干郊原古，窈窕丹青户牖空。
落落盘踞虽得地，冥冥孤高多烈风。
扶持自是神明力，正直原因造化功。
大厦如倾要梁栋，万牛回首丘山重。
不露文章世已惊，未辞剪伐谁能送。
苦心岂免容蝼蚁，香叶终经宿鸾凤。
志士幽人莫怨嗟，古来材大难为用。', '孔明庙前有一株老柏，枝干如青铜、根如磐石。皮色如霜、沾雨溜滑，粗有四十围；深青的树色参天，高达二千尺。君臣已与时代际会相合，树木尚且为人们所爱惜。云气飘来与巫峡的云气相连，月亮升起寒气通到雪山的洁白。回忆从前路过锦亭东边，先主刘备与武侯诸葛亮同在一座祠庙里。枝干高峻，郊野一片古意；幽深的彩绘，门窗却已空寂。孤傲地盘踞虽然得到了好地方，但孤高幽暗却多受烈风。能扶持它本是神明的力量，它的正直原出于造化的功效。大厦如果倾危就需要梁栋，但它重如山丘，万头牛也拉不动。不显露纹彩已使世人惊叹，不辞砍伐又有谁能运送。苦心经营岂能免于蝼蚁侵蚀，芳香的树叶终究经得起鸾凤栖宿。志士幽人不要怨叹，自古以来大材总是难以被任用。', 'public-domain'),
  ('tangshi300', 29, '观公孙大娘弟子舞剑器行·并序', 'tangshi-ts-51', '大历二年十月十九日，夔府别驾元持宅，见临颍李十二娘舞剑器，壮其蔚跂，问其所师，曰：「余公孙大娘弟子也。」开元三载，余尚童稚，记于郾城观公孙氏舞剑器浑脱，浏漓顿挫，独出冠时。自高头宜春、梨园二伎坊内人，洎外供奉舞女，晓是舞者，圣文神武皇帝初，公孙一人而已。玉貌锦衣，况余白首；今兹弟子，亦匪盛颜。既辨其由来，知波澜莫二。抚事慷慨，聊为《剑器行》。昔者吴人张旭善草书书帖，数尝于邺县见公孙大娘舞西河剑器，自此草书长进，豪荡感激，即公孙可知矣。
昔有佳人公孙氏，一舞剑器动四方。
观者如山色沮丧，天地为之久低昂。
耀如羿射九日落，矫如群帝骖龙翔。
来如雷霆收震怒，罢如江海凝清光。
绛唇珠袖两寂寞，晚有弟子传芬芳。
临颍美人在白帝，妙舞此曲神扬扬。
与余问答既有以，感时抚事增惋伤。
先帝侍女八千人，公孙剑器初第一。
五十年间似反掌，风尘澒洞昏王室。
梨园弟子散如烟，女乐余姿映寒日。
金粟堆南木已拱，瞿唐石城草萧瑟。
玳筵急管曲复终，乐极哀来月东出。
老夫不知其所往，足茧荒山转愁疾。', '大历二年十月十九日，我在夔州别驾元持的宅第里，看见临颍李十二娘舞《剑器》，赞叹她舞姿雄壮，问她师从何人，她说：「我是公孙大娘的弟子。」开元三年，我还年幼，记得在郾城看过公孙大娘舞《剑器》《浑脱》，舞姿淋漓顿挫，独冠当时。自从高头宜春、梨园两处教坊的宫人，以及外供奉的舞女，懂得这支舞的，在圣文神武皇帝初年，只有公孙大娘一人而已。她当年玉貌锦衣，何况如今我已白头；现在她的弟子，也已不是盛年容颜。既已辨明她的来历，知道舞艺的波澜与师承并无二致。抚今追昔，感慨万千，姑且作这首《剑器行》。从前吴人张旭善写草书，多次在邺县看公孙大娘舞西河《剑器》，从此草书大进，豪放激昂，由此可以推想公孙大娘的舞艺了。

从前有位佳人公孙氏，一舞《剑器》就震动四方。看的人多如山，个个神色沮丧，天地也为她久久地起伏低昂。剑光闪亮如后羿射落九日，身姿矫健如群帝驾龙翱翔。起舞时如雷霆收敛了震怒，收舞时如江海凝结了清光。绛唇珠袖都已寂寥，晚年幸有弟子传承她的芬芳。临颍的美人在白帝城，跳起这支曲子神采飞扬。她与我一问一答已明来历，感时抚事更添惋惜悲伤。先帝的侍女有八千人，公孙大娘的《剑器》当初数第一。五十年间快得像反掌，战乱弥漫、王室昏暗。梨园弟子如烟散去，女乐的余姿映着寒日。金粟堆南的树木已经合抱，瞿唐石城一片草木萧瑟。玳瑁筵席上急管繁弦一曲又终，乐极生悲，月亮从东方升起。我这老夫不知该往哪里去，脚上磨出茧子在荒山里转，愁苦更深。', 'public-domain'),
  ('tangshi300', 30, '月夜', 'tangshi-ts-110', '今夜鄜州月，闺中只独看。
遥怜小儿女，未解忆长安。
香雾云鬟湿，清辉玉臂寒。
何时倚虚幌，双照泪痕干。', '今夜鄜州的月亮，只有你在闺中独自观看。遥想可怜的小儿女，还不懂得思念长安。香雾沾湿了你的云鬓，清冷的月光使你的玉臂生寒。什么时候才能一同倚在薄帷上，让月光双双照干我们的泪痕。', 'public-domain'),
  ('tangshi300', 31, '春望', 'tangshi-ts-111', '国破山河在，城春草木深。
感时花溅泪，恨别鸟惊心。
烽火连三月，家书抵万金。
白头搔更短，浑欲不胜簪。', '国都沦陷山河依旧，城中春天草木深深。感伤时局，看见花也落泪；痛恨离别，听见鸟叫也心惊。战火连着几个月，一封家书抵得上万两黄金。白发越搔越短，简直要插不住簪子。', 'public-domain'),
  ('tangshi300', 32, '至德二载甫自京金光门出问道归凤翔乾元初从左拾遗移华州掾与亲故别因出此门有悲往事', 'tangshi-ts-113', '此道昔归顺，西郊胡正繁。
至今残破胆，应有未招魂。
近得归京邑，移官岂至尊。
无才日衰老，驻马望千门。', '这条路当年是我归顺朝廷时走过的，那时西郊的胡人正多。至今还心惊胆战，应当有未招回的魂魄。近来得以回到京城，调任外官岂是皇上的本意。我没有才能又日渐衰老，勒住马遥望那千门万户。', 'public-domain'),
  ('tangshi300', 33, '月夜忆舍弟', 'tangshi-ts-114', '戍鼓断人行，边秋一雁声。
露从今夜白，月是故乡明。
有弟皆分散，无家问死生。
寄书长不达，况乃未休兵。', '戍楼的更鼓断绝了人们的来往，边塞的秋天传来一只大雁的叫声。从今夜起就进入白露节气，月亮还是故乡的最明亮。虽有兄弟但都已离散，没有家可以打听他们的生死。寄出的书信常常不能送到，何况战乱还没有停止。', 'academic'),
  ('tangshi300', 34, '天末怀李白', 'tangshi-ts-115', '凉风起天末，君子意如何。
鸿雁几时到，江湖秋水多。
文章憎命达，魑魅喜人过。
应共冤魂语，投诗赠汨罗。', '凉风从天边吹起，你的心境如何呢。鸿雁什么时候才能把信带到，江湖上秋水正多。文章总是憎恶命运通达的人，魑魅喜欢别人有过失。你应当与那冤魂共语，把诗投入汨罗江赠给屈原。', 'public-domain'),
  ('tangshi300', 35, '蜀相', 'tangshi-ts-186', '丞相祠堂何处寻，锦官城外柏森森。
映阶碧草自春色，隔叶黄鹂空好音。
三顾频烦天下计，两朝开济老臣心。
出师未捷身先死，长使英雄泪满襟。', '丞相的祠堂到哪里去寻找，锦官城外柏树森森。映着台阶的碧草空自呈着春色，隔着树叶的黄鹂徒然叫着好音。三顾茅庐频频询问天下大计，两朝开济、尽老臣之心。出师未捷而身先死去，常使英雄泪满衣襟。', 'public-domain'),
  ('tangshi300', 36, '客至', 'poems-gz11-20', '舍南舍北皆春水，但见群鸥日日来。
花径不曾缘客扫，蓬门今始为君开。
盘飧市远无兼味，樽酒家贫只旧醅。
肯与邻翁相对饮，隔篱呼取尽余杯。', '草堂的南边北边都涨满了春水，只见一群群鸥鸟天天飞来。长满花草的小路从来没有因为客人而打扫，今天这扇蓬门才第一次为你打开。因为离集市太远，盘中的菜肴没有多种美味；家里贫穷，杯中的酒只是旧年的浊酒。如果你愿意和邻居的老翁一起对饮，我就隔着篱笆把他喊来，一起把剩下的酒喝完。', 'academic'),
  ('tangshi300', 37, '绝句漫兴九首·其五', 'tangshi-ts-437', '肠断春江欲尽头，杖藜徐步立芳洲。
颠狂柳絮随风舞，轻薄桃花逐水流。', '春江流到尽头，令人伤心肠断；我拄着藜杖慢慢走到芳洲上站住。轻狂的柳絮随风乱舞，轻薄的桃花随水漂流。', 'public-domain'),
  ('tangshi300', 38, '野望', 'tangshi-ts-188', '西山白雪三城戍，南浦清江万里桥。
海内风尘诸弟隔，天涯涕泪一身遥。
惟将迟暮供多病，未有涓埃答圣朝。
跨马出郊时极目，不堪人事日萧条。', '西山白雪下有三城的戍守，南浦清江上有万里桥。海内动荡，兄弟们都相隔异地；天涯遥远，我一人独自流泪。只能用迟暮之身对付多病，没有一丝一毫报答圣朝。骑马出郊时极目远望，不堪人事日渐萧条。', 'public-domain'),
  ('tangshi300', 39, '奉济驿重送严公四韵', 'tangshi-ts-116', '远送从此别，青山空复情。
几时杯重把，昨夜月同行。
列郡讴歌惜，三朝出入荣。
江村独归处，寂寞养残生。', '远送至此就要分别，青山空自依依有情。什么时候才能重举酒杯，昨夜我们还一同在月下行走。各郡讴歌惋惜你的离去，你三朝出入都很荣显。我独自回到江村，寂寞地度过残生。', 'public-domain'),
  ('tangshi300', 40, '闻官军收河南河北', 'poems-xx5-16', '剑外忽传收蓟北，初闻涕泪满衣裳。
却看妻子愁何在，漫卷诗书喜欲狂。
白日放歌须纵酒，青春作伴好还乡。
即从巴峡穿巫峡，便下襄阳向洛阳。', '在剑门关外忽然听说官军收复了蓟北，刚听到消息时眼泪沾满了衣裳。回头看妻子儿女的愁容不知哪里去了，随手卷起诗书欢喜得快要发狂。白天要放声高歌，痛饮美酒，趁着春光正好伴我返回故乡。即刻从巴峡穿过巫峡，再顺流而下经过襄阳直奔洛阳。', 'school');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 41, '登高', 'poems-gz10-05', '风急天高猿啸哀，渚清沙白鸟飞回。
无边落木萧萧下，不尽长江滚滚来。
万里悲秋常作客，百年多病独登台。
艰难苦恨繁霜鬓，潦倒新停浊酒杯。', '风急天高，猿猴哀哀地啼叫；水清沙白，鸟儿在急风中盘旋。无边无际的树木萧萧地落下枯叶，望不到头的长江滚滚奔流而来。悲对秋景，感慨万里漂泊常年作客他乡，一生多病，今日独自登上高台。历尽了艰难苦恨，白发长满了双鬓，穷困潦倒，刚刚又停下了浇愁的酒杯。', 'academic'),
  ('tangshi300', 42, '别房太尉墓', 'tangshi-ts-117', '他乡复行役，驻马别孤坟。
近泪无干土，低空有断云。
对棋陪谢傅，把剑觅徐君。
惟见林花落，莺啼送客闻。', '在他乡又要奔波远行，勒住马告别这孤零零的坟。走近坟前，泪水使地上的土没有一处是干的，低空飘着断开的云。当年我曾陪你对棋，如今像季札那样把剑挂在徐君墓树上。只见林中花落，莺啼送客声声入耳。', 'public-domain'),
  ('tangshi300', 43, '登楼', 'tangshi-ts-191', '花近高楼伤客心，万方多难此登临。
锦江春色来天地，玉垒浮云变古今。
北极朝廷终不改，西山寇盗莫相侵。
可怜后主还祠庙，日暮聊为梁甫吟。', '繁花靠近高楼却伤了客子之心，万方多难时在此登临。锦江的春色来自天地之间，玉垒的浮云变幻着古今。北极星般的朝廷终究不会改变，西山的寇盗不要来侵扰。可怜那后主还留有祠庙，日暮时姑且吟起《梁甫吟》。', 'public-domain'),
  ('tangshi300', 44, '宿府', 'tangshi-ts-192', '清秋幕府井梧寒，独宿江城蜡炬残。
永夜角声悲自语，中天月色好谁看。
风尘荏苒音书绝，关塞萧条行路难。
已忍伶俜十年事，强移栖息一枝安。', '清秋的幕府里井边梧桐生寒，独自宿在江城、蜡炬将要烧残。长夜的角声悲凉、仿佛自言自语，中天的月色虽好又有谁看。风尘荏苒、音书断绝，关塞萧条、行路艰难。已忍受伶俜漂泊十年的往事，勉强迁就栖息、求得一枝之安。', 'public-domain'),
  ('tangshi300', 45, '旅夜书怀', 'tangshi-ts-118', '细草微风岸，危樯独夜舟。
星垂平野阔，月涌大江流。
名岂文章著，官应老病休。
飘飘何所似，天地一沙鸥。', '微风吹着岸边的细草，高耸的桅杆下夜里独泊着一只船。星星低垂、原野显得开阔，月亮涌起、大江奔流。名声岂是靠文章显著，官职应当因老病而罢休。飘泊不定像什么呢，像天地间一只沙鸥。', 'public-domain'),
  ('tangshi300', 46, '阁夜', 'tangshi-ts-193', '岁暮阴阳催短景，天涯霜雪霁寒宵。
五更鼓角声悲壮，三峡星河影动摇。
野哭千家闻战伐，夷歌数处起渔樵。
卧龙跃马终黄土，人事音书漫寂寥。', '岁暮时日月催逼着短促的光阴，天涯的霜雪在寒夜放晴。五更的鼓角声悲壮，三峡的星河倒影摇动。野外的哭声千家里传来，是听到了战伐的消息；夷人的歌声几处响起，来自渔夫樵夫。卧龙诸葛亮与跃马的公孙述终究都成了黄土，人事与音书都徒然寂寥。', 'public-domain'),
  ('tangshi300', 47, '八阵图', 'tangshi-ts-233', '功盖三分国，名成八阵图。
江流石不转，遗恨失吞吴。', '功业盖过三分的国家，名声成就于八阵图。江水奔流而阵石不移，遗恨的是失计于吞吴。', 'public-domain'),
  ('tangshi300', 48, '咏怀古迹·其一', 'tangshi-ts-194', '支离东北风尘际，漂泊西南天地间。
三峡楼台淹日月，五溪衣服共云山。
羯胡事主终无赖，词客哀时且未还。
庾信平生最萧瑟，暮年诗赋动江关。', '我在东北风尘之中四处流离，漂泊在西南的天地之间。三峡的楼台淹留了岁月，五溪的衣装与云山共处。羯胡侍奉君主终究无赖，词人哀叹时世而未能归去。庾信平生最为萧瑟，暮年的诗赋却震动了江关。', 'public-domain'),
  ('tangshi300', 49, '咏怀古迹·其二', 'tangshi-ts-195', '摇落深知宋玉悲，风流儒雅亦吾师。
怅望千秋一洒泪，萧条异代不同时。
江山故宅空文藻，云雨荒台岂梦思。
最是楚宫俱泯灭，舟人指点到今疑。', '草木摇落、我深知宋玉的悲凉，他的风流儒雅也是我的老师。怅望千秋、一同洒泪，萧条异代、不同时世。江山的故宅空留下文采，云雨的荒台岂是梦中的情思。最是那楚宫都已泯灭，船夫指点着至今还令人疑惑。', 'public-domain'),
  ('tangshi300', 50, '咏怀古迹·其三', 'tangshi-ts-196', '群山万壑赴荆门，生长明妃尚有村。
一去紫台连朔漠，独留青冢向黄昏。
画图省识春风面，环佩空归夜月魂。
千载琵琶作胡语，分明怨恨曲中论。', '群山万壑奔赴荆门，王昭君生长的村庄至今还在。她一离开汉宫就远赴塞北沙漠，只留下一座青冢对着黄昏。凭图画哪里能认识她春风般的面容，环佩叮当、空自归来的只有夜月下的魂。千载以来琵琶弹着胡地的曲调，分明是怨恨在曲中诉说。', 'public-domain'),
  ('tangshi300', 51, '咏怀古迹·其四', 'tangshi-ts-197', '蜀主窥吴幸三峡，崩年亦在永安宫。
翠华想像空山里，玉殿虚无野寺中。
古庙杉松巢水鹤，岁时伏腊走村翁。
武侯祠堂常邻近，一体君臣祭祀同。', '蜀主刘备窥视东吴、亲临三峡，驾崩之年也在永安宫。翠羽华盖只能在空山里想象，玉殿虚无、只存在于野寺之中。古庙的杉松上水鹤筑巢，逢年过节、村翁前来祭祀。武侯祠堂常常就在附近，君臣一体、祭祀也相同。', 'public-domain'),
  ('tangshi300', 52, '咏怀古迹·其五', 'tangshi-ts-198', '诸葛大名垂宇宙，宗臣遗像肃清高。
三分割据纡筹策，万古云霄一羽毛。
伯仲之间见伊吕，指挥若定失萧曹。
运移汉祚终难复，志决身歼军务劳。', '诸葛亮的大名垂于宇宙，宗臣的遗像肃穆清高。三分割据、曲折地施展谋略，万古云霄中他如一片羽毛般高标。与伊尹吕尚相比也不相上下，指挥若定、使萧何曹参也失色。时运转移、汉朝的国祚终究难以恢复，志向坚定、以身殉国、军务劳瘁。', 'public-domain'),
  ('tangshi300', 53, '江南逢李龟年', 'poems-cz7-06', '岐王宅里寻常见，崔九堂前几度闻。
正是江南好风景，落花时节又逢君。', '当年在岐王的府宅里常常看到你，在崔九的堂前也多次听过你的歌唱。如今正是江南风景最好的时候，在这落花的时节又遇到了你。', 'academic'),
  ('tangshi300', 54, '登岳阳楼', 'poems-gz10-21', '昔闻洞庭水，今上岳阳楼。
吴楚东南坼，乾坤日夜浮。
亲朋无一字，老病有孤舟。
戎马关山北，凭轩涕泗流。', '从前就听说过洞庭湖的盛名，今天终于登上了岳阳楼。吴地和楚地被洞庭湖分割在东南两边，天地日月仿佛都日夜浮在湖中。亲戚朋友没有一封信来，年老多病只有一叶孤舟相伴。北方的关山又在燃起战火，我凭栏远望，涕泪横流。', 'academic'),
  ('tangshi300', 55, '谷口书斋寄杨补阙', 'tangshi-ts-143', '泉壑带茅茨，云霞生薜帷。
竹怜新雨后，山爱夕阳时。
闲鹭栖常早，秋花落更迟。
家童扫萝径，昨与故人期。', '泉流山谷围绕着茅屋，云霞从薜荔的帷幕上升起。竹子在新雨后可爱，山在夕阳时最可爱。悠闲的白鹭归栖常早，秋花落得更迟。家童扫着藤萝小径，昨天已与故人相约。', 'public-domain'),
  ('tangshi300', 56, '送僧归日本', 'tangshi-ts-142', '上国随缘住，来途若梦行。
浮天沧海远，去世法舟轻。
水月通禅寂，鱼龙听梵声。
惟怜一灯影，万里眼中明。', '你随缘在上国居住，来时的路途像梦一样。沧海浮天多么遥远，你离世乘坐的法舟轻快。水月通达禅寂之境，鱼龙也来听你诵经的声音。只怜那一盏孤灯的光影，在万里之外也照得眼中明亮。', 'public-domain'),
  ('tangshi300', 57, '赠阙下裴舍人', 'tangshi-ts-202', '二月黄鹂飞上林，春城紫禁晓阴阴。
长乐钟声花外尽，龙池柳色雨中深。
阳和不散穷途恨，霄汉常悬捧日心。
献赋十年犹未遇，羞将白发对华簪。', '二月里黄鹂飞上林苑，春日的紫禁城清晨阴阴。长乐宫的钟声在花外消尽，龙池的柳色在雨中更深。和暖的阳气驱不散穷途的怨恨，云霄之中常悬着捧日之心。献赋十年仍未遇合，羞于带着白发去面对华簪。', 'public-domain'),
  ('tangshi300', 58, '贼退示官吏·并序', 'tangshi-ts-24', '癸卯岁，西原贼入道州，焚烧杀掠，几尽而去。明年，贼又攻永破邵，不犯此州边鄙而退。岂力能制敌欤？盖蒙其伤怜而已。诸使何为忍苦征敛，故作诗一篇以示官吏。
昔岁逢太平，山林二十年。
泉源在庭户，洞壑当门前。
井税有常期，日晏犹得眠。
忽然遭世变，数岁亲戎旃。
今来典斯郡，山夷又纷然。
城小贼不屠，人贫伤可怜。
是以陷邻境，此州独见全。
使臣将王命，岂不如贼焉。
今彼征敛者，迫之如火煎。
谁能绝人命，以作时世贤。
思欲委符节，引竿自刺船。
将家就鱼麦，归老江湖边。', '癸卯年，西原的贼人攻入道州，烧杀抢掠，几乎把州城洗劫一空才离去。第二年，贼人又攻打永州、攻破邵州，却没有进犯道州的边境就退走了。这难道是道州的力量能够制服敌人吗？不过是蒙受他们的怜悯罢了。那些使者为什么忍心苦苦征收赋税，因此写诗一篇给官吏们看。

从前遇上太平盛世，我在山林里住了二十年。泉水就在庭院门前，洞壑正对着家门。交纳田租有固定的期限，日头升高还能安睡。忽然遭遇世道变故，几年间亲身参与战事。如今来掌管这个州郡，山中夷人又纷纷作乱。城池小，贼人不来屠杀；百姓贫穷，令人哀伤可怜。因此邻近州郡都陷落，唯有道州得以保全。奉命催税的使臣，难道还不如贼人吗。如今那些征收赋税的人，逼迫百姓如同火煎一般。谁忍心断绝百姓的性命，去博取当世能吏的贤名呢。我想弃官辞去符节，拿起竹篙自己撑船。带着家小去靠捕鱼种麦为生，到江湖边上养老归田。', 'public-domain'),
  ('tangshi300', 59, '石鱼湖上醉歌·并序', 'tangshi-ts-52', '漫叟以公田米酿酒，因休暇则载酒于湖上，时取一醉。欢醉中，据湖岸，引臂向鱼取酒，使舫载之，遍饮坐者。意疑倚巴丘酌于君山之上，诸子环洞庭而坐，酒舫泛泛然触波涛而往来者，乃作歌以长之。
石鱼湖，似洞庭，夏水欲满君山青。
山为樽，水为沼，酒徒历历坐洲岛。
长风连日作大浪，不能废人运酒舫。
我持长瓢坐巴丘，酌饮四座以散愁。', '我漫叟用公田的米酿酒，趁着休假就载着酒到湖上，时常一醉。欢醉之中，靠着湖岸，伸手向石鱼取酒，用船载着酒，遍请座中人饮。我仿佛觉得是倚着巴丘、在君山之上酌酒，众人环坐洞庭湖上，酒船飘飘荡荡地冲着波涛往来，于是作歌来助兴。

石鱼湖啊，就像洞庭湖，夏水将要涨满，君山一片青翠。把山当作酒樽，把水当作酒池，饮酒的人一个个坐在洲岛之上。连日长风吹起大浪，也不能妨碍人们运送酒船。我手持长瓢坐在巴丘，酌酒给四座痛饮，以排遣愁怀。', 'public-domain'),
  ('tangshi300', 60, '枫桥夜泊', 'poems-xx5-07', '月落乌啼霜满天，江枫渔火对愁眠。
姑苏城外寒山寺，夜半钟声到客船。', '月亮落下，乌鸦啼叫，满天霜气，江边的枫树和渔船上的灯火伴着我的愁绪入睡。姑苏城外的寒山寺，半夜里敲响的钟声传到了客船上。', 'school'),
  ('tangshi300', 61, '酬程延秋夜即事见赠', 'tangshi-ts-146', '长簟迎风早，空城澹月华。
星河秋一雁，砧杵夜千家。
节候看应晚，心期卧已赊。
向来吟秀句，不觉已鸣鸦。', '长竹席迎风早凉，空城里月色淡淡。星河下秋夜里一只孤雁，夜里千家传来砧杵声。看节候应当已晚，心中期盼高卧却已成空。方才吟咏你秀美的诗句，不知不觉已经鸦鸣天晓。', 'public-domain'),
  ('tangshi300', 62, '同题仙游观', 'tangshi-ts-204', '仙台初见五城楼，风物凄凄宿雨收。
山色遥连秦树晚，砧声近报汉宫秋。
疏松影落空坛静，细草香闲小洞幽。
何用别寻方外去，人间亦自有丹丘。', '在仙台初次见到五城楼，风物凄清、宿雨刚收。山色远远连着秦地的树、已近傍晚，砧声传来、近报汉宫的秋意。稀疏的松影落在空坛上、一片寂静，细草的清香闲淡、小洞清幽。何必到别处去寻找方外之地，人间也自有丹丘仙境。', 'public-domain'),
  ('tangshi300', 63, '寒食', 'poems-xx6-08', '春城无处不飞花，寒食东风御柳斜。
日暮汉宫传蜡烛，轻烟散入五侯家。', '暮春时节，长安城里处处飞舞着落花，寒食节的东风把皇宫里的柳枝吹得斜斜的。黄昏时分，汉宫里传出赐新火的旨意，轻烟就飘散在权贵人家的门前。', 'school'),
  ('tangshi300', 64, '月夜', 'tangshi-ts-266', '更深月色半人家，北斗阑干南斗斜。
今夜偏知春气暖，虫声新透绿窗纱。', '夜深时月色照着半边人家，北斗横斜、南斗也倾斜。今夜偏偏感到春气温暖，虫声初次透过绿色的窗纱。', 'public-domain'),
  ('tangshi300', 65, '春怨', 'tangshi-ts-249', '纱窗日落渐黄昏，金屋无人见泪痕。
寂寞空庭春欲晚，梨花满地不开门。', '纱窗外日落西沉，渐渐到了黄昏；金屋里没有人看见她的泪痕。寂寞的空庭里春天将尽，梨花落了一地，门也不开。', 'public-domain'),
  ('tangshi300', 66, '登鹳雀楼', 'poems-xx2-03', '白日依山尽，黄河入海流。
欲穷千里目，更上一层楼。', '太阳靠着山头落下，黄河向海里奔流。要想看尽千里之外的风光，就要再登上一层楼。', 'school'),
  ('tangshi300', 67, '阙题', 'tangshi-ts-147', '道由白云尽，春与青溪长。
时有落花至，远随流水香。
闲门向山路，深柳读书堂。
幽映每白日，清辉照衣裳。', '道路在白云的尽头，春意与青溪一样悠长。时时飘落的花瓣，远远随着流水飘香。闲静的柴门对着山路，深密的柳林中是读书堂。幽暗的树影映着白日的阳光，清辉照在衣裳上。', 'public-domain'),
  ('tangshi300', 68, '征人怨', 'tangshi-ts-268', '岁岁金河复玉关，朝朝马策与刀环。
三春白雪归青冢，万里黄河绕黑山。', '年年转战金河又到玉关，天天握着马鞭与刀环。暮春三月白雪还落在青冢上，万里黄河环绕着黑山。', 'public-domain'),
  ('tangshi300', 69, '送李端', 'tangshi-ts-149', '故关衰草遍，离别正堪悲。
路出寒云外，人归暮雪时。
少孤为客早，多难识君迟。
掩泪空相向，风尘何处期。', '故乡的关隘衰草遍地，离别正令人悲伤。道路延伸到寒云之外，你归去时正逢暮雪。我年少丧父、很早就作客他乡，历经多难与你相识太迟。掩着泪水空自相对，风尘之中何处才能相会。', 'public-domain'),
  ('tangshi300', 70, '江乡故人偶集客舍', 'tangshi-ts-148', '天秋月又满，城阙夜千重。
还作江南会，翻疑梦里逢。
风枝惊暗鹊，露草覆寒蛩。
羁旅长堪醉，相留畏晓钟。', '秋天天上月亮又圆，城阙在夜色中重重叠叠。居然还能在江南相会，反倒疑心是在梦里相逢。风吹树枝惊动暗处的鹊，露水打湿的草覆盖着寒蛩。作客他乡只宜长醉，彼此挽留、只怕听到晓钟。', 'public-domain'),
  ('tangshi300', 71, '塞下曲四首·其一', 'tangshi-ts-94', '鹫翎金仆姑，燕尾绣蝥弧。
独立扬新令，千营共一呼。', '箭上装着鹫羽的金仆姑，燕尾飘着绣成的蝥弧旗。他独自屹立，发布新的号令，千营的将士齐声呼应。', 'public-domain'),
  ('tangshi300', 72, '塞下曲四首·其二', 'tangshi-ts-94', '林暗草惊风，将军夜引弓。
平明寻白羽，没在石棱中。', '林中昏暗，忽然一阵风惊动草丛，将军夜里拉开弓。天亮时去寻找那支白羽箭，箭头已深深没入石棱之中。', 'public-domain'),
  ('tangshi300', 73, '塞下曲四首·其三', 'tangshi-ts-94', '月黑雁飞高，单于夜遁逃。
欲将轻骑逐，大雪满弓刀。', '没有月光的黑夜里大雁高飞，单于趁夜逃走。正要率领轻骑追赶，大雪已落满弓刀。', 'public-domain'),
  ('tangshi300', 74, '塞下曲四首·其四', 'tangshi-ts-94', '野幕敞琼筵，羌戎贺劳旋。
醉和金甲舞，雷鼓动山川。', '野外的帐幕里摆开丰盛的筵席，羌戎的部众庆贺并慰劳凯旋的将士。醉了便合着金甲起舞，雷鸣般的鼓声震动山川。', 'public-domain'),
  ('tangshi300', 75, '晚次鄂州', 'tangshi-ts-206', '云开远见汉阳城，犹是孤帆一日程。
估客昼眠知浪静，舟人夜语觉潮生。
三湘愁鬓逢秋色，万里归心对月明。
旧业已随征战尽，更堪江上鼓鼙声。', '云开之后远远望见汉阳城，却还有孤帆一天的路程。商人白天睡觉、知道浪已平静，船夫夜里说话、感到潮水上涨。三湘的愁鬓迎着秋色，万里的归心对着明月。旧日的家业已随征战而尽，更哪里受得了江上的战鼓声。', 'public-domain'),
  ('tangshi300', 76, '喜见外弟又言别', 'tangshi-ts-150', '十年离乱后，长大一相逢。
问姓惊初见，称名忆旧容。
别来沧海事，语罢暮天钟。
明日巴陵道，秋山又几重。', '十年离乱之后，长大成人了才相逢一次。问起姓氏、初见时感到惊讶，说出名字才想起旧日的容貌。分别以来世事沧桑，谈完了已是暮天的钟声。明天你要走上巴陵的道路，又是几重秋山相隔。', 'public-domain'),
  ('tangshi300', 77, '夜上受降城闻笛', 'poems-cz7-08', '回乐烽前沙似雪，受降城外月如霜。
不知何处吹芦管，一夜征人尽望乡。', '回乐峰前的沙地白得像雪，受降城外的月色冷得像霜。不知道哪里吹起了芦管，一夜之间，出征的人都望着故乡。', 'school'),
  ('tangshi300', 78, '听筝', 'tangshi-ts-239', '鸣筝金粟柱，素手玉房前。
欲得周郎顾，时时误拂弦。', '金粟装饰的筝柱发出鸣响，洁白的手弹在玉房之前。想得到周郎那样的顾盼，便时时故意弹错琴弦。', 'public-domain'),
  ('tangshi300', 79, '贼平后送人北归', 'tangshi-ts-153', '世乱同南去，时清独北还。
他乡生白发，旧国见青山。
晓月过残垒，繁星宿故关。
寒禽与衰草，处处伴愁颜。', '世道离乱时一同南去，时局清平后你却独自北还。在他乡生出了白发，回到故国可见青山。晓月下走过残破的营垒，繁星下歇宿在旧日的关隘。寒天的禽鸟与衰败的野草，处处伴随着你愁苦的容颜。', 'public-domain'),
  ('tangshi300', 80, '云阳馆与韩绅宿别', 'tangshi-ts-151', '故人江海别，几度隔山川。
乍见翻疑梦，相悲各问年。
孤灯寒照雨，深竹暗浮烟。
更有明朝恨，离杯惜共传。', '老朋友在江海间分别，几次相隔山川。忽然相见反而疑心是梦，相互悲叹、各自询问年岁。孤灯在寒夜里照着雨，深竹在暗中浮起烟雾。更添明天分别的怅恨，珍惜这离别的酒杯共相传饮。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 81, '喜外弟卢纶见宿', 'tangshi-ts-152', '静夜四无邻，荒居旧业贫。
雨中黄叶树，灯下白头人。
以我独沉久，愧君相见频。
平生自有分，况是蔡家亲。', '静夜里四邻无人，荒凉的居所、旧业贫寒。雨中是黄叶的树，灯下是白头的人。因为我长久独自沉沦，惭愧你频频来看望。平生本有缘分，何况还是表亲。', 'public-domain'),
  ('tangshi300', 82, '新嫁娘', 'tangshi-ts-240', '三日入厨下，洗手作羹汤。
未谙姑食性，先遣小姑尝。', '婚后三天走进厨房，洗净手做羹汤。不知道婆婆的口味，先让小姑尝一尝。', 'public-domain'),
  ('tangshi300', 83, '行宫', 'tangshi-ts-243', '寥落古行宫，宫花寂寞红。
白头宫女在，闲坐说玄宗。', '寥落的古老行宫，宫中的花寂寞地红着。白头宫女还在这里，闲坐谈论着玄宗。', 'public-domain'),
  ('tangshi300', 84, '玉台体', 'tangshi-ts-241', '昨夜裙带解，今朝蟢子飞。
铅华不可弃，莫是藁砧归。', '昨夜裙带自己解开，今早蟢子飞来。脂粉不可弃置不用，莫不是丈夫要回来了。', 'public-domain'),
  ('tangshi300', 85, '山石', 'tangshi-ts-53', '山石荦确行径微，黄昏到寺蝙蝠飞。
升堂坐阶新雨足，芭蕉叶大栀子肥。
僧言古壁佛画好，以火来照所见稀。
铺床拂席置羹饭，疏粝亦足饱我饥。
夜深静卧百虫绝，清月出岭光入扉。
天明独去无道路，出入高下穷烟霏。
山红涧碧纷烂漫，时见松枥皆十围。
当流赤足踏涧石，水声激激风吹衣。
人生如此自可乐，岂必局束为人鞿。
嗟哉吾党二三子，安得至老不更归。', '山石险峻不平，山路狭窄，黄昏时到寺里，蝙蝠飞来飞去。登上殿堂坐在台阶上，刚下过透雨，芭蕉叶肥大、栀子花饱满。僧人说起古壁上佛画很好，举着火来照，看得却不很清楚。铺床扫席摆上饭菜，粗茶淡饭也足以充饥。夜深静静躺卧，各种虫声都停了，清月从山岭升起，月光照进门扉。天明独自离去，没有现成的道路，高高低低地穿行在烟雾之中。山花红艳、涧水碧绿，色彩纷繁烂漫，时时见到松树枥树都有十围粗。对着溪流赤足踏着涧石，水声激荡，风吹动衣裳。人生像这样本来就可乐，何必受拘束被人牵制。唉，我们这几个同道，怎能到老还不归隐呢。', 'public-domain'),
  ('tangshi300', 86, '八月十五夜赠张功曹', 'tangshi-ts-54', '纤云四卷天无河，清风吹空月舒波。
沙平水息声影绝，一杯相属君当歌。
君歌声酸辞且苦，不能听终泪如雨。
洞庭连天九疑高，蛟龙出没猩鼯号。
十生九死到官所，幽居默默如藏逃。
下床畏蛇食畏药，海气湿蛰熏腥臊。
昨者州前捶大鼓，嗣皇继圣登夔皋。
赦书一日行万里，罪从大辟皆除死。
迁者追回流者还，涤瑕荡垢清朝班。
州家申名使家抑，坎轲只得移荆蛮。
判司卑官不堪说，未免捶楚尘埃间。
同时辈流多上道，天路幽险难追攀。
君歌且休听我歌，我歌今与君殊科。
一年明月今宵多，人生由命非由他，
有酒不饮奈明何。', '薄云四处消散，天上不见了银河，清风吹过天空，月亮散出波光。沙岸平旷、水面平静，声影都断绝了，我敬你一杯酒，你该唱首歌。你的歌声酸楚、言辞悲苦，我还没听完就泪如雨下。洞庭湖连天，九疑山高耸，蛟龙出没，猩猩和飞鼠哀号。你九死一生才到任所，幽居默默像躲藏的逃犯。下床怕蛇，吃饭怕毒，海气潮湿，蛰虫熏出腥臊之气。昨天州衙前擂响大鼓，新皇继位，起用夔、皋那样的贤臣。赦书一天传行万里，犯死罪的都免去死罪。被贬的追回、流放的放还，洗清污垢、整顿朝班。可州里申报了名字，却被观察使压下，命运坎坷，只调移到荆蛮之地。判司这样的卑官不值一提，免不了在尘埃中被鞭打。同时被贬的人大多已上路，可通向朝廷的天路幽险难以攀登。你别唱了，听我唱，我的歌今天与你不同调。一年中的明月今夜最圆最多，人生由命、不由别的，有酒不喝，怎么对得起这明月呢。', 'public-domain'),
  ('tangshi300', 87, '谒衡岳庙遂宿岳寺题门楼', 'tangshi-ts-55', '五岳祭秩皆三公，四方环镇嵩当中。
火维地荒足妖怪，天假神柄专其雄。
喷云泄雾藏半腹，虽有绝顶谁能穷。
我来正逢秋雨节，阴气晦昧无清风。
潜心默祷若有应，岂非正直能感通。
须臾静扫众峰出，仰见突兀撑青空。
紫盖连延接天柱，石廪腾掷堆祝融。
森然魄动下马拜，松柏一径趋灵宫。
粉墙丹柱动光彩，鬼物图画填青红。
升阶伛偻荐脯酒，欲以菲薄明其衷。
庙令老人识神意，睢盱侦伺能鞠躬。
手持杯珓导我掷，云此最吉余难同。
窜逐蛮荒幸不死，衣食才足甘长终。
侯王将相望久绝，神纵欲福难为功。
夜投佛寺上高阁，星月掩映云朣胧。
猿鸣钟动不知曙，杲杲寒日生于东。', '五岳的祭祀规格都等同于三公，四方各有山镇环绕，嵩山居中。南方属火、土地荒僻多有妖怪，上天借给神明权柄让他专擅雄威。衡山喷云吐雾、云雾藏住半山腰，虽有绝顶又有谁能登到尽头。我来时正逢秋雨时节，阴气晦暗没有清风。我潜心默默祈祷，仿佛有应验，难道不是正直之心能够感通神明吗。不一会儿阴云静扫、群峰露出，抬头看见山峰突兀地撑着青天。紫盖峰连绵接着天柱峰，石廪峰腾跃堆叠连着祝融峰。景象森然令人心惊，我下马而拜，沿着松柏夹道的小路走向神庙。粉墙红柱光彩闪动，鬼神图画涂着青红之色。我登阶弯腰献上干肉和酒，想用微薄的祭品表明诚心。庙里的老人懂得神意，瞪着眼察言观色、善于鞠躬。他手持杯珓引导我投掷，说这一卦最吉，别的难以相比。我被贬逐到蛮荒之地侥幸不死，衣食刚够便甘愿在此终老。封侯拜相已不抱指望，神明纵然想赐福也难以奏效。夜里投宿佛寺登上高阁，星月在朦胧的云中掩映。猿鸣钟响不知不觉天已破晓，明亮的寒日从东方升起。', 'public-domain'),
  ('tangshi300', 88, '石鼓歌', 'tangshi-ts-56', '张生手持石鼓文，劝我试作石鼓歌。
少陵无人谪仙死，才薄将奈石鼓何。
周纲陵迟四海沸，宣王愤起挥天戈。
大开明堂受朝贺，诸侯剑佩鸣相磨。
蒐于岐阳骋雄俊，万里禽兽皆遮罗。
镌功勒成告万世，凿石作鼓隳嵯峨。
从臣才艺咸第一，拣选撰刻留山阿。
雨淋日炙野火燎，鬼物守护烦撝呵。
公从何处得纸本，毫发尽备无差讹。
辞严义密读难晓，字体不类隶与科。
年深岂免有缺画，快剑斫断生蛟鼍。
鸾翔凤翥众仙下，珊瑚碧树交枝柯。
金绳铁索锁钮壮，古鼎跃水龙腾梭。
陋儒编诗不收入，二雅褊迫无委蛇。
孔子西行不到秦，掎摭星宿遗羲娥。
嗟余好古生苦晚，对此涕泪双滂沱。
忆昔初蒙博士征，其年始改称元和。
故人从军在右辅，为我度量掘臼科。
濯冠沐浴告祭酒，如此至宝存岂多。
毡包席裹可立致，十鼓只载数骆驼。
荐诸太庙比郜鼎，光价岂止百倍过。
圣恩若许留太学，诸生讲解得切磋。
观经鸿都尚填咽，坐见举国来奔波。
剜苔剔藓露节角，安置妥帖平不颇。
大厦深檐与盖覆，经历久远期无佗。
中朝大官老于事，讵肯感激徒媕娿。
牧童敲火牛砺角，谁复著手为摩挲。
日销月铄就埋没，六年西顾空吟哦。
羲之俗书趁姿媚，数纸尚可博白鹅。
继周八代争战罢，无人收拾理则那。
方今太平日无事，柄任儒术崇丘轲。
安能以此上论列，愿借辩口如悬河。
石鼓之歌止于此，呜呼吾意其蹉跎。', '张生手里拿着石鼓文的拓本，劝我试作一首石鼓歌。少陵杜甫已不在，谪仙李白也已死去，我才学浅薄，对这石鼓又能怎么办呢。周朝纲纪衰败、四海沸腾，宣王发愤而起挥动天戈。大开明堂接受朝贺，诸侯的宝剑玉佩叮当作响、互相磨擦。在岐阳打猎驰骋雄俊，万里之内的禽兽都被网罗。要刻功记业昭告万世，凿开山石做成石鼓，削平了嵯峨的山崖。随从之臣才艺都是第一流，挑选他们撰写刻石留在山阿。任凭雨淋日晒、野火烧灼，鬼神守护、频频驱呵。你从哪里得到这纸拓本，毫发都完备、毫无差错。文辞严正、含义细密，读起来难以通晓，字体既不像隶书也不像科斗文。年代久远岂能没有缺笔，像快剑砍断的蛟鼍。又像鸾凤飞翔、众仙下降，珊瑚碧树交错着枝柯。像金绳铁索锁钮般雄壮，像古鼎跃出水面、龙腾如梭。浅陋的儒者编《诗》没有收入，《大雅》《小雅》狭隘局促，没有这般的从容舒展。孔子西行没有到秦国，如同拾取星宿而遗漏了日月。可叹我爱好古物却生得太晚，面对它泪如雨下。回忆当初蒙召为博士，那年才改元为元和。老朋友在右辅从军，替我度量挖掘石鼓的坑穴。我洗净冠、沐浴身体禀告祭酒，这样的至宝留存下来的还能有多少。用毡包席裹立刻可以取来，十只石鼓只需几头骆驼运载。进献太庙与郜鼎相比，光价岂止超过百倍。圣恩如果允许留在太学，诸生讲解还能互相切磋。当年在鸿都门观经尚且拥挤，眼看全国都要为此奔波而来。剜去苔藓、剔净藓苔，露出石鼓的棱角，安置得妥帖平稳、不偏不倚。用大厦深檐把它遮盖，经历久远也可望无事。朝中高官老于处事，怎肯激动感慨，只是唯唯诺诺敷衍。牧童在石上敲火，牛在上面磨角，谁还肯动手去摩挲它。日销月蚀，终将埋没，我在西边回望六年，徒然吟哦。王羲之的俗书追求姿媚，几张纸还能换得白鹅。继周之后八代争战结束，无人收拾，理当如此又能怎样。如今太平无事了，朝廷重用儒术、推崇孔孟。怎能把这些上奏论列，愿借你悬河般的辩才。石鼓之歌到此为止，唉，我的心意恐怕要落空了。', 'public-domain'),
  ('tangshi300', 89, '左迁至蓝关示侄孙湘', 'poems-cz9-12', '一封朝奏九重天，夕贬潮州路八千。
欲为圣明除弊事，肯将衰朽惜残年！
云横秦岭家何在？雪拥蓝关马不前。
知汝远来应有意，好收吾骨瘴江边。', '早晨我把一封奏章呈给皇帝，傍晚就被贬到八千里外的潮州。我本想替圣明的朝廷革除弊政，怎么能因衰老而吝惜残余的生命！云横在秦岭上，我的家在何处？大雪堵住蓝关，马也停步不前。我知道你远道而来一定是有用意的，正好在瘴江边收殓我的尸骨。', 'school'),
  ('tangshi300', 90, '秋夜曲', 'tangshi-ts-87', '桂魄初生秋露微，轻罗已薄未更衣。
银筝夜久殷勤弄，心怯空房不忍归。', '月亮初升、秋露微凉，轻薄的罗衣已觉寒冷却还没有换衣。夜深了还在殷勤地弹着银筝，心里害怕那空房、不忍回去。', 'public-domain'),
  ('tangshi300', 91, '晨诣超师院读禅经', 'tangshi-ts-32', '汲井漱寒齿，清心拂尘服。
闲持贝叶书，步出东斋读。
真源了无取，妄迹世所逐。
遗言冀可冥，缮性何由熟。
道人庭宇静，苔色连深竹。
日出雾露余，青松如膏沐。
澹然离言说，悟悦心自足。', '从井里打水漱一漱寒凉的牙齿，清一清心，拂去衣上的尘土。闲来手持贝叶经书，走出东斋去诵读。真如本源全然无所执取，虚妄的迹象才是世人所追逐的。佛的遗言希望能默默契合，可修治本性又怎能纯熟。道人庭院寂静，苔色连着深深的竹林。太阳出来，雾露还在，青松像刚洗沐过一样。心境淡然，言语道断，悟道之乐使内心自然满足。', 'public-domain'),
  ('tangshi300', 92, '登柳州城楼寄漳汀封连四州刺史', 'tangshi-ts-207', '城上高楼接大荒，海天愁思正茫茫。
惊风乱飐芙蓉水，密雨斜侵薜荔墙。
岭树重遮千里目，江流曲似九回肠。
共来百越文身地，犹自音书滞一乡。', '城上的高楼连接着荒远之地，海天般的愁思正茫茫无边。狂风胡乱吹动芙蓉池水，密雨斜斜地打湿薜荔墙。岭上的树木重重遮蔽了望远的视线，江流曲折好似九回肠。我们一同来到百越文身之地，却仍然音信阻隔在一方。', 'public-domain'),
  ('tangshi300', 93, '溪居', 'tangshi-ts-33', '久为簪组累，幸此南夷谪。
闲依农圃邻，偶似山林客。
晓耕翻露草，夜榜响溪石。
来往不逢人，长歌楚天碧。', '长久被官职所牵累，幸而被贬谪到南夷这地方。闲来与农圃为邻，偶然间倒像个山林隐士。清晨耕作，翻动带露的草；夜里撑船，船桨碰响溪中的石头。往来都遇不到人，放声长歌，楚天一片碧蓝。', 'public-domain'),
  ('tangshi300', 94, '江雪', 'poems-xx2-05', '千山鸟飞绝，万径人踪灭。
孤舟蓑笠翁，独钓寒江雪。', '千山之中鸟儿都飞尽了，条条小路上没有人迹。只有一叶孤舟上披蓑戴笠的老翁，独自在寒冷的江雪中垂钓。', 'school'),
  ('tangshi300', 95, '渔翁', 'tangshi-ts-57', '渔翁夜傍西岩宿，晓汲清湘燃楚竹。
烟销日出不见人，欸乃一声山水绿。
回看天际下中流，岩上无心云相逐。', '渔翁夜里靠着西岩住宿，清晨汲取清湘的水、烧着楚地的竹。烟消日出却不见人影，只听到一声欸乃，山水一片翠绿。回头看天际，船已驶入中流，山岩上无心的白云相互追逐。', 'public-domain'),
  ('tangshi300', 96, '蜀先主庙', 'tangshi-ts-154', '天地英雄气，千秋尚凛然。
势分三足鼎，业复五铢钱。
得相能开国，生儿不象贤。
凄凉蜀故妓，来舞魏宫前。', '天地间的英雄气概，千秋之后仍然凛然。势力形成三足鼎立，要恢复汉室的五铢钱。得到贤相能够开国，生了儿子却不像父亲那样贤明。凄凉的蜀国旧日歌妓，被送来在魏宫前歌舞。', 'public-domain'),
  ('tangshi300', 97, '西塞山怀古', 'tangshi-ts-208', '王濬楼船下益州，金陵王气黯然收。
千寻铁锁沉江底，一片降幡出石头。
人世几回伤往事，山形依旧枕寒流。
今逢四海为家日，故垒萧萧芦荻秋。', '王濬的战船从益州顺流而下，金陵的王气黯然收去。千寻长的铁锁沉入江底，一片投降的旗帜从石头城上举出。人世间几次为往事感伤，山的形状依旧枕着寒流。如今正逢四海一家的日子，旧日的营垒萧萧、芦荻在秋风中摇动。', 'public-domain'),
  ('tangshi300', 98, '乌衣巷', 'tangshi-ts-271', '朱雀桥边野草花，乌衣巷口夕阳斜。
旧时王谢堂前燕，飞入寻常百姓家。', '朱雀桥边长满野草野花，乌衣巷口夕阳西斜。从前王导谢安家堂前的燕子，如今飞进了普通百姓的家。', 'public-domain'),
  ('tangshi300', 99, '和乐天春词', 'tangshi-ts-272', '新妆宜面下朱楼，深锁春光一院愁。
行到中庭数花朵，蜻蜓飞上玉搔头。', '新妆与面容相宜，缓步走下朱楼；深锁的春光里，满院都是愁。走到庭院中数着花朵，一只蜻蜓飞上了玉搔头。', 'public-domain'),
  ('tangshi300', 100, '游子吟', 'tangshi-ts-67', '慈母手中线，游子身上衣。
临行密密缝，意恐迟迟归。
谁言寸草心，报得三春晖。', '慈爱的母亲手里拿着针线，为将要远行的儿子缝制衣服。临行前密密地缝了又缝，担心孩子迟迟不能回来。谁说小草一样微薄的心意，能报答得了春天阳光般的恩情？', 'public-domain'),
  ('tangshi300', 101, '清平调·其三', 'yuefu-yf-75·3', '名花倾国两相欢，长得君王带笑看。
解释春风无限恨，沉香亭北倚阑干。', '名花与倾国之姿彼此相映成欢，常得君王带着笑意观看。春风能消解那无限的愁恨，沉香亭北，两人倚着栏杆。', 'public-domain'),
  ('tangshi300', 102, '渭城曲', 'poems-xx5-23', '渭城朝雨浥轻尘，
客舍青青柳色新。
劝君更尽一杯酒，
西出阳关无故人。', '渭城清晨的细雨润湿了轻尘，客舍旁柳色青青，格外鲜亮。劝你再干一杯酒，向西出了阳关就再没有老朋友了。', 'school'),
  ('tangshi300', 103, '金缕衣', 'yuefu-yf-76', '劝君莫惜金缕衣，劝君惜取少年时。
花开堪折直须折，莫待无花空折枝。', '劝你不要爱惜那金缕织成的衣裳，劝你要珍惜少年时光。花开可折的时候就尽管去折，不要等到花谢了空折一枝。', 'public-domain'),
  ('tangshi300', 104, '感遇·其一', 'tangshi-ts-1', '孤鸿海上来，池潢不敢顾。
侧见双翠鸟，巢在三珠树。
矫矫珍木巅，得无金丸惧。
美服患人指，高明逼神恶。
今我游冥冥，弋者何所慕。', '一只孤雁从海上飞来，连城池边的水塘也不敢停留回顾。它侧目看见一对翠鸟，把巢筑在珍贵的三珠树上。那对翠鸟高高地立在树梢，难道就不怕弹丸射来吗？华美的衣裳怕人指点，处在高位会招来神明的厌恶。如今我自在地翱翔在辽阔的天空，捕鸟的人又能对我有什么企图呢。', 'public-domain'),
  ('tangshi300', 105, '感遇·其二', 'tangshi-ts-2', '兰叶春葳蕤，桂华秋皎洁。
欣欣此生意，自尔为佳节。
谁知林栖者，闻风坐相悦。
草木有本心，何求美人折。', '兰草在春天枝叶繁茂，桂花在秋天花白皎洁。它们欣欣向荣地生长，各自成为美好的时节。谁会想到那隐居山林的人，闻到它们的芬芳便心生爱慕。草木散发香气本是出于天性，哪里是为了求得别人来攀折赏识呢。', 'public-domain'),
  ('tangshi300', 106, '没蕃故人', 'tangshi-ts-155', '前年伐月支，城下没全师。
蕃汉断消息，死生长别离。
无人收废帐，归马识残旗。
欲祭疑君在，天涯哭此时。', '前年讨伐月支，城下全军覆没。蕃汉之间消息断绝，是生是死都是长久的别离。没有人收拾废弃的营帐，归来的军马认识残破的旗帜。想祭奠你又疑心你还活着，天涯之远、此时唯有痛哭。', 'public-domain'),
  ('tangshi300', 107, '遣悲怀·其一', 'tangshi-ts-209', '谢公最小偏怜女，自嫁黔娄百事乖。
顾我无衣搜荩箧，泥他沽酒拔金钗。
野蔬充膳甘长藿，落叶添薪仰古槐。
今日俸钱过十万，与君营奠复营斋。', '你像谢公最疼爱的小女儿，自从嫁给我这贫士便百事不顺。看我没有衣服穿就翻箱倒柜寻找，缠着你去买酒、你便拔下金钗。用野菜充饥、甘心吃豆叶，靠落叶添柴、仰仗老槐树。如今我的俸钱已超过十万，却只能为你营办祭奠与斋事。', 'public-domain'),
  ('tangshi300', 108, '遣悲怀·其二', 'tangshi-ts-210', '昔日戏言身后意，今朝都到眼前来。
衣裳已施行看尽，针线犹存未忍开。
尚想旧情怜婢仆，也曾因梦送钱财。
诚知此恨人人有，贫贱夫妻百事哀。', '从前戏言身后的事，如今都到了眼前来。你的衣裳已经施舍出去、眼看就要用尽，针线还留着、我不忍心打开。还念着旧情而怜惜婢仆，也曾因为梦见你而送去钱财。确实知道这种遗恨人人都有，只是贫贱的夫妻事事都令人悲哀。', 'public-domain'),
  ('tangshi300', 109, '遣悲怀·其三', 'tangshi-ts-211', '闲坐悲君亦自悲，百年都是几多时。
邓攸无子寻知命，潘岳悼亡犹费词。
同穴窅冥何所望，他生缘会更难期。
惟将终夜长开眼，报答平生未展眉。', '闲坐时悲叹你也悲叹自己，百年又有多长时间。邓攸没有儿子、不久便知天命，潘岳悼亡、仍徒然耗费文词。同穴于幽暗黄泉又有什么可望，来生再会的缘分更加难期。只能整夜长睁着眼，报答你平生未曾舒展的眉头。', 'public-domain'),
  ('tangshi300', 110, '卖炭翁', 'poems-cz8-25', '卖炭翁，伐薪烧炭南山中。
满面尘灰烟火色，两鬓苍苍十指黑。
卖炭得钱何所营？身上衣裳口中食。
可怜身上衣正单，心忧炭贱愿天寒。
夜来城外一尺雪，晓驾炭车辗冰辙。
牛困人饥日已高，市南门外泥中歇。
翩翩两骑来是谁？黄衣使者白衫儿。
手把文书口称敕，回车叱牛牵向北。
一车炭，千余斤，宫使驱将惜不得。
半匹红纱一丈绫，系向牛头充炭直。', '有个卖炭的老翁，在南山里砍柴烧炭。他满脸灰尘，显出被烟熏火燎的颜色，两鬓灰白，十个手指也是黑的。卖炭得来的钱做什么用呢？是为了身上穿的衣裳和口中吃的食物。可怜他身上穿的衣服十分单薄，心里却因担心炭贱而希望天更冷些。夜里城外下了一尺厚的雪，清晨他驾着炭车碾过冰冻的车辙。牛累了，人饿了，太阳已经升得很高了，他就在集市南门外的泥地里歇息。那两个轻快地骑着马而来的人是谁？是穿着黄衣的太监和穿着白衫的爪牙。他们手里拿着公文，口里说是奉了皇帝的命令，便掉转车头，吆喝着牛向北赶去。一车炭，有一千多斤，宫使硬要赶走，老翁舍不得也没有办法。他们只把半匹红纱和一丈绫，系在牛头上就充当炭的价钱了。', 'academic'),
  ('tangshi300', 111, '长恨歌', 'tangshi-ts-58', '汉皇重色思倾国，御宇多年求不得。
杨家有女初长成，养在深闺人未识。
天生丽质难自弃，一朝选在君王侧。
回眸一笑百媚生，六宫粉黛无颜色。
春寒赐浴华清池，温泉水滑洗凝脂。
侍儿扶起娇无力，始是新承恩泽时。
云鬓花颜金步摇，芙蓉帐暖度春宵。
春宵苦短日高起，从此君王不早朝。
承欢侍宴无闲暇，春从春游夜专夜。
后宫佳丽三千人，三千宠爱在一身。
金屋妆成娇侍夜，玉楼宴罢醉和春。
姊妹弟兄皆列土，可怜光彩生门户。
遂令天下父母心，不重生男重生女。
骊宫高处入青云，仙乐风飘处处闻。
缓歌慢舞凝丝竹，尽日君王看不足。
渔阳鼙鼓动地来，惊破霓裳羽衣曲。
九重城阙烟尘生，千乘万骑西南行。
翠华摇摇行复止，西出都门百余里。
六军不发无奈何，宛转蛾眉马前死。
花钿委地无人收，翠翘金雀玉搔头。
君王掩面救不得，回看血泪相和流。
黄埃散漫风萧索，云栈萦纡登剑阁。
峨嵋山下少人行，旌旗无光日色薄。
蜀江水碧蜀山青，圣主朝朝暮暮情。
行宫见月伤心色，夜雨闻铃肠断声。
天旋日转回龙驭，到此踌躇不能去。
马嵬坡下泥土中，不见玉颜空死处。
君臣相顾尽沾衣，东望都门信马归。
归来池苑皆依旧，太液芙蓉未央柳。
芙蓉如面柳如眉，对此如何不泪垂。
春风桃李花开日，秋雨梧桐叶落时。
西宫南内多秋草，落叶满阶红不扫。
梨园弟子白发新，椒房阿监青娥老。
夕殿萤飞思悄然，孤灯挑尽未成眠。
迟迟钟鼓初长夜，耿耿星河欲曙天。
鸳鸯瓦冷霜华重，翡翠衾寒谁与共。
悠悠生死别经年，魂魄不曾来入梦。
临邛道士鸿都客，能以精诚致魂魄。
为感君王辗转思，遂教方士殷勤觅。
排空驭气奔如电，升天入地求之遍。
上穷碧落下黄泉，两处茫茫皆不见。
忽闻海上有仙山，山在虚无缥缈间。
楼阁玲珑五云起，其中绰约多仙子。
中有一人字太真，雪肤花貌参差是。
金阙西厢叩玉扃，转教小玉报双成。
闻道汉家天子使，九华帐里梦魂惊。
揽衣推枕起徘徊，珠箔银屏迤逦开。
云鬓半偏新睡觉，花冠不整下堂来。
风吹仙袂飘飖举，犹似霓裳羽衣舞。
玉容寂寞泪阑干，梨花一枝春带雨。
含情凝睇谢君王，一别音容两渺茫。
昭阳殿里恩爱绝，蓬莱宫中日月长。
回头下望人寰处，不见长安见尘雾。
惟将旧物表深情，钿合金钗寄将去。
钗留一股合一扇，钗擘黄金合分钿。
但教心似金钿坚，天上人间会相见。
临别殷勤重寄词，词中有誓两心知。
七月七日长生殿，夜半无人私语时。
在天愿作比翼鸟，在地愿为连理枝。
天长地久有时尽，此恨绵绵无绝期。', '汉皇贪恋美色、想得到倾国倾城的佳人，统治天下多年却求之不得。杨家有个女儿刚刚长大成人，养在深闺中无人知晓。天生的美丽资质难以自弃，一朝被选到君王身边。回头一笑就生出百般妩媚，六宫的妃嫔都黯然失色。春寒时赐她在华清池沐浴，温泉水滑，洗涤着她的肌肤。侍女扶起她时娇弱无力，这正是刚承恩泽的时候。鬓发如云、容颜如花、戴着金步摇，芙蓉帐里暖意融融地度过春宵。春宵苦于太短，日头高高升起，从此君王不再提早上朝。承受欢宠、侍奉宴饮没有空闲，春天随着出游，夜里独享君恩。后宫里美貌的佳丽有三千人，三千宠爱都集中在她一人身上。金屋里梳妆完毕娇娇地侍夜，玉楼宴会散后醉意与春意融合。她的姐妹兄弟都封土赐爵，门户上生出无限光彩。于是使天下做父母的心，不看重生男而看重生女。骊山行宫高高直入青云，仙乐随风飘荡处处可闻。缓歌慢舞与丝竹凝合，君王整日看也看不够。渔阳的鼙鼓震地而来，惊破了《霓裳羽衣曲》。九重城阙升起烟尘，千乘万骑向西南而行。翠羽华盖飘飘摇摇走着又停下，西出都门一百多里。六军不肯进发无可奈何，宛转娥眉死在马前。花钿丢在地上无人收拾，还有翠翘、金雀、玉搔头。君王掩面却救不了她，回头望去血泪交相流淌。黄尘散漫、风声萧索，沿着萦回的栈道登上剑阁。峨嵋山下行人稀少，旌旗没有光彩、日色淡薄。蜀江水碧绿、蜀山青翠，圣主朝朝暮暮满怀思念。在行宫里见月是伤心的颜色，夜雨里听铃是断肠的声音。天旋地转，圣驾回京，到此处踌躇着不忍离去。马嵬坡下的泥土中，不见玉颜，只留着她死去的地方。君臣相顾，泪湿衣襟，向东望着都门，信马而回。回京后池苑都依旧，太液池的芙蓉、未央宫的柳树。芙蓉像她的面容、柳叶像她的眉，面对这些怎么能不落泪。春风里桃李花开的日子，秋雨中梧桐叶落的时候。西宫南内长满秋草，落叶满阶、红色无人打扫。梨园弟子新添了白发，椒房的阿监、宫女都已衰老。傍晚殿中流萤飞过，思念悄然，孤灯挑尽也睡不着。钟鼓迟迟，夜刚开始变长，星河明亮将要天亮。鸳鸯瓦冷、霜花厚重，翡翠被寒，有谁与我共眠。悠悠生死一别已经一年，魂魄不曾进入我的梦中。临邛的道士是鸿都的客人，能以精诚招来魂魄。因为感念君王辗转思念，便叫方士殷勤地寻找。排开长空、驾着云气，奔走如电，升天入地寻遍。上穷碧落下至黄泉，两处茫茫都不见踪影。忽然听说海上有座仙山，山在虚无缥缈之间。楼阁玲珑，五色祥云升起，其中有许多绰约的仙子。其中有一位名叫太真，雪白肌肤、如花容貌，大约就是她。在仙宫金阙西厢轻叩玉门，转叫小玉去通报双成。听说汉家天子的使者到来，九华帐里梦魂惊动。她揽衣推枕起身徘徊，珠帘银屏一道道打开。云鬓半偏、刚睡醒的样子，花冠不整地走下堂来。清风吹动仙袖飘飘高扬，还像当年《霓裳羽衣舞》的样子。玉容寂寞、泪痕纵横，像一枝梨花带着春雨。她含情凝视、拜谢君王，一别之后音容两处渺茫。昭阳殿里的恩爱已经断绝，蓬莱宫中的日月却很漫长。回头向下望人间，看不见长安只见尘雾。只能拿旧物来表明深情，把钿盒金钗寄送回去。钗留一股、盒留一扇，把金钗掰开、把钿盒分半。只要心像金钿一样坚贞，天上人间总会相见。临别时殷勤地再三寄语，话中的誓言两心相知。七月七日长生殿，夜半无人私语的时候。在天愿作比翼鸟，在地愿为连理枝。天长地久也有尽时，这绵绵的遗恨却永无绝期。', 'public-domain'),
  ('tangshi300', 112, '琵琶行·并序', 'tangshi-ts-59', '元和十年，予左迁九江郡司马。明年秋，送客湓浦口，闻舟中夜弹琵琶者，听其音，铮铮然有京都声。问其人，本长安倡女，尝学琵琶于穆、曹二善才，年长色衰，委身为贾人妇。遂命酒，使快弹数曲。曲罢悯然，自叙少小时欢乐事，今漂沦憔悴，转徙于江湖间。予出官二年，恬然自安，感斯人言，是夕始觉有迁谪意。因为长句，歌以赠之，凡六百一十二言，命曰《琵琶行》。
浔阳江头夜送客，枫叶荻花秋瑟瑟。
主人下马客在船，举酒欲饮无管弦。
醉不成欢惨将别，别时茫茫江浸月。
忽闻水上琵琶声，主人忘归客不发。
寻声暗问弹者谁，琵琶声停欲语迟。
移船相近邀相见，添酒回灯重开宴。
千呼万唤始出来，犹抱琵琶半遮面。
转轴拨弦三两声，未成曲调先有情。
弦弦掩抑声声思，似诉平生不得志。
低眉信手续续弹，说尽心中无限事。
轻拢慢捻抹复挑，初为霓裳后六幺。
大弦嘈嘈如急雨，小弦切切如私语。
嘈嘈切切错杂弹，大珠小珠落玉盘。
间关莺语花底滑，幽咽泉流冰下难。
冰泉冷涩弦凝绝，凝绝不通声渐歇。
别有幽愁暗恨生，此时无声胜有声。
银瓶乍破水浆迸，铁骑突出刀枪鸣。
曲终收拨当心画，四弦一声如裂帛。
东船西舫悄无言，唯见江心秋月白。
沉吟放拨插弦中，整顿衣裳起敛容。
自言本是京城女，家在虾蟆陵下住。
十三学得琵琶成，名属教坊第一部。
曲罢曾教善才服，妆成每被秋娘妒。
五陵年少争缠头，一曲红绡不知数。
钿头银篦击节碎，血色罗裙翻酒污。
今年欢笑复明年，秋月春风等闲度。
弟走从军阿姨死，暮去朝来颜色故。
门前冷落鞍马稀，老大嫁作商人妇。
商人重利轻别离，前月浮梁买茶去。
去来江口守空船，绕船月明江水寒。
夜深忽梦少年事，梦啼妆泪红阑干。
我闻琵琶已叹息，又闻此语重唧唧。
同是天涯沦落人，相逢何必曾相识。
我从去年辞帝京，谪居卧病浔阳城。
浔阳地僻无音乐，终岁不闻丝竹声。
住近湓江地低湿，黄芦苦竹绕宅生。
其间旦暮闻何物，杜鹃啼血猿哀鸣。
春江花朝秋月夜，往往取酒还独倾。
岂无山歌与村笛，呕哑嘲哳难为听。
今夜闻君琵琶语，如听仙乐耳暂明。
莫辞更坐弹一曲，为君翻作琵琶行。
感我此言良久立，却坐促弦弦转急。
凄凄不似向前声，满座重闻皆掩泣。
座中泣下谁最多，江州司马青衫湿。', '元和十年，我被贬为九江郡司马。第二年秋天，在湓浦口送客，听见船中夜里有人弹琵琶，听那声音，铮铮然有京城的风味。问那人来历，她本是长安的歌女，曾向穆、曹两位乐师学琵琶，年长色衰，嫁给了商人做妻子。于是我命人摆酒，让她畅快地弹了几曲。弹完她神情悲戚，自述年少时的欢乐往事，如今漂泊憔悴，辗转在江湖之间。我离京外任两年，一向安然自适，听了她的话，这天晚上才感到被贬谪的况味。因而写了这首长句，作歌赠给她，共六百一十二字，题名《琵琶行》。

浔阳江头夜里送客，枫叶荻花在秋风里瑟瑟作响。主人下马、客人上船，举杯欲饮却没有音乐助兴。醉得不欢、凄凉地将要分别，分别时茫茫江水上浸着明月。忽然听见水上传来琵琶声，主人忘了回去、客人也不肯开船。顺着声音悄悄询问弹琵琶的是谁，琵琶声停了，想答话又迟疑。把船移近邀请相见，添酒挑灯重新开宴。千呼万唤她才出来，还抱着琵琶遮住半边脸。转轴拨弦试弹三两声，还没成曲调就已经含情。每一弦都掩抑低回、声声含思，像是在诉说一生的不得志。低着眉随手连续弹奏，说尽心中无限的心事。轻拢慢捻、抹过又挑，先弹《霓裳》后弹《六幺》。大弦嘈嘈像急雨，小弦切切像私语。嘈嘈切切交错弹奏，像大小珍珠落在玉盘上。间关的莺语在花底流滑，幽咽的泉水在冰下滞涩难流。冰泉冷涩、弦声凝绝，凝绝不通声音渐渐停歇。另有一种幽愁暗恨生出，此时无声胜有声。像银瓶突然破裂、水浆迸射，像铁骑突出、刀枪齐鸣。曲终时收拨在弦心一划，四弦同响一声如撕裂绸帛。东船西舫都悄无声息，只见江心一轮秋月皎白。她沉吟着放下拨子插在弦中，整顿衣裳、敛起面容。自言本是京城的女子，家在虾蟆陵下居住。十三岁学成琵琶，名字属于教坊第一部。曲子弹罢曾让乐师叹服，梳妆起来常被秋娘嫉妒。五陵少年争着送缠头，一曲下来红绡不知其数。钿头银篦打拍子都敲碎了，血色罗裙被酒污了也不惜。今年欢笑明年又欢笑，秋月春风都等闲度过。弟弟从军走了、阿姨也死了，暮去朝来容颜衰老。门前冷落、车马稀少，年老了便嫁给商人做妻。商人重利、看轻别离，上个月去浮梁买茶。他去了我就在江口守着空船，绕着船的月光清亮、江水寒冷。夜深忽然梦见少年时的往事，梦中啼哭、妆泪纵横。我听了琵琶已经叹息，又听了这番话更加唏嘘。同样是天涯沦落的人，相逢又何必曾经相识。我从去年辞别京城，贬居卧病在浔阳城。浔阳地方偏僻没有音乐，整年听不到丝竹之声。住处靠近湓江、地势低湿，黄芦苦竹绕着宅子生长。其间早晚听到的是什么，杜鹃啼血、猿猴哀鸣。春江花朝、秋月之夜，常常取酒独饮。难道没有山歌与村笛，可呕哑嘲哳实在难听。今夜听了你弹的琵琶，像听到仙乐、耳朵一时清明。请不要推辞，再坐下弹一曲，我为你翻写一首《琵琶行》。被我的话感动，她久久站立，退回坐下、把弦拧紧，弦声转急。凄凄的不像刚才的声音，满座的人听了都掩面哭泣。座中谁流的泪最多，江州司马的青衫都湿透了。', 'academic'),
  ('tangshi300', 113, '草', 'poems-xx2-10', '离离原上草，一岁一枯荣。
野火烧不尽，春风吹又生。
远芳侵古道，晴翠接荒城。
又送王孙去，萋萋满别情。', '原野上的草长得茂盛，一年枯一次又荣一次。野火烧不尽它，春风一吹又长出来。香气漫上古道，晴光接着荒城。今天又送友人远去，茂盛的草里满是离别的情绪。', 'school'),
  ('tangshi300', 114, '自河南经乱关内阻饥兄弟离散各在一处因望月有感聊书所怀寄上浮梁大兄於潜七兄乌江十五兄兼示符离及下邽弟妹', 'tangshi-ts-212', '时难年荒世业空，弟兄羁旅各西东。
田园寥落干戈后，骨肉流离道路中。
吊影分为千里雁，辞根散作九秋蓬。
共看明月应垂泪，一夜乡心五处同。', '时世艰难、年成荒歉，家业荡然无存，弟兄们羁旅漂泊、各在西东。田园在干戈之后寥落荒废，骨肉亲人在道路之中流离失散。顾影自怜、像分飞千里的孤雁，辞别故根、像散作九秋的飞蓬。我们一同望着明月应当落泪，一夜的思乡之心五处相同。', 'public-domain'),
  ('tangshi300', 115, '问刘十九', 'tangshi-ts-244', '绿蚁新醅酒，红泥小火炉。
晚来天欲雪，能饮一杯无。', '新酿的酒上浮着绿色的泡沫，红泥做的小火炉。傍晚天要下雪了，能来喝一杯吗。', 'public-domain'),
  ('tangshi300', 116, '后宫词', 'tangshi-ts-273', '泪湿罗巾梦不成，夜深前殿按歌声。
红颜未老恩先断，斜倚薰笼坐到明。', '泪水沾湿罗巾、睡不成梦，夜深时前殿传来按拍而歌的声音。红颜还未衰老、恩宠先已断绝，斜倚着薰笼一直坐到天明。', 'public-domain'),
  ('tangshi300', 117, '赠内人', 'tangshi-ts-274', '禁门宫树月痕过，媚眼惟看宿鹭窠。
斜拔玉钗灯影畔，剔开红焰救飞蛾。', '月光越过宫门与宫树，妩媚的眼睛只看着夜宿的白鹭窠。在灯影旁斜拔下发间的玉钗，剔开红焰去救那飞扑的飞蛾。', 'public-domain'),
  ('tangshi300', 118, '集灵台·其一', 'tangshi-ts-275', '日光斜照集灵台，红树花迎晓露开。
昨夜上皇新授箓，太真含笑入帘来。', '日光斜照着集灵台，红树的花迎着晓露开放。昨夜上皇新受符箓，太真含笑走进帘中来。', 'public-domain'),
  ('tangshi300', 119, '集灵台·其二', 'tangshi-ts-276', '虢国夫人承主恩，平明骑马入宫门。
却嫌脂粉污颜色，淡扫蛾眉朝至尊。', '虢国夫人承受君主的恩宠，天明时骑马进入宫门。却嫌脂粉污了容颜，只淡淡地画了眉毛去朝见天子。', 'public-domain'),
  ('tangshi300', 120, '题金陵渡', 'tangshi-ts-277', '金陵津渡小山楼，一宿行人自可愁。
潮落夜江斜月里，两三星火是瓜州。', '金陵渡口的小山楼，住上一宿的行人自然会发愁。潮水退落、夜江斜月在望，两三点星火的地方就是瓜州。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 121, '宫词', 'tangshi-ts-269', '玉楼天半起笙歌，风送宫嫔笑语和。
月殿影开闻夜漏，水晶帘卷近秋河。', '高耸入云的玉楼里响起笙歌，风送来宫嫔们的笑语声。月殿的影子散开，听到夜里的更漏声，水晶帘卷起，仿佛靠近了秋天的银河。', 'public-domain'),
  ('tangshi300', 122, '近试上张水部', 'tangshi-ts-279', '洞房昨夜停红烛，待晓堂前拜舅姑。
妆罢低声问夫婿，画眉深浅入时无。', '洞房里昨夜点着红烛，等到天明就要到堂前拜见公婆。梳妆完毕低声询问夫婿，画眉的深浅合不合时宜。', 'public-domain'),
  ('tangshi300', 123, '将赴吴兴登乐游原', 'tangshi-ts-280', '清时有味是无能，闲爱孤云静爱僧。
欲把一麾江海去，乐游原上望昭陵。', '清平之世有闲趣正是因为没有才能，闲时喜爱孤云、静时喜爱僧人。想持一支旌麾到江海去，在乐游原上遥望昭陵。', 'public-domain'),
  ('tangshi300', 124, '题扬州禅智寺', 'tangshi-ts-369', '雨过一蝉噪，飘萧松桂秋。
青苔满阶砌，白鸟故迟留。
暮霭生深树，斜阳下小楼。
谁知竹西路，歌吹是扬州。', '阵雨过后一只蝉噪鸣，松桂在风里飘动已见秋意。
青苔长满了台阶，白鸟故意迟迟不去。
暮霭从深树间升起，斜阳落下小楼。
谁能想到竹西路那边，歌吹喧闹的正是扬州。', 'public-domain'),
  ('tangshi300', 125, '遣怀', 'tangshi-ts-284', '落魄江湖载酒行，楚腰纤细掌中轻。
十年一觉扬州梦，赢得青楼薄幸名。', '落魄江湖、带着酒行走，楚地的腰肢纤细、舞姿轻盈能在掌上起舞。十年一觉、如同扬州的梦，只落得青楼里一个薄情的名声。', 'public-domain'),
  ('tangshi300', 126, '赤壁', 'tangshi-ts-281', '折戟沉沙铁未销，自将磨洗认前朝。
东风不与周郎便，铜雀春深锁二乔。', '折断的兵器沉在沙里、铁还没有销蚀，我把它磨洗一番、认出是前朝的遗物。如果东风不给周郎方便，铜雀台里恐怕已深锁着二乔了。', 'public-domain'),
  ('tangshi300', 127, '泊秦淮', 'tangshi-ts-282', '烟笼寒水月笼沙，夜泊秦淮近酒家。
商女不知亡国恨，隔江犹唱后庭花。', '烟雾笼罩着寒水、月光笼罩着沙，夜里停泊在秦淮河上、靠近酒家。歌女不懂亡国的遗恨，隔着江还在唱《后庭花》。', 'public-domain'),
  ('tangshi300', 128, '隋宫', 'tangshi-ts-215', '紫泉宫殿锁烟霞，欲取芜城作帝家。
玉玺不缘归日角，锦帆应是到天涯。
于今腐草无萤火，终古垂杨有暮鸦。
地下若逢陈后主，岂宜重问后庭花。', '长安的殿阁内弥漫着一片烟霞，杨广还想把芜城作为帝王之家。如果不是李渊得到传国的玉玺，那么他的龙舟还会游遍到天涯。如今隋朝的宫苑中已不见萤虫，只有低垂的杨柳和归巢的乌鸦。如果杨广在地下和陈后主相遇，有心欣赏淫逸辱国的后庭花吗？', 'public-domain'),
  ('tangshi300', 129, '寄扬州韩绰判官', 'tangshi-ts-283', '青山隐隐水迢迢，秋尽江南草未凋。
二十四桥明月夜，玉人何处教吹箫。', '青山隐隐、绿水迢迢，秋已尽了江南的草木还没凋零。二十四桥的明月之夜，你这位玉人在何处教人吹箫呢。', 'public-domain'),
  ('tangshi300', 130, '隋宫', 'tangshi-ts-298', '乘兴南游不戒严，九重谁省谏书函。
春风举国裁宫锦，半作障泥半作帆。', '隋炀帝为南游江都不顾安全，九重宫中有谁理会劝谏书函。春游中全国裁制的绫罗锦缎，一半作御马障泥一半作船帆。', 'public-domain'),
  ('tangshi300', 131, '赠别·其一', 'tangshi-ts-287', '娉娉袅袅十三余，豆蔻梢头二月初。
春风十里扬州路，卷上珠帘总不如。', '她姿态娉婷袅娜、才十三有余，像二月初豆蔻梢头的花。春风十里的扬州路上，卷起珠帘看来总比不上她。', 'public-domain'),
  ('tangshi300', 132, '赠别·其二', 'tangshi-ts-288', '多情却似总无情，惟觉樽前笑不成。
蜡烛有心还惜别，替人垂泪到天明。', '多情却像是总无情，只觉得在酒樽前笑不出来。蜡烛有心、还懂得惜别，替人流泪直到天明。', 'public-domain'),
  ('tangshi300', 133, '秋夕', 'tangshi-ts-285', '银烛秋光冷画屏，轻罗小扇扑流萤。
天阶夜色凉如水，卧看牵牛织女星。', '银烛的秋光映着清冷的画屏，她拿着轻罗小扇扑打流萤。天阶上的夜色凉如水，躺着看牵牛星与织女星。', 'public-domain'),
  ('tangshi300', 134, '金谷园', 'tangshi-ts-286', '繁华事散逐香尘，流水无情草自春。
日暮东风怨啼鸟，落花犹似坠楼人。', '繁华的往事随着香尘散去，流水无情、春草自绿。日暮时东风吹来、啼鸟哀怨，落花还像是那坠楼的人。', 'public-domain'),
  ('tangshi300', 135, '旅宿', 'tangshi-ts-157', '旅馆无良伴，凝情自悄然。
寒灯思旧事，断雁警愁眠。
远梦归侵晓，家书到隔年。
沧江好烟月，门系钓鱼船。', '旅馆里没有好友相伴，凝神静思、独自悄然。寒灯下回想旧事，失群孤雁的鸣叫惊醒愁眠。远梦归乡直到破晓，家书要到隔年才到。沧江上烟月美好，门前系着钓鱼的船。', 'public-domain'),
  ('tangshi300', 136, '早秋', 'tangshi-ts-159', '遥夜泛清瑟，西风生翠萝。
残萤栖玉露，早雁拂银河。
高树晓还密，远山晴更多。
淮南一叶下，自觉洞庭波。', '长夜里拨动清瑟，西风吹动翠绿的藤萝。残存的流萤栖息在玉露上，早飞的大雁掠过银河。高高的树木天亮时还很茂密，远山在晴天显得更多。淮南一片树叶落下，自己便感到洞庭湖起了波澜。', 'public-domain'),
  ('tangshi300', 137, '秋日赴阙题潼关驿楼', 'tangshi-ts-158', '红叶晚萧萧，长亭酒一瓢。
残云归太华，疏雨过中条。
树色随关迥，河声入海遥。
帝乡明日到，犹自梦渔樵。', '红叶在傍晚萧萧作响，长亭里饮下一瓢酒。残云归向太华山，疏雨掠过中条山。树色随着关塞延伸而变得遥远，黄河的水声遥遥流入大海。明天就要到达帝京，我却还在梦里想着渔樵生活。', 'public-domain'),
  ('tangshi300', 138, '锦瑟', 'poems-gz11-12', '锦瑟无端五十弦，一弦一柱思华年。
庄生晓梦迷蝴蝶，望帝春心托杜鹃。
沧海月明珠有泪，蓝田日暖玉生烟。
此情可待成追忆？只是当时已惘然。', '锦瑟啊，你为什么无缘无故地有五十根弦？每一弦每一柱都让我想起美好的年华。庄周在清晨的梦中迷上了蝴蝶，望帝把春心寄托在杜鹃的悲啼上。大海里明月高悬，鲛人的珍珠带着泪光；蓝田的日光温暖，美玉升起轻烟。这些情感哪里是等到日后追忆时才有的呢？只是当时就已经令人惘然若失了。', 'academic'),
  ('tangshi300', 139, '蝉', 'tangshi-ts-160', '本以高难饱，徒劳恨费声。
五更疏欲断，一树碧无情。
薄宦梗犹泛，故园芜已平。
烦君最相警，我亦举家清。', '你本来因为在高处而难以饱腹，徒劳地怨恨、白白费声。五更时叫声稀疏将要断绝，满树碧绿却无情不理。我官职微薄、像桃梗一样漂泊，故乡的田园已经荒芜平没。烦劳你最能给我警醒，我也是举家清贫。', 'public-domain'),
  ('tangshi300', 140, '乐游原', 'tangshi-ts-412', '向晚意不适，驱车登古原。
夕阳无限好，只是近黄昏。', '傍晚时心情不大舒畅，就赶着车登上了乐游原。落日的余晖真是无限美好，只可惜已经接近黄昏了。', 'public-domain'),
  ('tangshi300', 141, '夜雨寄北', 'poems-cz7-10', '君问归期未有期，巴山夜雨涨秋池。
何当共剪西窗烛，却话巴山夜雨时。', '你问我什么时候回去，我还没有确定的日期；巴山的夜雨下个不停，秋水涨满了池塘。什么时候我们才能在西窗下一起剪烛长谈，再来说说今夜巴山夜雨时我的心情。', 'academic'),
  ('tangshi300', 142, '韩碑', 'tangshi-ts-60', '元和天子神武姿，彼何人哉轩与羲。
誓将上雪列圣耻，坐法宫中朝四夷。
淮西有贼五十载，封狼生貙貙生罴。
不据山河据平地，长戈利矛日可麾。
帝得圣相相曰度，贼斫不死神扶持。
腰悬相印作都统，阴风惨澹天王旗。
愬武古通作牙爪，仪曹外郎载笔随。
行军司马智且勇，十四万众犹虎貔。
入蔡缚贼献太庙，功无与让恩不訾。
帝曰汝度功第一，汝从事愈宜为辞。
愈拜稽首蹈且舞，金石刻画臣能为。
古者世称大手笔，此事不系于职司。
当仁自古有不让，言讫屡颔天子颐。
公退斋戒坐小阁，濡染大笔何淋漓。
点窜尧典舜典字，涂改清庙生民诗。
文成破体书在纸，清晨再拜铺丹墀。
表曰臣愈昧死上，咏神圣功书之碑。
碑高三丈字如斗，负以灵鳌蟠以螭。
句奇语重喻者少，谗之天子言其私。
长绳百尺拽碑倒，粗砂大石相磨治。
公之斯文若元气，先时已入人肝脾。
汤盘孔鼎有述作，今无其器存其辞。
呜呼圣王及圣相，相与烜赫流淳熙。
公之斯文不示后，曷与三五相攀追。
愿书万本诵万过，口角流沫右手胝。
传之七十有二代，以为封禅玉检明堂基。', '元和天子有神武的英姿，他是什么样的人啊，如同轩辕与伏羲。发誓要洗雪列祖列宗的耻辱，坐在正殿上接受四夷朝拜。淮西有叛贼割据五十年，像封狼生貙、貙生罴一样世代相承。不凭山河之险，只占据平地，长戈利矛日日可以挥动。皇帝得到贤相名唤裴度，被叛贼砍伤却没有死，是神明在扶持。他腰间悬着相印做都统，阴风惨淡、天王的旗帜飘扬。李愬、韩公武、李道古、李文通做牙爪之将，仪曹外郎载笔随行。行军司马智勇双全，十四万大军如同虎貔。攻入蔡州缚住叛贼献于太庙，功劳无人能与相比，恩赏不可估量。皇帝说你裴度功劳第一，你的从事韩愈应当写一篇碑文。韩愈叩首拜谢、手舞足蹈，说金石刻画的文字臣能胜任。古来世上称为大手笔的，此事并不取决于职位。自古以来当仁不让，说完他屡次点头应承。韩公退朝后斋戒、坐在小阁中，饱蘸大笔、何等淋漓。点窜《尧典》《舜典》的文字，涂改《清庙》《生民》的诗篇。文章写成、以破体书写在纸上，清晨再拜铺在丹墀之上。表文说臣韩愈冒死进上，咏颂神圣之功、书写成碑。碑高三丈、字大如斗，由灵龟背负、螭龙盘绕。语句奇崛、言辞厚重，能理解的人很少，有人在天子面前进谗言说他有私心。用百尺长绳把碑拉倒，用粗砂大石来磨平。韩公这篇文字如同元气，先前已经深入人的肝脾。汤盘孔鼎都有述作，如今器物不存而文辞还在。唉，圣王与圣相，相互辉耀、流布淳厚的德化。韩公这篇文字若不传示后世，如何能与三皇五帝相追随呢。我愿书写万本、诵读万遍，诵得口角流沫、右手生茧。流传七十又二代，作为封禅的玉检、明堂的基石。', 'public-domain'),
  ('tangshi300', 143, '风雨', 'tangshi-ts-161', '凄凉宝剑篇，羁泊欲穷年。
黄叶仍风雨，青楼自管弦。
新知遭薄俗，旧好隔良缘。
心断新丰酒，销愁斗几千。', '凄凉地吟诵《宝剑篇》，漂泊羁旅将近一年。黄叶还在风雨中飘零，青楼里却自管弦歌舞。新交的朋友遭到浅薄世俗的非议，旧日的知交也隔断了良缘。心灰意冷不再指望新丰的酒，用来消愁一斗又要几千钱。', 'public-domain'),
  ('tangshi300', 144, '寄令狐郎中', 'tangshi-ts-296', '嵩云秦树久离居，双鲤迢迢一纸书。
休问梁园旧宾客，茂陵秋雨病相如。', '嵩山的云、秦地的树、我们久已分离两地，你从遥远的地方寄来一封书信。不要问梁园旧日的宾客怎样了，就像茂陵秋雨中卧病的司马相如。', 'public-domain'),
  ('tangshi300', 145, '筹笔驿', 'tangshi-ts-218', '猿鸟犹疑畏简书，风云常为护储胥。
徒令上将挥神笔，终见降王走传车。
管乐有才真不忝，关张无命欲何如。
他年锦里经祠庙，梁父吟成恨有余。', '猿猴鸟雀仿佛还畏惧军中的文书，风云常常为诸葛亮护卫营垒。徒然让上将挥动神笔筹画，终究还是看见投降的蜀主乘着传车而去。诸葛亮有管仲乐毅之才、真无愧色，关羽张飞命短、又能怎样。从前在锦里经过武侯祠庙，吟成《梁父吟》、遗恨无穷。', 'public-domain'),
  ('tangshi300', 146, '无题', 'tangshi-ts-214', '昨夜星辰昨夜风，画楼西畔桂堂东。
身无彩凤双飞翼，心有灵犀一点通。
隔座送钩春酒暖，分曹射覆蜡灯红。
嗟余听鼓应官去，走马兰台类转蓬。', '昨夜的星辰、昨夜的风，画楼的西畔、桂堂的东边。我身上没有彩凤那样双飞的翅膀，心里却像灵犀一点相通。隔着座位玩送钩、春酒正暖，分组玩射覆、蜡灯正红。可叹我听到更鼓就要去应差，骑马去兰台、像飘转的飞蓬。', 'public-domain'),
  ('tangshi300', 147, '无题·其一', 'tangshi-ts-216', '来是空言去绝踪，月斜楼上五更钟。
梦为远别啼难唤，书被催成墨未浓。
蜡照半笼金翡翠，麝熏微度绣芙蓉。
刘郎已恨蓬山远，更隔蓬山一万重。', '你说来只是空话、离去便无踪影，月斜楼上、已响起五更的钟。梦中因为远别而啼哭、难以唤醒，书信被催促写成、墨汁还未磨浓。烛光半笼着金翡翠的帷帐，麝香微微透过绣着芙蓉的被褥。刘郎已经怨恨蓬山遥远，何况更隔着蓬山一万重。', 'public-domain'),
  ('tangshi300', 148, '无题·其二', 'tangshi-ts-217', '飒飒东风细雨来，芙蓉塘外有轻雷。
金蟾啮锁烧香入，玉虎牵丝汲井回。
贾氏窥帘韩掾少，宓妃留枕魏王才。
春心莫共花争发，一寸相思一寸灰。', '飒飒的东风挟着细雨而来，芙蓉塘外传来轻轻的雷声。金蟾咬着锁钮、香烟由此而入，玉虎牵着丝绳、从井里汲水回来。贾氏在帘后窥看年轻的韩掾，宓妃留下枕头、爱慕魏王的才华。春心不要与花争着开放，一寸相思就成了一寸灰烬。', 'public-domain'),
  ('tangshi300', 149, '落花', 'tangshi-ts-162', '高阁客竟去，小园花乱飞。
参差连曲陌，迢递送斜晖。
肠断未忍扫，眼穿仍欲归。
芳心向春尽，所得是沾衣。', '高阁上的客人终于离去，小园里的花纷纷乱飞。参差不齐地连着曲折的路径，远远地送走斜阳。令人断肠、不忍心打扫，望眼欲穿、仍盼着它归来。芳心随着春天一同消尽，所得的只是泪湿衣裳。', 'public-domain'),
  ('tangshi300', 150, '为有', 'tangshi-ts-297', '为有云屏无限娇，凤城寒尽怕春宵。
无端嫁得金龟婿，辜负香衾事早朝。', '因为有着云母屏风后的无限娇美，京城里寒冬已尽、却怕这春宵。无缘无故嫁了个佩金龟的夫婿，辜负了温暖的被褥、去上早朝。', 'public-domain'),
  ('tangshi300', 151, '瑶池', 'tangshi-ts-299', '瑶池阿母绮窗开，黄竹歌声动地哀。
八骏日行三万里，穆王何事不重来。', '瑶池的西王母打开绮窗，黄竹的歌声动地哀伤。八匹骏马一天能走三万里，周穆王为了什么事不再重来。', 'public-domain'),
  ('tangshi300', 152, '春雨', 'tangshi-ts-219', '怅卧新春白袷衣，白门寥落意多违。
红楼隔雨相望冷，珠箔飘灯独自归。
远路应悲春晼晚，残宵犹得梦依稀。
玉珰缄札何由达，万里云罗一雁飞。', '新春里惆怅地卧着、穿着白色夹衣，白门寥落、心意多有不合。隔着雨望那红楼、只觉清冷，珠帘飘着灯光、我独自归去。远路之上应为春暮而悲伤，残夜之中还能依稀入梦。玉珰与书信怎样才能送到，万里云天如罗、一只大雁飞过。', 'public-domain'),
  ('tangshi300', 153, '嫦娥', 'poems-xx4-18', '云母屏风烛影深，
长河渐落晓星沉。
嫦娥应悔偷灵药，
碧海青天夜夜心。', '云母屏风上映着深深的烛影，银河渐渐西斜，晨星沉落。嫦娥想必后悔偷了不死药，面对碧海青天夜夜孤寂。', 'school'),
  ('tangshi300', 154, '贾生', 'tangshi-ts-301', '宣室求贤访逐臣，贾生才调更无伦。
可怜夜半虚前席，不问苍生问鬼神。', '汉文帝在宣室寻求贤才、征访被贬的臣子，贾生的才气更是无与伦比。可惜夜半白白地移席向前，不问百姓生计、只问鬼神之事。', 'public-domain'),
  ('tangshi300', 155, '凉思', 'tangshi-ts-163', '客去波平槛，蝉休露满枝。
永怀当此节，倚立自移时。
北斗兼春远，南陵寓使迟。
天涯占梦数，疑误有新知。', '客人离去时水波平齐着栏杆，蝉声停息、露水满枝。长久的思念正当这个时节，倚立在那里不知不觉过了许久。北斗星连同春天一样遥远，南陵的使者来得很迟。天涯之远屡屡占梦，疑心你误听而有了新交。', 'public-domain'),
  ('tangshi300', 156, '北青萝', 'tangshi-ts-164', '残阳西入崦，茅屋访孤僧。
落叶人何在，寒云路几层。
独敲初夜磬，闲倚一枝藤。
世界微尘里，吾宁爱与憎。', '残阳向西落入崦嵫山，我到茅屋去拜访独居的僧人。落叶纷纷、人在何处，寒云弥漫、山路有几层。他独自敲着初夜的磬，闲来倚着一枝藤杖。大千世界不过微尘一粒，我何必还要执著于爱与憎。', 'public-domain'),
  ('tangshi300', 157, '望月怀远', 'tangshi-ts-96', '海上生明月，天涯共此时。
情人怨遥夜，竟夕起相思。
灭烛怜光满，披衣觉露滋。
不堪盈手赠，还寝梦佳期。', '海上生起一轮明月，天各一方的人此时共同遥望。多情的人怨恨这漫长的夜，整个晚上都生出相思。熄了蜡烛怜惜那满屋清光，披上衣裳感到露水沾湿。不能把月光捧满手赠给你，只好回去就寝、在梦中相会。', 'public-domain'),
  ('tangshi300', 158, '题大庾岭北驿', 'tangshi-ts-101', '阳月南飞雁，传闻至此回。
我行殊未已，何日复归来。
江静潮初落，林昏瘴不开。
明朝望乡处，应见陇头梅。', '十月里南飞的大雁，传闻到这里就折回。我的行程却远未停止，何日才能回去。江面平静、潮水刚退，林中昏暗、瘴气不开。明天早上遥望故乡的地方，应当能看见岭头的梅花。', 'public-domain'),
  ('tangshi300', 159, '渡汉江', 'tangshi-ts-248', '岭外音书绝，经冬复立春。
近乡情更怯，不敢问来人。', '岭外与家乡的音信断绝，过了冬天又到立春。越靠近家乡、心情越是怯怯，不敢询问从家乡来的人。', 'public-domain'),
  ('tangshi300', 160, '新年作', 'tangshi-ts-141', '乡心新岁切，天畔独潸然。
老至居人下，春归在客先。
岭猿同旦暮，江柳共风烟。
已似长沙傅，从今又几年。', '思乡之心在新年更加迫切，天涯边上独自泪流。年老却位居人下，春天归去比我这客子还早。与岭上的猿猴同度早晚，与江边的柳树共受风烟。我已经像被贬长沙的贾谊，从今往后又要几年。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 161, '送杜少府之任蜀州', 'poems-cz8-21', '城阙辅三秦，风烟望五津。
与君离别意，同是宦游人。
海内存知己，天涯若比邻。
无为在歧路，儿女共沾巾。', '长安城被三秦之地拱卫着，遥望蜀州的五个渡口只见风烟迷蒙。与你分别，心中满怀情意，因为我们都是在外做官的人。只要四海之内有知心朋友，即使远在天涯也像近邻一样。不要在岔路口分手的时候，像小儿女一样挥泪沾湿了手巾。', 'school'),
  ('tangshi300', 162, '和晋陵陆丞早春游望', 'tangshi-ts-99', '独有宦游人，偏惊物候新。
云霞出海曙，梅柳渡江春。
淑气催黄鸟，晴光转绿苹。
忽闻歌古调，归思欲沾巾。', '只有宦游在外的人，才特别惊觉物候的变化。云霞从海上透出曙光，梅柳渡过江来带来春意。和暖的气息催促黄鸟鸣叫，晴朗的阳光使绿苹转动。忽然听到你唱起古雅的曲调，归乡的思绪使我泪湿手巾。', 'public-domain'),
  ('tangshi300', 163, '楚江怀古', 'tangshi-ts-167', '露气寒光集，微阳下楚丘。
猿啼洞庭树，人在木兰舟。
广泽生明月，苍山夹乱流。
云中君不见，竟夕自悲秋。', '露气与寒光聚集，微弱的夕阳落下楚地的山丘。猿猴在洞庭的树上啼叫，人坐在木兰舟中。广阔的湖泽上升起明月，苍茫的山中夹着乱流。云中的神君见不到，整夜独自悲秋。', 'public-domain'),
  ('tangshi300', 164, '灞上秋居', 'tangshi-ts-166', '灞原风雨定，晚见雁行频。
落叶他乡树，寒灯独夜人。
空园白露滴，孤壁野僧邻。
寄卧郊扉久，何年致此身。', '灞原上风雨初定，傍晚频频望见雁行。落叶是他乡的树，寒灯下是独夜的人。空园里白露滴落，孤壁边与野僧为邻。寄居在郊外的门扉已久，何年才能有所作为。', 'public-domain'),
  ('tangshi300', 165, '马嵬坡', 'tangshi-ts-290', '玄宗回马杨妃死，云雨难忘日月新。
终是圣明天子事，景阳宫井又何人。', '玄宗回马时杨妃已死，云雨之情难忘、而日月已新。终究还是圣明天子的行事，那景阳宫井中的陈后主又算什么人呢。', 'public-domain'),
  ('tangshi300', 166, '寻隐者不遇', 'poems-xx1-10', '松下问童子，言师采药去。
只在此山中，云深不知处。', '在松树下问小童师父去哪儿了，他说师父采药去了。就在这座山里，云雾深深不知在何处。', 'school'),
  ('tangshi300', 167, '利州南渡', 'tangshi-ts-220', '澹然空水对斜晖，曲岛苍茫接翠微。
波上马嘶看棹去，柳边人歇待船归。
数丛沙草群鸥散，万顷江田一鹭飞。
谁解乘舟寻范蠡，五湖烟水独忘机。', '空阔的水面淡然对着斜阳，曲折的岛屿苍茫接着青翠的山色。波浪上马在嘶鸣、看船桨划去，柳边有人歇息、等待船回来。几丛沙草、群鸥惊散，万顷江田、一只白鹭飞翔。谁能懂得乘舟去寻访范蠡，在五湖的烟水中独自忘掉机心。', 'public-domain'),
  ('tangshi300', 168, '瑶瑟怨', 'tangshi-ts-289', '冰簟银床梦不成，碧天如水夜云轻。
雁声远过潇湘去，十二楼中月自明。', '冰凉的竹席、银色的床、梦也做不成，碧天如水、夜云轻淡。雁声远远地越过潇湘而去，十二楼中明月自照。', 'public-domain'),
  ('tangshi300', 169, '送人东游', 'tangshi-ts-165', '荒戍落黄叶，浩然离故关。
高风汉阳渡，初日郢门山。
江上几人在，天涯孤棹还。
何当重相见，樽酒慰离颜。', '荒凉的戍楼落下黄叶，你意气浩然地离开故关。高风吹过汉阳渡，初日照着郢门山。江上还有几个人，天涯外一只孤舟归去。什么时候才能重见，举杯慰藉这离别的容颜。', 'public-domain'),
  ('tangshi300', 170, '苏武庙', 'tangshi-ts-221', '苏武魂销汉使前，古祠高树两茫然。
云边雁断胡天月，陇上羊归塞草烟。
回日楼台非甲帐，去时冠剑是丁年。
茂陵不见封侯印，空向秋波哭逝川。', '苏武在汉使面前神魂震撼，古祠与高树都一片茫然。云边的雁影断绝在胡天的月下，陇上的羊群归来在塞草的烟雾中。回来时楼台已经不是当年的甲帐，离去时加冠佩剑正当壮年。汉武帝已看不到他封侯的印绶，只能空对着秋水哀哭逝去的岁月。', 'public-domain'),
  ('tangshi300', 171, '书边事', 'tangshi-ts-168', '调角断清秋，征人倚戍楼。
春风对青冢，白日落梁州。
大漠无兵阻，穷边有客游。
蕃情似此水，长愿向南流。', '号角声断断续续地响在清秋，征人倚在戍楼上。春风对着青冢，白日落在梁州。大漠上没有兵阻，极远的边地还有客子游历。蕃人的心意就像这河水，但愿长久地向南流。', 'public-domain'),
  ('tangshi300', 172, '贫女', 'tangshi-ts-354', '蓬门未识绮罗香，拟托良媒益自伤。
谁爱风流高格调，共怜时世俭梳妆。
敢将十指夸针巧，不把双眉斗画长。
苦恨年年压金线，为他人作嫁衣裳。', '生在蓬门小户，从没见识过绮罗的芳香，想托个好媒人，反而更添感伤。
有谁赏识风流高雅的格调？人们都喜爱时兴的俭朴梳妆。
我敢用十指夸耀针线精巧，却不愿描长双眉与人争妍。
最恨年年压线刺绣，都是替别人做嫁衣。', 'public-domain'),
  ('tangshi300', 173, '春宫怨', 'tangshi-ts-171', '早被婵娟误，欲妆临镜慵。
承恩不在貌，教妾若为容。
风暖鸟声碎，日高花影重。
年年越溪女，相忆采芙蓉。', '早年就被美貌所误，想梳妆却对着镜子懒懒的。承受恩宠并不在于容貌，叫我如何打扮才好。风暖、鸟声细碎，日高、花影重叠。年年想起越溪的女子，一同采摘芙蓉的情景。', 'public-domain'),
  ('tangshi300', 174, '孤雁', 'tangshi-ts-170', '几行归塞尽，念尔独何之。
暮雨相呼失，寒塘欲下迟。
渚云低暗度，关月冷相随。
未必逢矰缴，孤飞自可疑。', '几行大雁归向边塞都已飞尽，想你独自要到哪里去。暮雨中互相呼唤却失散了，寒塘上想落下又迟疑。水洲的云低低压过，关塞的月冷冷相随。未必会遇到箭矢，可你独自飞翔总令人担心。', 'public-domain'),
  ('tangshi300', 175, '巴山道中除夜书怀', 'tangshi-ts-169', '迢递三巴路，羁危万里身。
乱山残雪夜，孤烛异乡人。
渐与骨肉远，转于僮仆亲。
那堪正飘泊，明日岁华新。', '三巴的道路多么遥远，羁旅艰危，身在万里之外。乱山残雪的除夕之夜，一支孤烛伴着异乡人。渐渐与骨肉亲人远离，转而与僮仆亲近。哪里受得了正漂泊无依，明天又是新的一年。', 'public-domain'),
  ('tangshi300', 176, '已凉', 'tangshi-ts-291', '碧阑干外绣帘垂，猩色屏风画折枝。
八尺龙须方锦褥，已凉天气未寒时。', '碧色的栏杆外绣帘低垂，猩红色的屏风上画着折枝花。八尺的龙须草席与方形的锦褥，正是天气已凉而未寒的时候。', 'public-domain'),
  ('tangshi300', 177, '章台夜思', 'tangshi-ts-172', '清瑟怨遥夜，绕弦风雨哀。
孤灯闻楚角，残月下章台。
芳草已云暮，故人殊未来。
乡书不可寄，秋雁又南回。', '清瑟哀怨地响在长夜，绕着琴弦是风雨般的悲声。孤灯下听到楚地的号角，残月沉下章台。芳草已经衰暮，老朋友却始终不来。家书无法寄出，秋雁又向南飞回。', 'public-domain'),
  ('tangshi300', 178, '金陵图', 'tangshi-ts-359', '谁谓伤心画不成，画人心逐世人情。
君看六幅南朝事，老木寒云满故城。', '谁说伤心的景致画不成？只是画家的心追逐着世俗的人情。
你看这六幅描绘南朝旧事的画，老树寒云布满整座故城。', 'public-domain'),
  ('tangshi300', 179, '台城', 'tangshi-ts-292', '江雨霏霏江草齐，六朝如梦鸟空啼。
无情最是台城柳，依旧烟笼十里堤。', '江上细雨霏霏、江草齐整，六朝的往事如梦、鸟儿空自啼叫。最无情的要数台城的柳树，依旧烟雾笼罩着十里长堤。', 'public-domain'),
  ('tangshi300', 180, '在狱咏蝉·并序', 'tangshi-ts-98', '余禁所禁垣西，是法厅事也，有古槐数株焉。虽生意可知，同殷仲文之古树；而听讼斯在，即周召伯之甘棠。每至夕照低阴，秋蝉疏引，发声幽息，有切尝闻。岂人心异于曩时，将虫响悲于前听？嗟乎，声以动容，德以象贤。故洁其身也，禀君子达人之高行；蜕其皮也，有仙都羽化之灵姿。候时而来，顺阴阳之数；应节为变，审藏用之机。有目斯开，不以道昏而昧其视；有翼自薄，不以俗厚而易其真。吟乔树之微风，韵姿天纵；饮高秋之坠露，清畏人知。仆失路艰虞，遭时徽纆。不哀伤而自怨，未摇落而先衰。闻蟪蛄之流声，悟平反之已奏；见螳螂之抱影，怯危机之未安。感而缀诗，贻诸知己。庶情沿物应，哀弱羽之飘零；道寄人知，悯余声之寂寞。非谓文墨，取代幽忧云尔。
西陆蝉声唱，南冠客思深。
不堪玄鬓影，来对白头吟。
露重飞难进，风多响易沉。
无人信高洁，谁为表予心。', '我被囚禁的院墙西边，是法厅所在地，有几株古槐。虽然生机还看得出，却如殷仲文所见的古树；而这里听讼断案，就像周召伯的甘棠。每到夕阳低照、阴影下垂，秋蝉稀疏地鸣唱，发出幽微的声息，比从前听过的更觉凄切。难道是人心与往昔不同，还是虫鸣比从前更悲呢？唉，声音能打动人的容貌，德行可以象征贤人。所以它清洁自身，禀有君子达人的高行；它蜕去皮壳，有仙都羽化的灵姿。按时令而来，顺应阴阳的规律；随节候而变，明察隐显的机微。有眼就睁开，不因世道昏乱而遮蔽视力；有翅自然轻薄，不因世俗厚重而改变本性。在乔木的微风里吟唱，风韵姿质天生；饮高秋的坠露，清高怕人知道。我迷失道路、处境艰难，遭遇牢狱之灾。不哀伤而自怨，还没到摇落就先衰败。听见蟪蛄的鸣声，悟到平反的奏章已经上达；看见螳螂抱影，惧怕危机还未安定。感于此而写成诗，赠给知己。但愿情随物应，哀怜这弱羽的飘零；道理寄于人所知，怜悯我余声的寂寞。并非要论文墨，只是借此排遣幽忧而已。

西方秋蝉鸣唱，牢中囚客的思绪深沉。不堪那玄鬓的蝉影，来对着我这白头吟咏。露水重、飞也难进，风多声响容易沉没。没人相信我的高洁，谁能为我表白心迹。', 'public-domain'),
  ('tangshi300', 181, '代悲白头翁', 'tangshi-ts-376', '洛阳城东桃李花，飞来飞去落谁家？
洛阳女儿惜颜色，行逢落花长叹息。
今年花落颜色改，明年花开复谁在？
已见松柏摧为薪，更闻桑田变成海。
古人无复洛城东，今人还对落花风。
年年岁岁花相似，岁岁年年人不同。
寄言全盛红颜子，应怜半死白头翁。
此翁白头真可怜，伊昔红颜美少年。
公子王孙芳树下，清歌妙舞落花前。
光禄池台文锦绣，将军楼阁画神仙。
一朝卧病无相识，三春行乐在谁边？
宛转蛾眉能几时？须臾鹤发乱如丝。
但看古来歌舞地，唯有黄昏鸟雀悲。', '洛阳城东的桃花李花，飞来飞去落到了谁家？洛阳的女儿爱惜自己的容貌，路上遇见落花就长声叹息。今年花落了容颜也随之改变，明年花开时又是谁还在？已经见到松柏被砍成柴薪，更听说桑田变成了沧海。古人不会再回到洛城东，今人却还对着落花伤风。年年岁岁花都一样，岁岁年年人却不同。
奉劝那些正当盛年的红颜少年，也该怜惜这半死的白头老翁。这老翁白头实在可怜，他从前也是红颜少年。当年在公子王孙的芳树下，在落花前清歌妙舞。光禄寺的池台铺着锦绣，将军的楼阁画着神仙。一朝卧病就无人相识，当年三春的行乐又在哪里？宛转的蛾眉还能有几时？转眼间白发就乱如丝。只要看看自古以来的歌舞之地，只剩下黄昏时分鸟雀的悲鸣。', 'public-domain'),
  ('tangshi300', 182, '登幽州台歌', 'poems-cz7-18', '前不见古人，后不见来者。
念天地之悠悠，独怆然而涕下！', '往前看不到古代的贤君，往后也看不到后世的明主。想到天地是这样辽阔久远，我独自悲伤，泪流满面！', 'academic'),
  ('tangshi300', 183, '寄人', 'tangshi-ts-293', '别梦依依到谢家，小廊回合曲阑斜。
多情只有春庭月，犹为离人照落花。', '别后的梦依依地来到谢家，小廊回环、曲栏斜斜。多情的只有春天庭院的月亮，还为离别的人照着落花。', 'public-domain'),
  ('tangshi300', 184, '陇西行', 'tangshi-ts-391', '誓扫匈奴不顾身，五千貂锦丧胡尘。
可怜无定河边骨，犹是春闺梦里人。', '将士们发誓扫平匈奴，奋不顾身；五千名身穿貂锦的精锐都丧身在胡地的战尘里。可怜那无定河边的白骨，还是妻子春闺梦中思念的人。', 'public-domain'),
  ('tangshi300', 185, '哥舒歌', 'tangshi-ts-250', '北斗七星高，哥舒夜带刀。
至今窥牧马，不敢过临洮。', '北斗七星高悬，哥舒翰夜里佩刀巡边。至今胡人窥探着牧马，不敢越过临洮。', 'public-domain'),
  ('tangshi300', 186, '杂诗', 'tangshi-ts-294', '近寒食雨草萋萋，著麦苗风柳映堤。
等是有家归未得，杜鹃休向耳边啼。', '临近寒食、细雨绵绵、春草萋萋，风吹麦苗、柳树映着长堤。同样是有家却回不去，杜鹃啊不要在我耳边啼叫。', 'public-domain'),
  ('tangshi300', 187, '寻陆鸿渐不遇', 'tangshi-ts-442', '移家虽带郭，野径入桑麻。
近种篱边菊，秋来未著花。
扣门无犬吠，欲去问西家。
报道山中去，归时每日斜。', '他的新家虽在城郭附近，野外小径却通向桑麻丛中。篱笆边新近种下的菊花，到了秋天还没有开花。敲门听不到一声犬吠，想要离去时又去问西边的邻居。邻人回答他进山去了，回来时往往太阳已经西斜。', 'public-domain'),
  ('tangshi300', 188, '清平调·其一', 'yuefu-yf-75·1', '云想衣裳花想容，春风拂槛露华浓。
若非群玉山头见，会向瑶台月下逢。', '见云便想到她的衣裳，见花便想到她的容颜，春风吹拂着栏杆，露水正浓。若不是在群玉山头相见，就该在瑶台的月光下相逢。', 'public-domain'),
  ('tangshi300', 189, '杂诗', 'tangshi-ts-226', '君自故乡来，应知故乡事。
来日绮窗前，寒梅著花未。', '你从故乡来，应当知道故乡的事。你来的时候，雕花窗前的那株寒梅开花了没有。', 'public-domain'),
  ('tangshi300', 190, '回乡偶书·其一', 'poems-xx6-07', '少小离家老大回，乡音无改鬓毛衰。
儿童相见不相识，笑问客从何处来。', '年少时离开家乡，年老时才回来，家乡的口音没变，鬓发却已稀疏。家乡的孩子见了我不认识，笑着问我是从哪里来的客人。', 'school'),
  ('tangshi300', 191, '回乡偶书·其二', 'tangshi-ts-252', '离别家乡岁月多，近来人事半消磨。
惟有门前镜湖水，春风不改旧时波。', '离别家乡的岁月已经很多，近来人事多半消磨改变。只有门前镜湖的水，春风吹过还是旧时的波澜。', 'public-domain'),
  ('tangshi300', 192, '次北固山下', 'poems-cz7-03', '客路青山外，行舟绿水前。
潮平两岸阔，风正一帆悬。
海日生残夜，江春入旧年。
乡书何处达？归雁洛阳边。', '旅人要走的路在青山之外，船行在绿水中。潮水涨满，两岸顿时开阔；顺风行驶，船帆高高悬起。红日在残夜中升起，江南的春天在旧年未尽时到来。写给家里的信什么时候才能送到？希望北归的大雁把它带到洛阳。', 'school'),
  ('tangshi300', 193, '桃花溪', 'tangshi-ts-253', '隐隐飞桥隔野烟，石矶西畔问渔船。
桃花尽日随流水，洞在清溪何处边。', '隐隐约约的飞桥隔着野外的烟雾，在石矶的西边询问渔船。桃花整日随着流水漂去，那桃花洞在清溪的哪一边呢。', 'public-domain'),
  ('tangshi300', 194, '送别', 'tangshi-ts-224', '山中相送罢，日暮掩柴扉。
春草明年绿，王孙归不归。', '在深山里送走友人，日暮时掩上柴门。春草到明年又绿的时候，你回不回来呢。', 'public-domain'),
  ('tangshi300', 195, '送綦毋潜落第还乡', 'tangshi-ts-11', '圣代无隐者，英灵尽来归。
遂令东山客，不得顾采薇。
既至金门远，孰云吾道非。
江淮度寒食，京洛缝春衣。
置酒长安道，同心与我违。
行当浮桂棹，未几拂荆扉。
远树带行客，孤城当落晖。
吾谋适不用，勿谓知音稀。', '清明盛世没有隐逸的人，俊杰之士都来归附朝廷。这便使你这隐居东山的高士，也无暇再去采薇隐居了。既然来到京城却未能入选，谁能说你我的主张不对呢。你将在江淮一带度过寒食，在京城洛阳缝制春衣。我在长安道上设酒送别，志同道合的你却要与我分离。你即将乘船远行，不久就要叩响家乡的柴门。远处的树木映带着行客，孤零零的城郭对着落日余晖。我的主张只是暂时不被采用，不要说知音稀少。', 'public-domain'),
  ('tangshi300', 196, '青溪', 'tangshi-ts-13', '言入黄花川，每逐青溪水。
随山将万转，趣途无百里。
声喧乱石中，色静深松里。
漾漾泛菱荇，澄澄映葭苇。
我心素已闲，清川澹如此。
请留盘石上，垂钓将已矣。', '我进入黄花川，常常追随着青溪的水流。随着山势千回万转，路程却不到百里。水声在乱石间喧响，水色在深松林里幽静。水波荡漾漂着菱叶荇菜，水光澄澈映着芦苇。我的心本来就很闲适，清澈的溪流也如此恬淡。请让我留在溪边的盘石上，垂钓度日就此了此一生吧。', 'public-domain'),
  ('tangshi300', 197, '渭川田家', 'tangshi-ts-14', '斜阳照墟落，穷巷牛羊归。
野老念牧童，倚杖候荆扉。
雉雊麦苗秀，蚕眠桑叶稀。
田夫荷锄立，相见语依依。
即此羡闲逸，怅然吟式微。', '斜阳照着村庄，深巷里牛羊回来了。老人惦记着放牧的孩子，拄着拐杖在柴门前等候。野鸡鸣叫，麦苗正在抽穗；蚕儿休眠，桑叶已经稀疏。农夫扛着锄头站立，彼此相见话语依依。看到这些，我羡慕这种闲适安逸，惆怅地吟起《式微》来。', 'public-domain'),
  ('tangshi300', 198, '西施咏', 'tangshi-ts-15', '艳色天下重，西施宁久微。
朝为越溪女，暮作吴宫妃。
贱日岂殊众，贵来方悟稀。
邀人傅香粉，不自著罗衣。
君宠益娇态，君怜无是非。
当时浣纱伴，莫得同车归。
持谢邻家子，效颜安可希。', '美色为天下人所看重，西施怎能长久微贱呢。早晨她还是越溪边浣纱的女子，傍晚就成了吴王宫中的宠妃。贫贱时她与众人有什么不同，显贵之后才让人感到她的稀罕。她要别人给她搽香粉，自己连罗衣都不动手穿。君王的宠爱使她更加娇态百出，君王的怜爱让她没有是非的顾虑。当年一起浣纱的伙伴，没有一个能与她同车而归。我借这话奉告邻家的姑娘，想要效仿她的美貌又怎能指望得上呢。', 'public-domain'),
  ('tangshi300', 199, '老将行', 'tangshi-ts-69', '少年十五二十时，步行夺得胡马骑。
射杀山中白额虎，肯数邺下黄须儿。
一身转战三千里，一剑曾当百万师。
汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。
卫青不败由天幸，李广无功缘数奇。
自从弃置便衰朽，世事蹉跎成白首。
昔时飞箭无全目，今日垂杨生左肘。
路旁时卖故侯瓜，门前学种先生柳。
苍茫古木连穷巷，寥落寒山对虚牖。
誓令疏勒出飞泉，不似颍川空使酒。
贺兰山下阵如云，羽檄交驰日夕闻。
节使三河募年少，诏书五道出将军。
试拂铁衣如雪色，聊持宝剑动星文。
愿得燕弓射大将，耻令越甲鸣吾君。
莫嫌旧日云中守，犹堪一战取功勋。', '少年十五二十岁的时候，步行夺过胡人的马骑。射杀山中的白额猛虎，哪肯把邺下的黄须儿曹操放在眼里。一身转战三千里，一把剑曾抵挡百万大军。汉兵奋迅如霹雳，敌骑崩溃奔逃、畏惧蒺藜。卫青不败是因为天幸，李广无功是因为命运不好。自从被弃置不用便衰朽了，世事蹉跎，已成白头。从前神箭能射中飞鸟的眼，如今左肘上长了瘤如垂柳。在路旁时时卖着故侯的瓜，在门前学陶渊明种着柳树。苍茫的古木连着深巷，寥落的寒山对着空窗。发誓要如耿恭让疏勒涌出飞泉，不像颍川的灌夫那样空自使酒骂座。贺兰山下军阵如云，插羽毛的紧急军书日夜交驰。节度使在三河招募少年，诏书分五道出兵、将军出征。我试着拂拭铁甲如雪的颜色，姑且持起宝剑、剑上星文晃动。愿得到燕地的良弓去射敌将，以让越国的甲兵惊扰我的君王为耻。不要嫌弃旧日的云中太守，他还能一战去夺取功勋。', 'public-domain'),
  ('tangshi300', 200, '桃源行', 'tangshi-ts-70', '渔舟逐水爱山春，两岸桃花夹古津。
坐看红树不知远，行尽青溪不见人。
山口潜行始隈隩，山开旷望旋平陆。
遥看一处攒云树，近入千家散花竹。
樵客初传汉姓名，居人未改秦衣服。
居人共住武陵源，还从物外起田园。
月明松下房栊静，日出云中鸡犬喧。
惊闻俗客争来集，竞引还家问都邑。
平明闾巷扫花开，薄暮渔樵乘水入。
初因避地去人间，及至成仙遂不还。
峡里谁知有人事，世中遥望空云山。
不疑灵境难闻见，尘心未尽思乡县。
出洞无论隔山水，辞家终拟长游衍。
自谓经过旧不迷，安知峰壑今来变。
当时只记入山深，青溪几曲到云林。
春来遍是桃花水，不辨仙源何处寻。', '渔船顺着溪水前行，喜爱山中的春色，两岸桃花夹着古老的渡口。坐着看红树不知走了多远，行遍青溪也不见人影。从山口悄悄前行进入曲折的深处，山势开阔、豁然望见一片平地。远远看见一处云树攒聚，走近了是千家散落着花竹。打柴的人初次听说汉朝的姓名，居民还没有改变秦代的衣装。居民们共同住在武陵源，从世外建起了田园。月明时松下房舍静寂，日出云中鸡犬喧闹。惊闻有世俗的客人，争先聚集，争相引他还家询问故乡。天明时里巷扫净、打开门，傍晚渔人樵夫乘船进来。当初为躲避乱世离开人间，等到成了仙便不再回去。峡谷里谁知道有人间的事，世人遥遥望去只见空蒙的云山。他不疑这样的灵境难以遇见，只是尘心未尽、思念家乡。出洞后不论隔着山水，辞别家人终究打算长久地游历。自以为经过的地方不会迷路，哪里知道山峰沟壑如今已经改变。当时只记得进入山中很深，青溪几曲就通到云林。春天来时遍地是桃花水，分不清仙源在哪里去寻找。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 201, '洛阳女儿行', 'tangshi-ts-71', '洛阳女儿对门居，才可颜容十五余。
良人玉勒乘骢马，侍女金盘脍鲤鱼。
画阁朱楼尽相望，红桃绿柳垂檐向。
罗帏送上七香车，宝扇迎归九华帐。
狂夫富贵在青春，意气骄奢剧季伦。
自怜碧玉亲教舞，不惜珊瑚持与人。
春窗曙灭九微火，九微片片飞花琐。
戏罢曾无理曲时，妆成只是薰香坐。
城中相识尽繁华，日夜经过赵李家。
谁怜越女颜如玉，贫贱江头自浣纱。', '洛阳的女儿住在对门，容貌才十五有余。丈夫戴着玉勒、骑着骢马，侍女用金盘盛着细切的鲤鱼。画阁朱楼处处相望，红桃绿柳垂向屋檐。用罗帏送上七香车，用宝扇迎回九华帐。丈夫富贵正当青春，意气骄奢超过石崇。自怜妻子美好而亲自教她舞蹈，不惜把珊瑚拿去送人。春窗破晓时熄了九微灯，灯花片片飞落。嬉戏过后不曾整理乐曲，梳妆好了只是熏香端坐。城中相识的都是繁华人家，日夜来往于赵李之家。谁怜惜那越地的女子容颜如玉，却贫贱地在江头独自浣纱。', 'public-domain'),
  ('tangshi300', 202, '辋川闲居赠裴秀才迪', 'tangshi-ts-120', '寒山转苍翠，秋水日潺湲。
倚杖柴门外，临风听暮蝉。
渡头余落日，墟里上孤烟。
复值接舆醉，狂歌五柳前。', '寒山转成苍翠，秋水日日潺潺流淌。我拄着拐杖站在柴门之外，迎着风听傍晚的蝉鸣。渡头还留着落日，村落里升起一缕孤烟。又遇上像接舆一样醉酒的裴迪，在五柳前放声狂歌。', 'public-domain'),
  ('tangshi300', 203, '酬张少府', 'tangshi-ts-124', '晚年惟好静，万事不关心。
自顾无长策，空知返旧林。
松风吹解带，山月照弹琴。
君问穷通理，渔歌入浦深。', '晚年只喜欢清静，万事都不关心。自思没有好的计策，只知道回归旧日的山林。松风吹来解开衣带，山月照着弹琴。你问穷困与通达的道理，渔歌正传入那深深的浦口。', 'public-domain'),
  ('tangshi300', 204, '送梓州李使君', 'tangshi-ts-126', '万壑树参天，千山响杜鹃。
山中一夜雨，树杪百重泉。
汉女输橦布，巴人讼芋田。
文翁翻教授，不敢倚先贤。', '万壑之中树木参天，千山里响着杜鹃的啼声。山中下了一夜雨，树梢上挂着百道飞泉。汉中的女子交纳橦布，巴地的人为芋田诉讼。文翁那样的教化之风再现，不敢只倚仗先贤的旧绩。', 'public-domain'),
  ('tangshi300', 205, '除夜有怀', 'tangshi-ts-169', '迢递三巴路，羁危万里身。
乱山残雪夜，孤烛异乡人。
渐与骨肉远，转于僮仆亲。
那堪正飘泊，明日岁华新。', '三巴的道路多么遥远，羁旅艰危、身在万里之外。乱山残雪的除夕之夜，一支孤烛伴着异乡人。渐渐与骨肉亲人远离，转而与僮仆亲近。哪里受得了正漂泊无依，明天又是新的一年。', 'public-domain'),
  ('tangshi300', 206, '过香积寺', 'tangshi-ts-125', '不知香积寺，数里入云峰。
古木无人径，深山何处钟。
泉声咽危石，日色冷青松。
薄暮空潭曲，安禅制毒龙。', '不知香积寺在何处，走了几里进入云雾缭绕的山峰。古木森森没有人的路径，深山里不知从哪里传来钟声。泉声在危石间呜咽，日色在青松间显得清冷。傍晚在空潭的弯曲处，坐禅入定、制伏心中的毒龙。', 'public-domain'),
  ('tangshi300', 207, '山居秋暝', 'poems-xx5-06', '空山新雨后，天气晚来秋。
明月松间照，清泉石上流。
竹喧归浣女，莲动下渔舟。
随意春芳歇，王孙自可留。', '空旷的山中刚下过一场新雨，傍晚的天气带来了秋意。明月从松林间照下来，清泉在山石上流淌。竹林里传来洗衣女子的笑语，莲叶摇动是渔船顺流而下。任凭春天的花草凋谢吧，我留在山中正可以长久栖居。', 'school'),
  ('tangshi300', 208, '终南别业', 'tangshi-ts-127', '中岁颇好道，晚家南山陲。
兴来每独往，胜事空自知。
行到水穷处，坐看云起时。
偶然值林叟，谈笑无还期。', '中年时颇喜好佛道，晚年安家在南山边上。兴致来时常常独自出游，美好的事情只有自己知道。走到水流的尽头，坐着看云升起的时候。偶然遇到林中的老人，谈笑之间忘了回去的时候。', 'public-domain'),
  ('tangshi300', 209, '归嵩山作', 'tangshi-ts-122', '清川带长薄，车马去闲闲。
流水如有意，暮禽相与还。
荒城临古渡，落日满秋山。
迢递嵩高下，归来且闭关。', '清澈的河川环绕着长长的草木丛，车马悠然自在地离去。流水仿佛有情意，傍晚的鸟儿与我一同归还。荒凉的城池临着古老的渡口，落日的余晖洒满秋山。在高远的嵩山脚下，我归来姑且闭门隐居。', 'public-domain'),
  ('tangshi300', 210, '终南山', 'tangshi-ts-123', '太乙近天都，连山接海隅。
白云回望合，青霭入看无。
分野中峰变，阴晴众壑殊。
欲投人处宿，隔水问樵夫。', '终南山靠近天帝的都城，山峦连绵一直连接到海边。回头望去白云已合拢，走近看青色的雾气又不见了。中峰把星野划分开来，各个山谷或阴或晴各不相同。想找个有人烟的地方投宿，隔着溪水询问樵夫。', 'public-domain'),
  ('tangshi300', 211, '汉江临眺', 'tangshi300-212', '楚塞三湘接，荆门九派通。
江流天地外，山色有无中。
郡邑浮前浦，波澜动远空。
襄阳好风日，留醉与山翁。', '楚地的边塞连接着三湘，荆门与九派的水道相通。江水浩荡，仿佛流到天地之外；山色迷蒙，似有似无。城邑仿佛浮在前面的水边，波涛摇动着远空。襄阳的风光这样好，愿留下与山翁一同醉饮。', 'public-domain'),
  ('tangshi300', 212, '奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制', 'tangshi-ts-180', '渭水自萦秦塞曲，黄山旧绕汉宫斜。
銮舆迥出千门柳，阁道回看上苑花。
云里帝城双凤阙，雨中春树万人家。
为乘阳气行时令，不是宸游玩物华。', '渭水依旧萦绕着秦地的关塞弯曲而流，黄山依然斜斜地绕着汉宫。天子的车驾远远地出了千门杨柳，在阁道上回头看皇家园林的花。云里帝京耸立着双凤阙，雨中的春树掩映着万户人家。这是顺应阳气来施行时令，不是天子游乐玩赏美景。', 'public-domain'),
  ('tangshi300', 213, '和贾至舍人早朝大明宫之作', 'tangshi-ts-181', '绛帻鸡人报晓筹，尚衣方进翠云裘。
九天阊阖开宫殿，万国衣冠拜冕旒。
日色才临仙掌动，香烟欲傍衮龙浮。
朝罢须裁五色诏，佩声归到凤池头。', '戴红巾的鸡人报出晓筹，尚衣官刚进上翠云裘。九天的宫门大开，万国的使臣朝拜天子。日色刚照到仙掌、光影闪动，香烟仿佛傍着龙袍浮动。朝罢还要起草五色诏书，玉佩声中回到凤凰池。', 'public-domain'),
  ('tangshi300', 214, '酬郭给事', 'tangshi-ts-183', '洞门高阁霭余晖，桃李阴阴柳絮飞。
禁里疏钟官舍晚，省中啼鸟吏人稀。
晨摇玉佩趋金殿，夕奉天书拜琐闱。
强欲从君无那老，将因卧病解朝衣。', '宫门高阁笼罩着落日的余晖，桃李浓荫、柳絮纷飞。宫禁里钟声稀疏，官舍已晚，省中鸟啼，吏人稀少。早晨玉佩摇动，快步走上金殿；傍晚捧着天子的诏书，拜谢宫门。很想跟随你却无奈年老，将要因为卧病而脱下朝衣。', 'public-domain'),
  ('tangshi300', 215, '鹿柴', 'poems-xx4-17', '空山不见人，
但闻人语响。
返景入深林，
复照青苔上。', '空寂的山里看不见人影，只听见有人说话的声音。落日的余光返照进深林，又映在青苔上。', 'school'),
  ('tangshi300', 216, '竹里馆', 'poems-cz7-14', '独坐幽篁里，弹琴复长啸。
深林人不知，明月来相照。', '独自坐在幽深的竹林里，一边弹琴一边长声呼啸。深林中没有别人知道，只有明月来与我相伴。', 'academic'),
  ('tangshi300', 217, '杂诗·其二', 'tangshi-ts-226', '君自故乡来，应知故乡事。
来日绮窗前，寒梅著花未。', '你从故乡来，应当知道故乡的事。你动身的那天，雕花窗前的那株寒梅开花了没有。', 'academic'),
  ('tangshi300', 218, '相思', 'tangshi-ts-225', '红豆生南国，春来发几枝。
愿君多采撷，此物最相思。', '红豆生长在南方，春天来时发出几枝。愿你多多采摘，这东西最能寄托相思。', 'public-domain'),
  ('tangshi300', 219, '九月九日忆山东兄弟', 'poems-xx3-16', '独在异乡为异客，每逢佳节倍思亲。
遥知兄弟登高处，遍插茱萸少一人。', '独自在他乡做客，每到佳节就更加思念亲人。遥想兄弟们登高的地方，插茱萸时唯独少了我一个。', 'school'),
  ('tangshi300', 220, '送崔九', 'tangshi-ts-227', '归山深浅去，须尽丘壑美。
莫学武陵人，暂游桃源里。', '你归隐山中去、无论深浅，都要尽情领略丘壑的美。不要学那武陵人，只在桃源里短暂一游。', 'public-domain'),
  ('tangshi300', 221, '寻西山隐者不遇', 'tangshi-ts-20', '绝顶一茅茨，直上三十里。
扣关无僮仆，窥室唯案几。
若非巾柴车，应是钓秋水。
差池不相见，黾勉空仰止。
草色新雨中，松声晚窗里。
及兹契幽绝，自足荡心耳。
虽无宾主意，颇得清净理。
兴尽方下山，何必待之子。', '高高的山顶上有一间茅屋，一直往上要走三十里。敲门却没有童仆应答，窥看屋内只有几案。主人若不是驾着柴车外出，就该是在秋水里垂钓。阴差阳错没能相见，徒然辛劳地仰慕他。新雨过后草色青青，傍晚的窗外传来松涛声。置身这幽绝的境地，已足以涤荡我的心胸与耳目。虽然没有宾主酬答的情意，却也颇得清净的道理。兴致尽了便下山去，何必一定要等到见到他呢。', 'public-domain'),
  ('tangshi300', 222, '黄鹤楼', 'poems-cz8-06', '昔人已乘黄鹤去，此地空余黄鹤楼。
黄鹤一去不复返，白云千载空悠悠。
晴川历历汉阳树，芳草萋萋鹦鹉洲。
日暮乡关何处是？烟波江上使人愁。', '传说中的仙人已经乘着黄鹤飞走了，这个地方只留下空空的黄鹤楼。黄鹤一去再也没有回来，千百年来只有白云在空中飘飘荡荡。晴日里，汉阳的树木清晰可数，鹦鹉洲上芳草长得十分茂盛。天色已晚，故乡在什么地方呢？江上的烟波使人愁绪满怀。', 'academic'),
  ('tangshi300', 223, '行经华阴', 'tangshi-ts-174', '岧峣太华俯咸京，天外三峰削不成。
武帝祠前云欲散，仙人掌上雨初晴。
河山北枕秦关险，驿路西连汉畤平。
借问路旁名利客，何如此处学长生。', '高峻的太华山俯视着咸阳，天外的三峰像是刀削不成。武帝祠前的云将要散去，仙人掌峰上的雨刚刚转晴。山河北枕秦关之险，驿路西连着平坦的汉畤。请问路旁追逐名利的人，何不像这样在这里学长生之道。', 'public-domain'),
  ('tangshi300', 224, '望蓟门', 'tangshi-ts-175', '燕台一去客心惊，笳鼓喧喧汉将营。
万里寒光生积雪，三边曙色动危旌。
沙场烽火侵胡月，海畔云山拥蓟城。
少小虽非投笔吏，论功还欲请长缨。', '一到燕台客子便心惊，笳鼓喧闹的是汉将的军营。万里寒光从积雪中生出，三边的曙光使高悬的旌旗飘动。沙场的烽火侵扰着胡地的月亮，海边的云山簇拥着蓟城。我年少时虽不是投笔从戎的班超，论功却还想请缨杀敌。', 'public-domain'),
  ('tangshi300', 225, '终南望余雪', 'tangshi-ts-228', '终南阴岭秀，积雪浮云端。
林表明霁色，城中增暮寒。', '终南山北面的山岭秀丽，积雪浮在云端。树林梢头露出晴后的天色，城中更添傍晚的寒意。', 'public-domain'),
  ('tangshi300', 226, '古从军行', 'tangshi-ts-73', '白日登山望烽火，黄昏饮马傍交河。
行人刁斗风沙暗，公主琵琶幽怨多。
野云万里无城郭，雨雪纷纷连大漠。
胡雁哀鸣夜夜飞，胡儿眼泪双双落。
闻道玉门犹被遮，应将性命逐轻车。
年年战骨埋荒外，空见蒲桃入汉家。', '白天登山瞭望烽火，黄昏在交河边饮马。行人打着刁斗，风沙昏暗，公主的琵琶声里幽怨很多。野云万里不见城郭，雨雪纷纷连接着大漠。胡雁哀鸣夜夜飞翔，胡儿的眼泪双双落下。听说玉门关还被遮断，只能拼着性命跟随轻车将军。年年战死的尸骨埋在荒外，只看见葡萄传入了汉家。', 'public-domain'),
  ('tangshi300', 227, '琴歌', 'tangshi-ts-35', '主人有酒欢今夕，请奏鸣琴广陵客。
月照城头乌半飞，霜凄万树风入衣。
铜炉华烛烛增辉，初弹渌水后楚妃。
一声已动物皆静，四座无言星欲稀。
清淮奉使千余里，敢告云山从此始。', '主人备酒，今夜欢聚，请来善弹琴的广陵客为我奏一曲。月光照着城头，乌鸦半飞；霜气凄冷万树，寒风吹入衣裳。铜炉香料、华美蜡烛使烛光更亮，先弹《渌水》，后弹《楚妃》。琴声一起，万物都静了下来，满座无言，直到天将亮、星星稀疏。我奉命出使清淮，路远千里，从此要辞别云山开始了。', 'public-domain'),
  ('tangshi300', 228, '送陈章甫', 'tangshi-ts-37', '四月南风大麦黄，枣花未落桐叶长。
青山朝别暮还见，嘶马出门思旧乡。
陈侯立身何坦荡，虬须虎眉仍大颡。
腹中贮书一万卷，不肯低头在草莽。
东门酤酒饮我曹，心轻万事如鸿毛。
醉卧不知白日暮，有时空望孤云高。
长河浪头连天黑，津吏停舟渡不得。
郑国游人未及家，洛阳行子空叹息。
闻道故林相识多，罢官昨日今如何。', '四月南风吹来大麦金黄，枣花未落桐叶已长。青山早晨一别傍晚又见，马嘶着走出家门便思念故乡。陈侯为人何等坦荡，胡须卷曲、眉毛如虎、额头宽阔。腹中藏着一万卷书，却不肯低头埋没在草野之中。他在东门买酒请我们喝，心里把万事看得轻如鸿毛。醉卧时不知白日已暮，有时空自遥望孤云高飞。长河浪头连天昏黑，渡口官吏停船不能渡。郑国的游子还没到家，洛阳的行人徒然叹息。听说故乡旧识很多，你昨日罢官，如今他们会怎样待你呢。', 'public-domain'),
  ('tangshi300', 229, '听安万善吹觱篥歌', 'tangshi-ts-38', '南山截竹为觱篥，此乐本自龟兹出。
流传汉地曲转奇，凉州胡人为我吹。
傍邻闻者多叹息，远客思乡皆泪垂。
世人解听不解赏，长飙风中自来往。
枯桑老柏寒飕飗，九雏鸣凤乱啾啾。
龙吟虎啸一时发，万籁百泉相与秋。
忽然更作渔阳掺，黄云萧条白日暗。
变调如闻杨柳春，上林繁花照眼新。
岁夜高堂列明烛，美酒一杯声一曲。', '从南山截下竹子做成觱篥，这种乐器本出自龟兹。流传到汉地曲调变得更加奇妙，凉州的胡人为我吹奏。旁边的邻人听了都叹息，远方的旅客思念家乡都流下泪来。世人只懂得听却不懂得欣赏，乐声像长风在风中自来自往。像枯桑老柏在寒风里飕飗作响，又像九只雏凤鸣叫，细细啾啾。忽然如龙吟虎啸一齐迸发，又像万种声响与百道泉流共奏秋声。忽然又转为《渔阳掺》的曲调，黄云萧条，白日昏暗。变调时仿佛听到杨柳迎春，上林苑繁花照眼一新。除夕之夜高堂上点起明烛，美酒一杯、乐曲一支。', 'public-domain'),
  ('tangshi300', 230, '古意', 'tangshi-ts-36', '男儿事长征，少小幽燕客。
赌胜马蹄下，由来轻七尺。
杀人莫敢前，须如猬毛磔。
黄云陇底白云飞，未得报恩不能归。
辽东小妇年十五，惯弹琵琶解歌舞。
今为羌笛出塞声，使我三军泪如雨。', '男儿当兵去远征，从小是幽燕一带的健儿。在马蹄下争夺胜负，向来把性命看得轻。杀人时勇猛没人敢上前，胡须像刺猬毛一样张开。陇山下黄云弥漫，白云飞卷，未报答国恩就不能回家。辽东有个十五岁的小妇，惯于弹琵琶、善歌舞。如今她用羌笛吹起出塞的曲调，使我们三军将士泪如雨下。', 'public-domain'),
  ('tangshi300', 231, '听董大弹胡笳兼寄语弄房给事', 'tangshi300-232', '蔡女昔造胡笳声，一弹一十有八拍。
胡人落泪沾边草，汉使断肠对归客。
古戍苍苍烽火寒，大荒沉沉飞雪白。
先拂商弦后角羽，四郊秋叶惊摵摵。
董夫子，通神明，深松窃听来妖精。
言迟更速皆应手，将往复旋如有情。
空山百鸟散还合，万里浮云阴且晴。
嘶酸雏雁失群夜，断绝胡儿恋母声。
川为静其波，鸟亦罢其鸣。
乌孙部落家乡远，逻娑沙尘哀怨生。
幽音变调忽飘洒，长风吹林雨堕瓦。
迸泉飒飒飞木末，野鹿呦呦走堂下。
长安城连东掖垣，凤凰池对青琐门。
高才脱略名与利，日夕望君抱琴至。', '蔡文姬当年创制胡笳曲，一弹便是十八拍。胡人听了落泪沾湿边草，汉使听了对着归客断肠。古老的戍垒苍茫，烽火透着寒意；广漠的原野沉沉，飞雪一片白。先拂商弦，再动角羽，四郊的秋叶惊得簌簌作响。董先生啊，你的琴艺通神明，深松间偷听的妖精也被引来。慢挑快拨都随手应心，将往又回，仿佛含着深情。空山里百鸟散去又聚拢，万里浮云忽阴忽晴。凄酸的像失群的雏雁在夜里哀鸣，断绝的像胡儿依恋母亲的声音。河水为它静下波浪，鸟儿也为它停止啼叫。乌孙部落远离家乡，逻娑的沙尘里生出哀怨。幽咽的音调忽然转为飘洒，像长风吹林、急雨打瓦。像迸溅的泉水飒飒飞上树梢，像野鹿呦呦叫着走过堂下。长安城连着东掖的墙垣，凤凰池对着青琐门。你才高而不拘名利，我日夜盼你抱琴而来。', 'public-domain'),
  ('tangshi300', 232, '送魏万之京', 'tangshi-ts-177', '朝闻游子唱离歌，昨夜微霜初渡河。
鸿雁不堪愁里听，云山况是客中过。
关城树色催寒近，御苑砧声向晚多。
莫见长安行乐处，空令岁月易蹉跎。', '早晨听到你唱起离别的歌，昨夜微霜刚刚渡过黄河。鸿雁的鸣声在愁中不堪听，云山更是在客旅中所经过的。关城的树色催促寒气临近，御苑的砧声到傍晚更多。不要只看见长安是行乐的地方，白白地让岁月蹉跎。', 'public-domain'),
  ('tangshi300', 233, '春泛若耶溪', 'tangshi-ts-21', '幽意无断绝，此去随所偶。
晚风吹行舟，花路入溪口。
际夜转西壑，隔山望南斗。
潭烟飞溶溶，林月低向后。
生事且弥漫，愿为持竿叟。', '幽居的意趣没有断绝，此番出行随遇而安。晚风吹着行船，沿着花径进入溪口。入夜后船转入西边的山谷，隔着山望见南斗星。潭上雾气溶溶飘飞，林中月影低低地向后移去。人生世事茫茫无边，我愿做个持竿垂钓的老翁。', 'public-domain'),
  ('tangshi300', 234, '同从弟南斋玩月忆山阴崔少府', 'tangshi-ts-19', '高卧南斋时，开帷月初吐。
清辉澹水木，演漾在窗户。
荏苒几盈虚，澄澄变今古。
美人清江畔，是夜越吟苦。
千里其如何，微风吹兰杜。', '高卧在南斋的时候，拉开帷幕看见月亮刚刚升起。清辉淡淡地洒在水面与树木上，荡漾着映在窗户之间。时光荏苒，月亮几度圆缺，澄澈的月色变换着古今。我所思念的人在清江之畔，今夜他一定在越地苦苦吟咏。相隔千里又能怎样呢，微风吹送着兰草杜若的芳香。', 'public-domain'),
  ('tangshi300', 235, '出塞二首·其一', 'tangshi-ts-88', '秦时明月汉时关，万里长征人未还。
但使龙城飞将在，不教胡马度阴山。', '依然是秦汉时的明月和边关，万里出征的将士还没有回还。只要龙城的飞将军还在，就不会让胡人的战马越过阴山。', 'public-domain'),
  ('tangshi300', 236, '春宫曲', 'tangshi-ts-257', '昨夜风开露井桃，未央前殿月轮高。
平阳歌舞新承宠，帘外春寒赐锦袍。', '昨夜春风吹开了露井边的桃花，未央宫前殿月轮高悬。平阳家的歌女新受恩宠，帘外春寒、赐下锦袍。', 'public-domain'),
  ('tangshi300', 237, '闺怨', 'tangshi-ts-256', '闺中少妇不知愁，春日凝妆上翠楼。
忽见陌头杨柳色，悔教夫婿觅封侯。', '闺中的少妇不知道愁，春日里盛妆登上翠楼。忽然看见路边的杨柳春色，后悔当初让丈夫去求取封侯。', 'public-domain'),
  ('tangshi300', 238, '芙蓉楼送辛渐', 'poems-xx4-20', '寒雨连江夜入吴，
平明送客楚山孤。
洛阳亲友如相问，
一片冰心在玉壶。', '寒雨连着江水，夜里来到吴地；天亮送别友人，只余楚山孤零零。洛阳的亲友如果问起我，就说我的心像玉壶里的冰一样纯洁。', 'school'),
  ('tangshi300', 239, '宿王昌龄隐居', 'tangshi-ts-22', '清溪深不测，隐处唯孤云。
松际露微月，清光犹为君。
茅亭宿花影，药院滋苔纹。
余亦谢时去，西山鸾鹤群。', '清清的溪水深不可测，隐居之处只有一片孤云。松林间露出淡淡的月亮，清朗的月光仿佛还在为你而照。茅亭里停宿着花的影子，种药的院子里滋生了青苔的纹路。我也要辞别时俗而去，到西山与鸾鹤为群。', 'public-domain'),
  ('tangshi300', 240, '听弹琴', 'tangshi-ts-236', '泠泠七弦上，静听松风寒。
古调虽自爱，今人多不弹。', '冷冷清清的七弦琴上，静静地听出松风般的寒意。古调虽然我自己喜爱，如今的人却多不弹了。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 241, '送上人', 'tangshi-ts-237', '孤云将野鹤，岂向人间住。
莫买沃洲山，时人已知处。', '孤云伴随野鹤，怎会在人间居住。不要去购买沃洲山，那是时人已经知道的地方。', 'public-domain'),
  ('tangshi300', 242, '送灵澈', 'tangshi-ts-235', '苍苍竹林寺，杳杳钟声晚。
荷笠带斜阳，青山独归远。', '苍苍的是竹林寺，杳杳的是傍晚的钟声。你背着斗笠、披着斜阳，独自向青山远处归去。', 'public-domain'),
  ('tangshi300', 243, '送李中丞归汉阳别业', 'tangshi-ts-138', '流落征南将，曾驱十万师。
罢归无旧业，老去恋明时。
独立三边静，轻生一剑知。
茫茫江汉上，日暮欲何之。', '流落江湖的征南将军，曾经统率十万大军。罢官归来没有旧日的产业，年老还眷恋着清明的时代。他独自镇守、三边安宁，舍生忘死只有那一把剑知道。茫茫的江汉之上，日暮时分你要往哪里去。', 'public-domain'),
  ('tangshi300', 244, '秋日登吴公台上寺远眺', 'tangshi-ts-137', '古台摇落后，秋日望乡心。
野寺来人少，云峰隔水深。
夕阳依旧垒，寒磬满空林。
惆怅南朝事，长江独至今。', '古台草木摇落之后，秋日里生出望乡之心。荒野的寺庙来人很少，云绕的山峰隔着深水。夕阳照着旧日的营垒，清寒的磬声充满空寂的山林。惆怅南朝的往事，只有长江独自流到如今。', 'public-domain'),
  ('tangshi300', 245, '寻南溪常道士', 'tangshi-ts-140', '一路经行处，莓苔见屐痕。
白云依静渚，芳草闭闲门。
过雨看松色，随山到水源。
溪花与禅意，相对亦忘言。', '一路走过的地方，青苔上还留着足迹。白云依傍着寂静的水洲，芳草掩闭着闲静的柴门。雨后观赏松树的颜色，顺着山势走到水源。溪花与禅意相对，彼此相看都忘了言语。', 'public-domain'),
  ('tangshi300', 246, '饯别王十一南游', 'tangshi-ts-139', '望君烟水阔，挥手泪沾巾。
飞鸟没何处，青山空向人。
长江一帆远，落日五湖春。
谁见汀洲上，相思愁白苹。', '望着你远入烟水茫茫，挥手之间泪水沾湿手巾。飞鸟消失在哪里，青山空自对着人。长江上一片孤帆远去，落日下五湖正逢春天。谁看见我在汀洲之上，因相思而对着白苹发愁。', 'public-domain'),
  ('tangshi300', 247, '江州重别薛六柳八二员外', 'tangshi-ts-199', '生涯岂料承优诏，世事空知学醉歌。
江上月明胡雁过，淮南木落楚山多。
寄身且喜沧洲近，顾影无如白发何。
今日龙钟人共老，愧君犹遣慎风波。', '一生哪料承蒙优诏，世事也只空知学着醉歌。江上明月、胡雁飞过，淮南叶落、楚山众多。寄身此地、且喜离水边沧洲很近，自顾身影、对白发无可奈何。如今老态龙钟、大家都已衰老，惭愧你还要派我要小心风波。', 'public-domain'),
  ('tangshi300', 248, '长沙过贾谊宅', 'poems-cz9-11', '三年谪宦此栖迟，万古惟留楚客悲。
秋草独寻人去后，寒林空见日斜时。
汉文有道恩犹薄，湘水无情吊岂知？
寂寂江山摇落处，怜君何事到天涯！', '贾谊被贬长沙三年，在这里栖身，万古以来只留下楚客的悲哀。秋草之中，我独自寻找他离去后的踪迹，寒冷的树林里只看到夕阳西下。汉文帝虽然贤明，对他的恩遇尚且如此微薄；湘水无情，凭吊贾谊又怎么知道呢？寂寥冷落的江山，草木摇落的时节，可怜你为什么要来到这天涯之地！', 'school'),
  ('tangshi300', 249, '自夏口至鹦鹉洲夕望岳阳寄源中丞', 'tangshi-ts-201', '汀洲无浪复无烟，楚客相思益渺然。
汉口夕阳斜渡鸟，洞庭秋水远连天。
孤城背岭寒吹角，独戍临江夜泊船。
贾谊上书忧汉室，长沙谪去古今怜。', '汀洲上没有波浪也没有烟雾，楚客的相思更加渺茫。汉口的夕阳斜照渡鸟，洞庭的秋水远远连着天。孤城背靠山岭、寒风中吹起号角，独戍临江、夜里停泊着船只。贾谊上书忧虑汉室，被贬长沙、古今都为之怜惜。', 'public-domain'),
  ('tangshi300', 250, '九日登望仙台呈刘明府', 'tangshi-ts-176', '汉文皇帝有高台，此日登临曙色开。
三晋云山皆北向，二陵风雨自东来。
关门令尹谁能识，河上仙翁去不回。
且欲近寻彭泽宰，陶然共醉菊花杯。', '汉文皇帝有一座高台，今日登临、曙色开朗。三晋的云山都向北拱卫，二陵的风雨从东边而来。关门的令尹谁能赏识，河上的仙翁一去不回。且就近去寻访彭泽令那样的县令，乐陶陶地一同醉饮菊花酒。', 'public-domain'),
  ('tangshi300', 251, '凉州词二首·其一', 'poems-xx4-05', '葡萄美酒夜光杯，欲饮琵琶马上催。
醉卧沙场君莫笑，古来征战几人回。', '夜光杯里斟满葡萄美酒，正要畅饮，马上的琵琶声却催人上路。醉倒在沙场上请你不要笑话，自古以来出征的人能有几个活着回来。', 'school'),
  ('tangshi300', 252, '秋登兰山寄张五', 'tangshi-ts-16', '北山白云里，隐者自怡悦。
相望始登高，心随雁飞灭。
愁因薄暮起，兴是清秋发。
时见归村人，沙行渡头歇。
天边树若荠，江畔洲如月。
何当载酒来，共醉重阳节。', '北山的白云里，隐居的人自得其乐。为了遥望你我才登上高处，心随着大雁飞去直到看不见。忧愁因傍晚而生，兴致因清秋而发。时时看见回村的人，在沙滩上行走、在渡口歇息。天边的树木细得像荠菜，江边的沙洲弯得像月亮。什么时候你带着酒来，我们一同醉在重阳节。', 'public-domain'),
  ('tangshi300', 253, '夏日南亭怀辛大', 'tangshi-ts-17', '山光忽西落，池月渐东上。
散发乘夕凉，开轩卧闲敞。
荷风送香气，竹露滴清响。
欲取鸣琴弹，恨无知音赏。
感此怀故人，中宵劳梦想。', '山上的日色忽然向西落下，池上的月亮渐渐从东边升起。我披散开头发乘着傍晚的凉意，打开窗户闲适地躺卧在敞亮的屋中。荷风送来阵阵香气，竹叶上的露水滴落发出清脆的声响。想取出琴来弹奏，可惜没有知音来欣赏。感念于此，怀念起老朋友，半夜里还在梦中苦苦思念。', 'public-domain'),
  ('tangshi300', 254, '宿业师山房期丁大不至', 'tangshi-ts-18', '夕阳度西岭，群壑倏已暝。
松月生夜凉，风泉满清听。
樵人归欲尽，烟鸟栖初定。
之子期宿来，孤琴候萝径。', '夕阳越过西边的山岭，各条山谷忽然间已经昏暗。松间的月亮带来夜的凉意，风声泉声充满了清幽的听觉。砍柴的人差不多都回家了，暮烟中的鸟儿也刚刚安歇。你约定今晚来过夜，我抱着孤琴在藤萝小径上等候。', 'public-domain'),
  ('tangshi300', 255, '夜归鹿门山歌', 'tangshi-ts-39', '山寺钟鸣昼已昏，渔梁渡头争渡喧。
人随沙岸向江村，余亦乘舟归鹿门。
鹿门月照开烟树，忽到庞公栖隐处。
岩扉松径长寂寥，惟有幽人自来去。', '山寺钟声响起，白昼已经昏暮，渔梁渡头人们争着渡河，一片喧闹。行人沿着沙岸走向江村，我也乘船回鹿门山。鹿门的月光照着烟雾散开的树林，忽然来到庞公当年隐居的地方。岩洞的门、松间的小路，长年寂寥，只有我这个幽人自来自去。', 'public-domain'),
  ('tangshi300', 256, '临洞庭上张丞相', 'poems-cz8-22', '八月湖水平，涵虚混太清。
气蒸云梦泽，波撼岳阳城。
欲济无舟楫，端居耻圣明。
坐观垂钓者，徒有羡鱼情。', '八月洞庭湖水暴涨，水面与湖岸齐平，湖水与天空浑然一体。水气蒸腾笼罩着云梦大泽，波涛汹涌震动着岳阳城。我想渡过湖去却没有船只，闲居不仕又愧对圣明的时代。只能坐看那些垂钓的人，白白地生出羡慕鱼儿的心情。', 'school'),
  ('tangshi300', 257, '秦中寄远上人', 'tangshi-ts-133', '一丘常欲卧，三径苦无资。
北土非吾愿，东林怀我师。
黄金燃桂尽，壮志逐年衰。
日夕凉风至，闻蝉但益悲。', '常想在一座小丘上高卧隐居，可苦于没有修筑三径的钱财。北方不是我的心愿，我怀念东林寺的师父。黄金像烧桂一样耗尽，壮志随着年岁衰减。傍晚凉风吹来，听到蝉鸣更添悲伤。', 'public-domain'),
  ('tangshi300', 258, '春思', 'tangshi-ts-205', '莺啼燕语报新年，马邑龙堆路几千。
家住层城临汉苑，心随明月到胡天。
机中锦字论长恨，楼上花枝笑独眠。
为问元戎窦车骑，何时返旆勒燕然。', '莺啼燕语报告新年，马邑龙堆的路途有几千里。家住在层城、临近汉苑，心随着明月到了胡天。机中织出锦字诉说长恨，楼上的花枝嘲笑独自成眠。请问主将窦车骑，什么时候才能班师回朝、在燕然山刻石纪功。', 'public-domain'),
  ('tangshi300', 259, '宿桐庐江寄广陵旧游', 'tangshi-ts-134', '山暝听猿愁，沧江急夜流。
风鸣两岸叶，月照一孤舟。
建德非吾土，维扬忆旧游。
还将两行泪，遥寄海西头。', '山色昏暗、听着猿啼发愁，青苍的江水夜里湍急地流。风吹响两岸的树叶，月光照着一只孤舟。建德不是我的故乡，我怀念扬州的旧友。只好把两行眼泪，远远地寄到大海的西头。', 'public-domain'),
  ('tangshi300', 260, '早寒江上有怀', 'tangshi-ts-136', '木落雁南度，北风江上寒。
我家襄水曲，遥隔楚云端。
乡泪客中尽，孤帆天际看。
迷津欲有问，平海夕漫漫。', '树叶飘落、大雁南飞，北风吹得江上寒冷。我的家在襄水的弯曲处，远远隔着楚地的云端。思乡的泪在客旅中流尽，孤帆向天边望去。迷失了渡口想问路，平阔的海面傍晚茫茫无边。', 'public-domain'),
  ('tangshi300', 261, '留别王维', 'tangshi-ts-135', '寂寂竟何待，朝朝空自归。
欲寻芳草去，惜与故人违。
当路谁相假，知音世所稀。
只应守寂寞，还掩故园扉。', '寂寂无声还等待什么呢，天天白白地归来。想寻找芳草离去，又舍不得与老朋友分别。当权的人谁来帮助我呢，知音在世上很稀少。只该守着寂寞，回去关上故园的门。', 'public-domain'),
  ('tangshi300', 262, '宴梅道士山房', 'tangshi-ts-130', '林卧愁春尽，搴帷览物华。
忽逢青鸟使，邀入赤松家。
金灶初开火，仙桃正发花。
童颜若可驻，何惜醉流霞。', '高卧林中愁春天将尽，掀开帷幕观赏景物的芳华。忽然遇到青鸟使者，邀我到赤松子家去。金丹灶刚生起火，仙桃正开着花。如果童颜可以留住，何必吝惜醉饮流霞仙酒。', 'public-domain'),
  ('tangshi300', 263, '与诸子登岘山', 'tangshi-ts-129', '人事有代谢，往来成古今。
江山留胜迹，我辈复登临。
水落鱼梁浅，天寒梦泽深。
羊公碑尚在，读罢泪沾襟。', '人事有新陈代谢，往来之间便成了古今。江山留下名胜古迹，我们又来登临。水落下去鱼梁洲显得浅，天气寒冷云梦泽显得深。羊公碑还在，读完之后泪水沾湿了衣襟。', 'public-domain'),
  ('tangshi300', 264, '过故人庄', 'poems-xx6-17', '故人具鸡黍，邀我至田家。
绿树村边合，青山郭外斜。
开轩面场圃，把酒话桑麻。
待到重阳日，还来就菊花。', '老友准备了饭菜，邀我到农家做客。绿树环绕着村庄，青山在城郭外斜卧。打开窗子面对谷场菜园，端着酒谈说庄稼。等到重阳节，还要再来赏菊。', 'school'),
  ('tangshi300', 265, '岁暮归南山', 'tangshi-ts-131', '北阙休上书，南山归敝庐。
不才明主弃，多病故人疏。
白发催年老，青阳逼岁除。
永怀愁不寐，松月夜窗虚。', '不再到北阙去上书，回到南山的旧屋。没有才能被明主弃置，身体多病故人也疏远。白发催人老去，春天逼近岁末。长怀愁绪睡不着，松间月色照着空寂的夜窗。', 'public-domain'),
  ('tangshi300', 266, '岁除夜有怀', 'tangshi-ts-169', '迢递三巴路，羁危万里身。
乱山残雪夜，孤烛异乡人。
渐与骨肉远，转于僮仆亲。
那堪正飘泊，明日岁华新。', '三巴的道路多么遥远，羁旅艰危，身在万里之外。乱山残雪的除夕之夜，一支孤烛伴着异乡人。渐渐与骨肉亲人远离，转而与僮仆亲近。哪里受得了正漂泊无依，明天又是新的一年。', 'public-domain'),
  ('tangshi300', 267, '春晓', 'poems-xx1-07', '春眠不觉晓，处处闻啼鸟。
夜来风雨声，花落知多少。', '春天睡得香甜，不知不觉天就亮了，处处听到鸟儿的鸣叫。回想夜里风雨的声音，不知落了多少花。', 'school'),
  ('tangshi300', 268, '宿建德江', 'poems-xx6-01', '移舟泊烟渚，日暮客愁新。
野旷天低树，江清月近人。', '我把船停靠在烟雾迷蒙的小洲边，日暮时分，旅人的愁绪又添了一层。旷野无边无际，天比树还低；江水清澈，月影仿佛离人更近了。', 'school'),
  ('tangshi300', 269, '将进酒', 'poems-gz11-06', '君不见，黄河之水天上来，奔流到海不复回。
君不见，高堂明镜悲白发，朝如青丝暮成雪。
人生得意须尽欢，莫使金樽空对月。
天生我材必有用，千金散尽还复来。
烹羊宰牛且为乐，会须一饮三百杯。
岑夫子，丹丘生，将进酒，杯莫停。
与君歌一曲，请君为我倾耳听。
钟鼓馔玉不足贵，但愿长醉不愿醒。
古来圣贤皆寂寞，惟有饮者留其名。
陈王昔时宴平乐，斗酒十千恣欢谑。
主人何为言少钱，径须沽取对君酌。
五花马、千金裘，呼儿将出换美酒，与尔同销万古愁。', '你没有看见吗？黄河之水从天上奔腾而来，滚滚东流入海再也不回还。你没有看见吗？在高堂明镜前悲叹白发，早晨还是满头青丝，傍晚就变成了白雪。人生得意时就应当尽情欢乐，不要让金杯空对着明月。上天生下我这人才一定有用，千金散尽也还会再来。烹羊宰牛暂且尽情享乐，要喝就应当一饮三百杯。岑夫子，丹丘生，快喝酒，不要停下杯子。我为你们唱一首歌，请你们侧耳为我倾听。那些豪华的宴饮不值得珍贵，只愿长醉不愿醒来。自古以来的圣贤都很寂寞，只有善于饮酒的人才留下了名声。陈王曹植当年在平乐观设宴，斗酒万钱，尽情欢乐。主人为什么说钱少呢？只管去买酒来，让我与你们共饮。这名贵的五花马，这价值千金的裘皮衣，叫我的儿子拿出去换成美酒，让我们一同来消解这万古的愁绪！', 'academic'),
  ('tangshi300', 270, '关山月', 'tangshi-ts-63', '明月出天山，苍茫云海间。
长风几万里，吹度玉门关。
汉下白登道，胡窥青海湾。
由来征战地，不见有人还。
戍客望边色，思归多苦颜。
高楼当此夜，叹息未应闲。', '明月从天山升起，出没在苍茫的云海之间。长风吹过几万里，一直吹过玉门关。汉朝出兵白登道，胡人窥视青海湾。自古以来征战的地方，不见有人生还。守边的将士望着边地的景色，思归的脸上多是苦色。高楼上的妻子在这夜里，叹息声大约也不曾停歇。', 'public-domain'),
  ('tangshi300', 271, '清平调·其二', 'yuefu-yf-75·2', '一枝红艳露凝香，云雨巫山枉断肠。
借问汉宫谁得似，可怜飞燕倚新妆。', '一枝红艳的花上露水凝聚着芳香，巫山云雨的故事只令人白白断肠。请问汉宫里谁能与她相比，只有新妆初罢的赵飞燕还堪比拟。', 'public-domain'),
  ('tangshi300', 272, '静夜思', 'poems-xx1-09', '床前明月光，疑是地上霜。
举头望明月，低头思故乡。', '床前洒着一片明月的光，疑心是地上结的霜。抬头望着明月，低下头就想起了故乡。', 'school'),
  ('tangshi300', 273, '赠孟浩然', 'tangshi-ts-105', '吾爱孟夫子，风流天下闻。
红颜弃轩冕，白首卧松云。
醉月频中圣，迷花不事君。
高山安可仰，徒此揖清芬。', '我喜爱孟夫子，他的风流潇洒天下闻名。年轻时就抛弃了官爵车马，白头时高卧在松云之间。醉于明月频频称圣，迷恋花草而不去侍奉君王。像高山一样怎么能够仰望，只好在此拱手敬仰他清高的品德。', 'public-domain'),
  ('tangshi300', 274, '庐山谣寄卢侍御虚舟', 'tangshi-ts-40', '我本楚狂人，凤歌笑孔丘。
手持绿玉杖，朝别黄鹤楼。
五岳寻仙不辞远，一生好入名山游。
庐山秀出南斗傍，屏风九叠云锦张，
影落明湖青黛光。
金阙前开二峰长，银河倒挂三石梁。
香炉瀑布遥相望，回崖沓嶂凌苍苍。
翠影红霞映朝日，鸟飞不到吴天长。
登高壮观天地间，大江茫茫去不还。
黄云万里动风色，白波九道流雪山。
好为庐山谣，兴因庐山发。
闲窥石镜清我心，谢公行处苍苔没。
早服还丹无世情，琴心三叠道初成。
遥见仙人彩云里，手把芙蓉朝玉京。
先期汗漫九垓上，愿接卢敖游太清。', '我本是楚国的狂人接舆，唱着凤歌嘲笑孔丘。手拿绿玉杖，清晨辞别黄鹤楼。寻访五岳的仙人不怕路远，一生就喜欢到名山去游历。庐山秀丽地耸立在南斗星旁，像九叠屏风张开的云锦，山影落入明净的湖中，泛着青黛色的光。金阙岩前两座山峰长耸，三石梁上瀑布如银河倒挂。香炉峰与瀑布遥遥相望，回环的山崖、层叠的山嶂凌驾于苍茫之上。翠影红霞映着朝阳，鸟儿也飞不到吴地那辽阔的天空。登高远望，天地间景色壮观，大江茫茫东去不回。万里黄云随风变色，九道白波如雪山奔流。我喜爱作这首庐山谣，诗兴因庐山而发。闲来窥看石镜以清我心，谢灵运走过的地方已被苍苔埋没。早服仙丹便无世俗之情，琴心三叠，道行初成。远远望见仙人在彩云里，手把芙蓉朝拜玉京。我预先约好在九天之上相会，愿与你卢敖一同遨游太清。', 'public-domain'),
  ('tangshi300', 275, '梦游天姥吟留别', 'tangshi-ts-41', '海客谈瀛洲，烟涛微茫信难求。
越人语天姥，云霞明灭或可睹。
天姥连天向天横，势拔五岳掩赤城。
天台四万八千丈，对此欲倒东南倾。
我欲因之梦吴越，一夜飞度镜湖月。
湖月照我影，送我至剡溪。
谢公宿处今尚在，渌水荡漾清猿啼。
脚著谢公屐，身登青云梯。
半壁见海日，空中闻天鸡。
千岩万转路不定，迷花倚石忽已暝。
熊咆龙吟殷岩泉，栗深林兮惊层巅。
云青青兮欲雨，水澹澹兮生烟。
列缺霹雳，丘峦崩摧。
洞天石扉，訇然中开。
青冥浩荡不见底，日月照耀金银台。
霓为衣兮风为马，云之君兮纷纷而来下。
虎鼓瑟兮鸾回车，仙之人兮列如麻。
忽魂悸以魄动，恍惊起而长嗟。
惟觉时之枕席，失向来之烟霞。
世间行乐亦如此，古来万事东流水。
别君去兮何时还，且放白鹿青崖间，须行即骑访名山。
安能摧眉折腰事权贵，使我不得开心颜。', '航海的人谈起瀛洲，烟波渺茫实在难以寻求。越地的人说起天姥山，云霞明灭之间或许还能看见。天姥山连着天向天横亘，山势超出五岳，遮蔽了赤城。天台山高四万八千丈，对着它也要向东南倾倒。我想因此梦游吴越，一夜之间飞过月光下的镜湖。湖月照着我的影子，把我送到剡溪。谢灵运当年住宿的地方如今还在，绿水荡漾，清猿啼叫。我脚穿谢公的木屐，身登直上青云的石梯。半山腰看见海上日出，半空中听到天鸡啼鸣。千岩万壑峰回路转，路径不定，迷恋山花倚着石头，忽然天色已暮。熊在咆哮、龙在吟啸，震动岩石与泉水；使深林战栗，令层巅惊骇。云青青的将要下雨，水澹澹的生起烟雾。闪电霹雳，山峦崩裂。仙洞的石门，轰然从中打开。青天浩荡看不到底，日月照耀着金银台。以彩虹为衣、以风为马，云中的神仙纷纷降下。老虎鼓瑟、鸾鸟驾车，仙人们排列得像麻一样多。忽然心惊魄动，恍然惊醒而长声叹息。身边只有醒来时的枕席，失去了刚才的烟霞仙境。世间行乐也当如此，古来万事都如东流之水。告别你离去何时才回来，暂且把白鹿放养在青崖之间，要走时就骑上它去访名山。怎能低眉弯腰去侍奉权贵，使我不能舒心畅意。', 'academic'),
  ('tangshi300', 276, '金陵酒肆留别', 'tangshi-ts-42', '风吹柳花满店香，吴姬压酒唤客尝。
金陵子弟来相送，欲行不行各尽觞。
请君试问东流水，别意与之谁短长。', '风吹着柳花，满店都是香气，吴地的姑娘压出酒来招呼客人品尝。金陵的子弟们前来相送，要走未走之间各自饮尽杯中的酒。请你问问那向东流去的江水，这离别的深情与它相比谁短谁长。', 'public-domain'),
  ('tangshi300', 277, '送孟浩然之广陵', 'poems-xx4-23', '故人西辞黄鹤楼，
烟花三月下扬州。
孤帆远影碧空尽，
唯见长江天际流。', '老朋友在黄鹤楼与我辞别，在柳絮如烟的三月去扬州。孤帆的影子消失在碧空尽头，只见长江向天边流去。', 'school'),
  ('tangshi300', 278, '渡荆门送别', 'poems-cz8-08', '渡远荆门外，来从楚国游。
山随平野尽，江入大荒流。
月下飞天镜，云生结海楼。
仍怜故乡水，万里送行舟。', '我乘船远渡到荆门之外，来到楚地漫游。山峦随着平坦的原野的出现而渐渐消失，江水奔流进入辽远无际的原野。月亮倒映在水中，像天上飞下来一面明镜；云气升起，结成了海市蜃楼。我还是怜爱故乡的水，它不远万里送我的行舟。', 'school'),
  ('tangshi300', 279, '送友人', 'poems-cz8-27', '青山横北郭，白水绕东城。
此地一为别，孤蓬万里征。
浮云游子意，落日故人情。
挥手自兹去，萧萧班马鸣。', '青山横亘在城北，白水环绕着城东。我们在这里分别，你像孤单的蓬草随风飘转，踏上万里征程。浮云飘忽不定，正如游子的心意；落日不忍落下，正如故人的情谊。挥手告别，从此离去，只听见马儿萧萧的嘶鸣。', 'academic'),
  ('tangshi300', 280, '宣州谢朓楼饯别校书叔云', 'tangshi-ts-43', '弃我去者，昨日之日不可留；
乱我心者，今日之日多烦忧。
长风万里送秋雁，对此可以酣高楼。
蓬莱文章建安骨，中间小谢又清发。
俱怀逸兴壮思飞，欲上青天揽明月。
抽刀断水水更流，举杯消愁愁更愁。
人生在世不称意，明朝散发弄扁舟。', '弃我而去的，昨天的时光已不可挽留；扰乱我心的，今天的日子又有许多烦忧。长风万里送走秋雁，面对这样的景色正可以在高楼上痛饮。你的文章有蓬莱阁的气象、建安的风骨，其间谢朓又清新秀发。我们都怀有飘逸的兴致、雄壮的思绪飞扬，想登上青天去揽取明月。抽刀去砍水，水反而流得更急；举杯消愁，愁反而更愁。人生在世既不能称心如意，不如明天就披散头发，泛一叶小舟而去。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 281, '下终南山过斛斯山人宿置酒', 'tangshi-ts-3', '暮从碧山下，山月随人归。
却顾所来径，苍苍横翠微。
相携及田家，童稚开荆扉。
绿竹入幽径，青萝拂行衣。
欢言得所憩，美酒聊共挥。
长歌吟松风，曲尽河星稀。
我醉君复乐，陶然共忘机。', '傍晚从青山下来，山间的月亮一路随着我归来。回头望望走过的山路，只见苍苍茫茫横着一片青翠的山色。与友人相携来到田家，孩童为我们打开柴门。绿竹夹着幽静的小路，青藤拂过行人的衣裳。欢谈之间找到了歇息的好地方，姑且举杯共饮美酒。放声长歌吟咏松林的风，唱完时天上银河里的星星已经稀疏。我醉了你也高兴，乐陶陶地把世俗的机巧之心全都忘掉。', 'public-domain'),
  ('tangshi300', 282, '登金陵凤凰台', 'tangshi-ts-178', '凤凰台上凤凰游，凤去台空江自流。
吴宫花草埋幽径，晋代衣冠成古丘。
三山半落青天外，二水中分白鹭洲。
总为浮云能蔽日，长安不见使人愁。', '凤凰台上曾有凤凰来游，凤凰飞去、台子空留、江水自流。吴宫的花草埋没了幽径，晋代的衣冠成了古坟。三山一半落在青天之外，二水被白鹭洲从中分开。总是因为浮云能够遮蔽太阳，望不见长安使人发愁。', 'public-domain'),
  ('tangshi300', 283, '早发白帝城', 'poems-xx3-08', '朝辞白帝彩云间，千里江陵一日还。
两岸猿声啼不住，轻舟已过万重山。', '清晨告别彩云缭绕的白帝城，千里之外的江陵一天就能到达。两岸猿猴的叫声还没停，轻快的小船已驶过万重山。', 'school'),
  ('tangshi300', 284, '夜泊牛渚怀古', 'tangshi-ts-109', '牛渚西江夜，青天无片云。
登舟望秋月，空忆谢将军。
余亦能高咏，斯人不可闻。
明朝挂帆席，枫叶落纷纷。', '牛渚的西江之夜，青天没有一片云。我登船遥望秋月，徒然怀念谢尚将军。我也能高声吟咏，只是这样的人已经听不到了。明天早上就扬帆而去，枫叶纷纷落下。', 'public-domain'),
  ('tangshi300', 285, '月下独酌', 'tangshi-ts-4', '花间一壶酒，独酌无相亲。
举杯邀明月，对影成三人。
月既不解饮，影徒随我身。
暂伴月将影，行乐须及春。
我歌月徘徊，我舞影零乱。
醒时同交欢，醉后各分散。
永结无情游，相期邈云汉。', '花丛中一壶酒，独自饮酒没有亲近的人。举杯邀请明月，对着影子就成了三人。月亮既不懂得饮酒，影子也只是空随我身。姑且伴月与影，行乐要趁春天。我唱歌月亮徘徊，我起舞影子零乱。醒时一同交欢，醉后各自分散。永远结下这无情的交游，相约在遥远的云汉。', 'public-domain'),
  ('tangshi300', 286, '听蜀僧濬弹琴', 'tangshi-ts-108', '蜀僧抱绿绮，西下峨嵋峰。
为我一挥手，如听万壑松。
客心洗流水，余响入霜钟。
不觉碧山暮，秋云暗几重。', '蜀地的僧人抱着绿绮琴，从西边的峨嵋峰下来。为我挥手一弹，像听到万壑的松涛。客子之心被流水般的琴声洗净，余音融入霜天的钟声。不知不觉碧山已暮，秋云暗了好几重。', 'public-domain'),
  ('tangshi300', 287, '怨情', 'tangshi-ts-232', '美人卷珠帘，深坐颦蛾眉。
但见泪痕湿，不知心恨谁。', '美人卷起珠帘，久坐皱眉。只见她泪痕沾湿，却不知她心里怨恨的是谁。', 'public-domain'),
  ('tangshi300', 288, '淮上喜会梁州故人', 'tangshi-ts-144', '江汉曾为客，相逢每醉还。
浮云一别后，流水十年间。
欢笑情如旧，萧疏鬓已斑。
何因不归去，淮上有秋山。', '我曾在江汉一带做客，每次相逢都醉着回去。像浮云一样分别之后，流水般的十年过去了。欢笑的情谊还如旧日，稀疏的鬓发却已斑白。为什么不回去呢，因为淮上有秋山可赏。', 'public-domain'),
  ('tangshi300', 289, '郡斋雨中与诸文士燕集', 'tangshi-ts-25', '兵卫森画戟，宴寝凝清香。
海上风雨至，逍遥池阁凉。
烦疴近消散，嘉宾复满堂。
自惭居处崇，未睹斯民康。
理会是非遣，性达形迹忘。
鲜肥属时禁，蔬果幸见尝。
俯饮一杯酒，仰聆金玉章。
神欢体自轻，意欲凌风翔。
吴中盛文史，群彦今汪洋。
方知大藩地，岂曰财赋强。', '卫兵林立，画戟森然，宴饮的寝室里凝聚着清雅的香气。海上的风雨袭来，池阁之间逍遥自在、一片清凉。烦闷的疾病近来将要消散，嘉宾又坐满了厅堂。我惭愧自己居处高显，却未能看到百姓安康。道理通了是非就自然排遣，性情通达就连形迹也忘了。荤腥鲜美的食物正逢时禁，好在蔬菜瓜果还能请大家品尝。低头饮一杯酒，抬头聆听金玉般的美文。心神欢畅身体自然轻快，真想凌风飞翔。吴中之地文史兴盛，众多才俊如今济济一堂。这才知道大藩之地，岂止是财物赋税强盛而已。', 'public-domain'),
  ('tangshi300', 290, '初发扬子寄元大校书', 'tangshi-ts-26', '凄凄去亲爱，泛泛入烟雾。
归棹洛阳人，残钟广陵树。
今朝此为别，何处还相遇。
世事波上舟，沿洄安得住。', '凄凄然地离开亲爱的人，飘飘荡荡驶进烟雾之中。我这是要乘船回洛阳去的人，耳边还萦绕着广陵树影传来的残钟声。今天在这里与你分别，何处才能再相逢。世事就像波涛上的小船，顺流逆流哪里能停得住。', 'public-domain'),
  ('tangshi300', 291, '寄李儋元锡', 'tangshi-ts-203', '去年花里逢君别，今日花开又一年。
世事茫茫难自料，春愁黯黯独成眠。
身多疾病思田里，邑有流亡愧俸钱。
闻道欲来相问讯，西楼望月几回圆。', '去年花开时与你相逢又分别，今日花开又是一年。世事茫茫难以预料，春愁黯淡、独自成眠。身体多病、思念田园，县里有流亡的百姓、愧领俸钱。听说你要来看望我，我在西楼望月、月已圆了几回。', 'public-domain'),
  ('tangshi300', 292, '寄全椒山中道士', 'tangshi-ts-27', '今朝郡斋冷，忽念山中客。
涧底束荆薪，归来煮白石。
欲持一瓢酒，远慰风雨夕。
落叶满空山，何处寻行迹。', '今天郡斋里清冷，忽然想起山中修行的朋友。他在山涧底下捆些柴草，回来煮那白色的石头为食。我想带着一瓢酒，远道去慰问这风雨的夜晚。可落叶铺满了空旷的山野，到哪里去寻找他的踪迹呢。', 'public-domain'),
  ('tangshi300', 293, '赋得暮雨送李胄', 'tangshi-ts-145', '楚江微雨里，建业暮钟时。
漠漠帆来重，冥冥鸟去迟。
海门深不见，浦树远含滋。
相送情无限，沾襟比散丝。', '楚江笼罩在微雨里，正是建业敲响晚钟的时候。江面漠漠、船帆沉重，天色冥冥、鸟儿迟归。海门深远望不见，水边的树木远远含着水汽。相送的情意无穷无尽，泪水沾湿衣襟，比散乱的雨丝还多。', 'public-domain'),
  ('tangshi300', 294, '送杨氏女', 'tangshi-ts-31', '永日方戚戚，出行复悠悠。
女子今有行，大江溯轻舟。
尔辈苦无恃，抚念益慈柔。
幼为长所育，两别泣不休。
对此结中肠，义往难复留。
自小阙内训，事姑贻我忧。
赖兹托令门，任恤庶无尤。
贫俭诚所尚，资从岂待周。
孝恭遵妇道，容止顺其猷。
别离在今晨，见尔当何秋。
居闲始自遣，临感忽难收。
归来视幼女，零泪缘缨流。', '整天都在悲戚，出行又是那么遥远。女儿今天要出嫁，要逆着大江乘轻舟而去。你们自幼丧母，我抚育思念，更加慈爱温柔。妹妹是你这做姐姐的抚养大的，今朝分别，两人哭个不停。面对此情我心中郁结，可女儿应当出嫁，难以再留。你从小缺少母亲的教诲，侍奉婆婆让我担忧。好在托身到好人家，但愿能受到信任体恤，不致有什么过失。安贫节俭本是我所崇尚的，嫁妆哪里需要置办周全。要孝顺恭敬，遵守为妇之道，仪容举止都要合乎规矩。离别就在今晨，再见你不知是哪个秋天。平日闲暇时还能自我排遣，临到别时这感情忽然难以收住。回来后看着小女儿，眼泪顺着帽带直往下流。', 'public-domain'),
  ('tangshi300', 295, '长安遇冯著', 'tangshi-ts-28', '客从东方来，衣上灞陵雨。
问客何为来，采山因买斧。
冥冥花正开，飏飏燕新乳。
昨别今已春，鬓丝生几缕。', '客人从东方来，衣上还带着灞陵的雨痕。我问客人为何而来，他说要为开山采薪来买斧头。花在幽暗中正开着，燕子翩翩飞舞，雏燕刚刚育出。上次分别到如今已是春天，你两鬓又添了几缕白发呢。', 'public-domain'),
  ('tangshi300', 296, '夕次盱眙县', 'tangshi-ts-29', '落帆逗淮镇，停舫临孤驿。
浩浩风起波，冥冥日沉夕。
人归山郭暗，雁下芦洲白。
独夜忆秦关，听钟未眠客。', '落下风帆停泊在淮水边的城镇，停船靠近一座孤零零的驿站。浩浩荡荡的风掀起波浪，天色昏暗太阳沉入暮色。人们回到山边的城郭，暮色四合；大雁飞落芦洲，一片银白。孤独的夜里思念着秦关故土，我是个听着钟声难以入眠的旅人。', 'public-domain'),
  ('tangshi300', 297, '东郊', 'tangshi-ts-30', '吏舍跼终年，出郊旷清曙。
杨柳散和风，青山澹吾虑。
依丛适自憩，缘涧还复去。
微雨霭芳原，春鸠鸣何处。
乐幽心屡止，遵事迹犹遽。
终罢斯结庐，慕陶直可庶。', '终年在官署里拘束，出到郊外才感到清晨的空旷清朗。杨柳在和风中舒展，青山使我的思虑淡泊下来。依着树丛正好独自歇息，沿着山涧信步又归去。微雨笼罩着芬芳的原野，春鸠在何处鸣叫。我喜爱幽静，屡屡停下脚步，可公务在身行迹还是匆匆。终究要辞官在此结庐而居，仰慕陶渊明大概能够相近。', 'public-domain'),
  ('tangshi300', 298, '滁州西涧', 'poems-xx3-17', '独怜幽草涧边生，上有黄鹂深树鸣。
春潮带雨晚来急，野渡无人舟自横。', '我独爱涧边幽静的青草，岸上有黄鹂在深树中鸣叫。春潮带着夜雨来得急，荒野渡口无人，小船自在地横着。', 'school'),
  ('tangshi300', 299, '与高适薛据登慈恩寺浮图', 'tangshi-ts-23', '塔势如涌出，孤高耸天宫。
登临出世界，磴道盘虚空。
突兀压神州，峥嵘如鬼工。
四角碍白日，七层摩苍穹。
下窥指高鸟，俯听闻惊风。
连山若波涛，奔凑似朝东。
青槐夹驰道，宫馆何玲珑。
秋色从西来，苍然满关中。
五陵北原上，万古青濛濛。
净理了可悟，胜因夙所宗。
誓将挂冠去，觉道资无穷。', '塔势如从地下涌出，孤高耸立在天空。登临其上仿佛超脱了尘世，石阶盘旋在半空。高耸挺拔压着神州大地，峥嵘险峻如同鬼斧神工。四角遮住了太阳，七层高塔逼近苍天。往下看去指点高飞的鸟，俯首倾听惊风的声响。相连的群山如同波涛，奔涌而来好似朝东而拜。青槐夹着驰道，宫馆是多么玲珑。秋色从西边而来，苍茫一片布满关中。北原上的五陵，万古以来都是青蒙蒙的。清净的佛理全然可以领悟，胜妙的因缘是我素来所信奉的。我发誓要辞官而去，以觉道为依托，受益无穷。', 'public-domain'),
  ('tangshi300', 300, '白雪歌送武判官归京', 'tangshi-ts-46', '北风卷地白草折，胡天八月即飞雪。
忽如一夜春风来，千树万树梨花开。
散入珠帘湿罗幕，狐裘不暖锦衾薄。
将军角弓不得控，都护铁衣冷难著。
瀚海阑干百丈冰，愁云惨淡万里凝。
中军置酒饮归客，胡琴琵琶与羌笛。
纷纷暮雪下辕门，风掣红旗冻不翻。
轮台东门送君去，去时雪满天山路。
山回路转不见君，雪上空留马行处。', '北风卷地而来，白草都吹折了，塞外八月就飞起雪花。忽然像是一夜之间春风吹来，千树万树梨花盛开。雪花飘进珠帘沾湿罗幕，狐皮袍不暖、锦被也显薄。将军的角弓冻得拉不开，都护的铁甲冷得穿不上。沙漠纵横着百丈坚冰，愁云惨淡凝结万里。中军帐里摆酒饯别归京的客人，奏起胡琴、琵琶和羌笛。傍晚大雪纷纷落在辕门外，风扯着红旗冻得不能飘动。我在轮台东门送你离去，走时雪已铺满天山路。山回路转，看不见你的身影，雪地上只留下马蹄的印迹。', 'public-domain'),
  ('tangshi300', 301, '轮台歌奉送封大夫出师西征', 'tangshi-ts-45', '轮台城头夜吹角，轮台城北旄头落。
羽书昨夜过渠黎，单于已在金山西。
戍楼西望烟尘黑，汉兵屯在轮台北。
上将拥旄西出征，平明吹笛大军行。
四边伐鼓雪海涌，三军大呼阴山动。
虏塞兵气连云屯，战场白骨缠草根。
剑河风急雪片阔，沙口石冻马蹄脱。
亚相勤王甘苦辛，誓将报主静边尘。
古来青史谁不见，今见功名胜古人。', '轮台城头夜里吹起号角，轮台城北的旄头星坠落。插羽毛的紧急军书昨夜越过渠黎，单于已经到了金山西边。从戍楼上向西望去，烟尘一片昏黑，汉朝兵马驻扎在轮台北面。上将手持旄节向西出征，天刚亮就吹笛出发、大军开拔。四边擂鼓震得雪海翻涌，三军齐声呐喊使阴山动摇。敌营兵气连云屯聚，战场上白骨缠着草根。剑河风急雪片大，沙口石头冻硬，马蹄都冻得脱落。亚相为国勤劳，甘心吃苦，发誓要报答君王、扫清边尘。自古以来青史留名谁没看见，如今你的功名将胜过古人。', 'public-domain'),
  ('tangshi300', 302, '走马川行奉送封大夫出师西征', 'tangshi-ts-44', '君不见走马川行雪海边，平沙莽莽黄入天。
轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。
匈奴草黄马正肥，金山西见烟尘飞，汉家大将西出师。
将军金甲夜不脱，半夜军行戈相拨，风头如刀面如割。
马毛带雪汗气蒸，五花连钱旋作冰，幕中草檄砚水凝。
虏骑闻之应胆慑，料知短兵不敢接，车师西门伫献捷。', '你没看见吗，走马川在雪海边奔流，平沙莽莽一直黄到天边。轮台九月夜里狂风怒吼，满川碎石大如斗，随风满地乱滚。匈奴那边草黄马正肥，金山西边望见烟尘飞扬，汉家大将向西出师。将军夜里不解金甲，半夜行军戈矛互相碰撞，风头如刀把脸割得生疼。马毛带着雪，汗气蒸腾，五花马、连钱马转眼就结成冰，营幕中起草檄文，砚水都冻凝了。敌军听说过这些应当心惊胆寒，料想他们不敢短兵相接，我们就在车师西门等着献捷报吧。', 'public-domain'),
  ('tangshi300', 303, '寄左省杜拾遗', 'tangshi-ts-104', '联步趋丹陛，分曹限紫微。
晓随天仗入，暮惹御香归。
白发悲花落，青云羡鸟飞。
圣朝无阙事，自觉谏书稀。', '我们并肩快步走上红色的台阶，分属不同官署、相隔在紫微省左右。早晨随着天子的仪仗入朝，傍晚沾着御香归来。白发的人悲叹花落，望着青云羡慕鸟飞。圣明的朝廷没有缺失之事，自己觉得进谏的奏书也少了。', 'public-domain'),
  ('tangshi300', 304, '奉和中书舍人贾至早朝大明宫', 'tangshi-ts-185', '银烛朝天紫陌长，禁城春色晓苍苍。
千条弱柳垂青琐，百啭流莺绕建章。
剑佩声随玉墀步，衣冠身惹御炉香。
共沐恩波凤池上，朝朝染翰侍君王。', '银烛照着通往宫中的长路，禁城春色在拂晓里一片苍茫。千条弱柳垂在青琐门外，百啭流莺绕着建章宫飞鸣。剑佩之声随着走上玉阶的脚步，衣冠上沾染着御炉的香气。一同沐浴凤池上的恩波，天天执笔侍奉君王。', 'public-domain'),
  ('tangshi300', 305, '逢入京使', 'poems-cz7-16', '故园东望路漫漫，双袖龙钟泪不干。
马上相逢无纸笔，凭君传语报平安。', '向东望着故乡，路途遥远漫长，两只袖子沾满泪水，擦也擦不干。在马上与你相遇，没有纸笔写信，只好请你捎个口信，告诉我的家人我一切平安。', 'school');
